window.__D("text/imrei-bina/c005",{"p":[[1700400353,"שרש ומקור להמשכת כללי' החכמ' הזאת אינו אלא שיהיה מציאת אותה החכמה בעולם וכאשר יומשך ממקור המשפיע כל החכמות המציאה של חכמת הרפואה בעול' נק' המשכה זו המשכה פרטי' וכן כאשר יומשך המציא' דחכמת התכונה בעולם המשכה אחרת היא ואמנם הגם שנק' פרט לגבי מקור שממנו טבע כל מיני מציאות חכמה בעולם אבל כאשר נמשך מציא' חכמת הרפואה הרי היא נק' מקור לפרטיו' השכליי' והחלוקי' שנמצאו בה לכל משכיל ומחדש בה וכן חכמ' התכונה נק' מקור כללי להפרטיו' שכליי' שמתחדשין בה כו' וכמ\"כ אדם שלם בכל חכמ' כחכמ' שלמה הרי נק' מיני החכמו' שמשפיע בשם נתיבות פרטיי' והמה כלליי' כ\"א כולל כמה מיני שכליי' כו' ועד\"ז יובן בל\"ב נ\"ח דציצית שע\"ז נא' וזכרתם את כל מצות כו' לפי שהוא בחי' נתיבות חכמ' עלא' שכולל כל פרטי חכמ' אלקי' שבכל מצוה ומצוה כידוע דטעמי מצות שרשם בח\"ע דרך פרט וכללות ההמשכה שזהו הנק' מקורם הנעלם הן ל\"ב חוטי' דציצית שזהו בחי' המשכו' מקיפי' במוחין ד\"ק שהוא ח\"ת וכן בח\"ע דאבא וז\"א כו' שהוא עוטה אור כשלמ' רק שהטלית מקיף כללי והחוטין שע\"ג כנף נק' נתיבות כמשל המשכות מציאות חכמ' כנ\"ל ולכך שקולה מצות ציצית כנגד כל המצות עד שיזכרו על כל כו' וזהו למעלה מבחי' מקיפים דמוחין דאו\"א דז\"א בד' בתים שהוא רק חו\"ב שבא בגלוי להתחלק בחו\"ג כו' משא\"כ בטלית שמקיף ראשו וכללותו כמ\"ש לבושיה כו' וזהו ענין ד' גוונין שבד' כנפות כנ\"ל שנק' הארת פנים שהאור המאיר בפנים הוא בא מבחי' פנימי' ועצמות דוקא כידוע בענין חכמת אדם תאיר פניו כמו צהבו פניו דר' כו' שלא ע\"י הסתר מסך ולבוש הנ\"ל ומלבד זה הנה הוא אור והמשכ' היולית שמחמתו וכחו ישכיל בכל חכמה כשרואה פני רבו כמ\"ש במ\"א בענין יראה כל זכורך כו' (וז\"ש יאר ה' פניו פני אדם עלאה ותתאה עד הפנים דמל' שמקבל ד' גוונין העליונים בד' כנפות כמ\"ש ופרשת כנפיך כו' כנף גי' ק\"נ והן ק\"נ נהורין דאבא כו' וזהו כמשל הנ\"ל וד\"ל) (וזהו וראיתם בראיה דתכלת בחי' פני אדם קדמאה דכליל ג' גוונין חג\"ת שהוא כשנחלק לג' קוין אח\"כ כמשל הנ\"ל בהמשכת כמה מיני חכמות כו' וד\"ל) ולפ\"ז עוטה אור כשלמה וכן לבושיה כתלג כו' אינו בבחי' הסתר וצמצום כלבוש דשערות בת\"ד אלא אדרבה הוא תוקף האור העצמי המאיר באור הפנים כו' (וכמ\"ש במ\"א בענין כתנות אור באלף בתורתו של ר\"מ כו' שנק' זיהרא עלאה כו' וזהו היפוך המבואר למעלה בלבוש דמחשבה להיות רק הארה דהארה כו' דא\"כ אין זה דומה לענין הארת פנים דיאר ה' פניו כו' ומ\"ש עוטה אור כשלמה לבוש היינו שיאיר ממנו הפנימית דוקא וכמו פנימיות אור התורה כנ\"ל וד\"ל) והנה שרש ענין הד' כנפות מבואר למעלה שהן ד' גוונין עליונים כו' והענין הוא שזהו ד' מדרגות דחגת\"ם שהן ד' פנים שבמרכבה פני אריה פני שור הוא בחי' חו\"ג ופני נשר בחי' ת\"ת ופני אדם הוא בחי' מל' דכליל כולהו וז\"ס ופני אדם לארבעתן וזהו בחי' מל' דאצי' שנק' אדם תתאה שרוכב על המרכבה דבריאה וכמ\"כ המל' מרכבה עלאה דז\"א כו' עד מרכבתא עלאה דאדם קדמאה שהוא בחי' אור אבא ומרכבה שלו בחי' חגת\"ם דז\"א כו' ופני אריה בחי' חסד דז\"א כו' (שהמדות הן כמו בחי' מרכבה לגבי השכל שבראש כמו שהדבור נק' מרכבה לגבי המדות כענין רוכב על כרוב קל כו' והדבור שהוא במל' אדם תתאה נק' רוכב על המרכבה דבריאה כמ\"ש במ\"א בפי' א\"ד בם סיני כו') והנה התכלת היה מלמעלה כדי שיראו אותו וזכרתם היינו בחי' המל' דהתכלת דומה לים כו' כנ\"ל ומשום דאבא יסד ברתא דנעוץ תחילתן בסופן וסופן כו' שהוא פני אדם קדמאה דאור אבא כו' ע\"כ אמר וראיתם אותו וזכרתם את כל מצות ה' שזהו מצות המלך דבחי' המל' וממילא יזכרו על ידה על כל מצותי משום דשקולה מצות ציצית כנגד כל המצות ולהבין כ\"ז הנה הקדמה הכללית לכ\"ז הוא"],[1700400354,"הידוע בענין אם אין חכמ' אין יראה אם אין יראה אין חכמ' דידוע הקושי' ממה יתחיל מאחר דיראה בלא חכמ' אינו כלום וכן חכמ' בלא יראה כו' אך התירוץ הוא כידו' שיש ב' מיני יראה יראה תתאה ויראה עלא' וכמ\"ש בכ\"מ דחילו ורחימו רחימו ודחילו ויראה עלא' היא חכמ' כמ\"ש הן יראת ה' היא חכמה שאין לחלק ביניהם כלל והענין הוא כח מ\"ה בחי' בטול ואין בעצם כידוע במדריגת משה שא' ונחנו מה מ\"ה בעצם משום דגלוי אא\"ס תמיד בחכמ' שנק' אין בעצם וזהו ג\"כ בחי' יראה עלא' שהוא בטול במציאו' ממש מצד העצם כמשל הנכנס בהיכל המלך שנופל עליו הביטול בעצם מצד עצמו' המלך משא\"כ קודם שנכנס שלא ראהו עדיין שגם שמתבטל נק' בטול היש מעצמותו לבד כו' ובטול היש נק' יראה תתא' שהוא בבחי' חיצוניו' לבד ולא בפנימיותו כלל אך ורק מה שמתבטל מישותו וגסותו לגמרי הנק' השתחווא' חיצוניו' או הכנעה חיצוניו' כשהיא מכל וכל בחיצוניו' עכ\"פ ה\"ז נעשה בחי' כלי מוכן לבחי' בטול במציאו' דהא בהא תליא משו' דנעוץ תחלתן בסופן דוקא והטעם הוא כידוע בענין יהב חכמתא לחכימין דהקושי' ידוע לחכימין כבר מה צורך ליתן להם חכמה אך הענין הוא דחכימין היינו שיש בהם בחי' בטול היש בתכלית ולפי ערך בטול ישותם שהו' העדר והרגש זה בעצמם למהות ודבר כלל מכל וכל לפי ערך זה יוכלו להיות כלי מוכן לקבל בחי' ח\"ע שהוא גלוי אלקות מלמעלה למטה באור ח\"ע מצד העצם שזהו בחי' בטול פנימי ועצמי דכח מ\"ה דמשה הנ\"ל וכל מי שיש בו חכמה בחי' בטול היש יותר יותר יומשך בו ח\"ע בטול הפנימי דבחי' ראיה כו' וד\"ל וכנראה בחוש בכל טועמי טע' אור החכמ' אלקית שלא תשכון בגסי הרוח שעושי' מזה יש ודבר לעצמם וכמ\"ש ראית איש חכם בעיניו תקוה לכסיל כו' וכמ\"ש במ\"א ובזה יובן התירוץ על מאמר דאם אין יראה כו' בב' אופנים או דקאי בח\"ע וירא' עילא' דכתיב הן יראי ה' היא חכמ' שהוא כח מ\"ה ובטול בעצם הנ\"ל או דקאי בירא' תתאה ומשום דנעוץ תחלתן בסופן ע\"כ אם אין יראה תתאה שנק' פתח אין ח\"ע ולהיפך אם אין חכמ' ממילא מובן שאין יראה תתאה משום דלא יהב ח\"ע רק לחכימין שהוא בחי' ירא' תתאה וזהו כל שאין ירא' חטאו קודמת לחכמתו שהוא יראה תתאה השתחוואה ובטול היש לבד אין חכמתו בטול בעצם מתקיימת כלל מטעם הנ\"ל וד\"ל וכמ\"כ יובן למעלה בבחי' מל' דאצי' שנק' אדם תתאה היא יראה תתאה וח\"ת חכמ' בסוף שמתפשט בבי\"ע הרי שרשה באדם קדמא' הוא אור אבא חכמ' בראש שנק' יראה עלא' כנ\"ל דנעוץ תחלתן בסופן דוקא כנ\"ל ולכך ע\"י מצות ה' שנק' מצות המלך יראה תתאה דתכלת בחי' המל' יזכרו על כל מצותי שנמשך מרצון העליון ע\"י חכמ' בראש שהוא אור אבא דאבא יסד ברתא כו' כנ\"ל וד\"ל:\n(ז) <b>והנה</b> מעתה יש להבין בחי' ד' גוונין חגת\"מ הנ\"ל הרי התכלת שהוא בחי' המל' נק' אשא אוכמא ע\"ש שמכלה ומבער הרע דנוגה כמ\"ש בזהר וחג\"ת הן חוטי הלבן שהוא בחי' אש' חוורא (וכנ\"ל בענין נר ה' נשמת אדם וכענין אש שחורה ע\"ג אש לבנה באור תורה) והענין מבואר משום דהמל' יורדת למטה בסתר המדרגה עד היכלות דנוגה לברר ברורי' דרפ\"ח כו' וכמ\"ש טרף נתן וכו' ותתן טרף רפ\"ח ע\"ה כו' וענין הברו' הזה ידוע להיו שעה\"ד טו\"ר כשבא בבחי' נוגה מתערב ביותר והוא עד גסות השמרים דקליפת נוגה דעשי' שרובו רע כידוע וכאשר נגלה אור האלקי שם ביתר מכפי הצמצום וההסתר דשם מתבטלים ממציאותם ונכלל הטוב שבהם בקדושה האלקי' ודוגמא לדבר זה מה שאמרו למה צדיקי' דומין בפני השכינ' כנר בפני האבוק' לפי שנמש' הניצו' אח' מקו' ושרש מחצבו כו' כך גם נצוצות דקדוש' שנפלו בקליפו' כאש' יבא גילוי מקור חוצבם שהוא אור האלקי יומשכו ממילא ויבדלו מתערובת הרע והמות שנדבקו שם וראי' לזה מהעלא' ניצוצות נשמות הגרים שנשקעו בעכו\"ם ונגררים ונמשכים ממילא אחרי ה' בהגלו' נגלות אור האלקי בצדיק גמור שבדור כמו באהברהם אע\"ה שנק' אב המון גוים מפני שנשמתו הי' מרכבה לאלקים חיים בגילוי"],[1700400355,"אור ממש וכמשמעות הכ' שקראוהו בני חת נשיא אלהים אתה בתוכינו ולכך נלוו אליו גרים רבים כידוע בהנפש אשר עשו בחרן ובענר אשכול וממרא ושאר חניכיו ג' מאות וכו' וכדוגמא זו יובן למעלה בבירור רפ\"ח כו' שנפלו בתערובת דנגה דעשי' ודיצירה כו' שמתבררי' ועולין בבחי' בטול והתכללות בשכינ' שהוא בחי' שם ב\"ן המברר כו' וכידוע בענין המאמר דבהמה רבה רביעא על אלף טורין דמגדלין בכל יומא כו' שז\"ש מצמיח חציר לבהמה גי' ב\"ן ששתת לון בגמיעא חדא כו' והיינו בחי' בירור הטוב שבנגה שגדל בכל יום וכמו יוצר משרתים שבכל יום נברא ומתחדש שנק' חציר ועולה ונכלל בפי בהמה בחי' ב\"ן המברר כו' ויובן זה ע\"ד הנ\"ל בבירור נשמות הגרים וכה\"ג יובן בענין התכל' שנק' אשא דאכיל ושצי כו' שזהו לא לכלות לגמרי כאש השורף אלא להעלות ולכלול בו ולהמשיך אליו מה שהוא ממקורו כשלהב' המושך את הניצוץ אליו שזהו כמו כח המושך שיוכלל ויבוטל מציאותו בו (כאש שע\"ג המזב' שנק' אכילת מזבח והוא כמו ארי' דאכיל קורבנין ונק' אש של מעלה והעשן היוצא הוא הפסולת הנבדל לחוץ להיכלות החיצונים כך והר סיני עשן לא שכלה לגמרי אלא שנבדל הטוב והרע מתבער ממיל' כמ\"ש ז\"ל וירד ירדה שנאה לעכו\"ם והי' חירות ממה\"מ כו' ובאמת אין כל זה בסגנון א' עם התכלת דתכלת אכיל ושצי ממש לכלות ולבער הרע לגמרי שלא יוכל לעלות לקדושה האלקית וכמו שידוע דהתכלת הוא אור מקיף שמסמא עיני החיצונים (וכידוע בענין מה שהוכו בסנוירים ע\"י אלישע דוקא שהוא בחי' המל' דבריאה כשבאה לברר בנוגה לכך עשה גדולות ונפלאות הרבה ואליהו גימ' ב\"ן הוא למעלה בבחי' האצילות וא' ויהי נא פי שנים ברוחך כו') משא\"כ אש שלמעלה שעל המזבח שנק' אריה דבחי' חסד דימין רק שהוא חסד שבגבורה דאריה גימ' גבורה וכאריה לטרוף טרף רפ\"ח כו' וכן בהמה רבה דאכיל ושתית לון בגמיעא כו' ומכ\"ש הרי סיני עשן דזהו אור תורה שמברר לעה\"ד כו' שכל זה רק בירור הטוב מן הרע ולא לבער ולכלות את הרע לגמרי רק דוגמא לזה יש גם בתורה למשמאילים בה שהוא סמא דמותא להמית ולכלות את הרע ממש כשלומד שלא לשמה וכמשל רפוא' סם כשאינו ראוי ימיתנו וכך יש שפע אלקי' שלראוי זה תחי' אותו ולמי שאינו ראוי דבר זה עצמו ימיתנו וכמו שאמר נגוף ורפוא נגוף למצרים ורפוא לישראל בשפע והמשכה אח' דוק' כמ\"ש במ\"א וכן עמוד הענן שהלך מאחריהם היה אור לישראל וחשך למצרים כו' וכל זה אינו כענין התכלת דאכיל ושצי לרע דוקא שנק' אש השורף ומכלה הוא אש האלקי הנק' אש אוכלה כו' ואין דוגמא אמיתית לזה רק מה שאנו רואי' בכעס כנחש של יראי אלקי' על הרשעי' שנק' חיויא דרבנן וכמו שיש דבר זה בכ\"א לפי ערכו בהתקשרותו בתפל' בעבודה שבלב כשרואה דבר רע שעושה הרשע במרד ומעל כזנות וחילול שבת בפרהסיא וכה\"ג שיכעוס בכעס וחרון אף למאד וכן כשיראה ע\"ע הדבר המנגד ביותר לנקודת יהדותו יכעוס ויקצוף וחמתו בער' בו עד להשחית ממש כו' וד\"ל) אך הנה ענין חוטי הלבן שבציצית הוא בחי' חג\"ת הן הכוללים כל המצות שע\"ז א' שקולה מצות ציצית כו' ולא מצד ראי' דתכלת כפשט הכתוב שאין ראיה זאת רק לקבל עליו עמ\"ש לבער הרע כו' אך העיקר הוא מה שיסתעף מזה אח\"כ והוא מ\"ש למען תזכרו ועשיתם כל מצותי שעיקרן רק בבחי' תוס' אורות בכלים דאצילות למעלה ולא ענין בירור בטו\"ר כלל כי באצילות אין שם גם בחי' מקור לרע שנק' עולם התיקון כידוע וע\"כ ענין המצות דשם שנק' מצותי דוקא אינו רק להוסיף אור בכלים והוא להמשיך בחי' תוס' אור מן עצמות המאציל בנאצלים כו' ותוס' גלוי אור זה בא מבחי' הפנימיות ועצמות דוקא וזהו שרש ענין היופי העליון דהארת פנים העליונים [דא\"א או דא\"ק או דאור אבא שכל זה נק' אדם קדמא' וז\"א נק' יעקב שע\"ז אמ' שופרי' דיעקב מעין שופרי' דאדה\"ר כו' כידוע באד\"ר] דהנה ידוע בענין יאר ה' פניו אליך מלמעלה למטה שז\"ש ב\"פ הנך יפה כנ\"ל אך הנה מ\"ש הנך יפה הא' שהוא מלמטה למעלה בד' גוונין דכנ\"י באתדל\"ת"],[1700400356,"כו' גם זה בא מלמעלה למטה וכמ\"ש במ\"א בענין אין אשה אלא ליופי שהיופי שלה נמשך מהארת פנים דא\"א כמשל הגדול שמסתכל בקטן שיתחזק עי\"ז ויאירו פניו כו' (וכענין הקבלת פני רבו שמאור פני רבו יאירו פניו בהלכה כו') כמ\"ש עיני כל אליך כו' אשא עיני כו' (וכמ\"ש במ\"א בענין עיניך יונים כו' עיניו כיונים כו') והנה פי' פניו לשון רבים שכלול מג' גוונין חג\"ת (וכידוע בענין תקון הז' ואמת שהוא הארת תרין תפוחין כו') (וכמו חכמת אדם תאיר פניו בשעת מ\"ת דפנים בפני' דיבר כו') וזהו יאר ה' פניו אליך שזהו אסתכלות' דא\"א בזו\"נ שנק' אדם תתאה וכמ\"ש מה שמו מה שם בנו שהוא ז\"א ונק' ישראל או כנ\"י וזהו אליך דוק' וכל זה הוא ע\"י תוס' האור באו\"כ דאצילות שכלול בכל המצות העליונות שנק' מצותי כו' והוא בחי' חוטי הלבן שממשיכים תוס' אור להאיר לבד ונק' אשא חוורא כנ\"ל ולע\"ל יתגלה אור זה למטה בבי\"ע ועכשיו אין זה האור רק למעלה באצילות וכמ\"ש במ\"א וד\"ל: וזהו ג\"כ שרש ענין עוטה אור כשלמה ואח\"כ נוטה שמים כיריעה דהנה פי' שמים אש ומים יחד והוא בחי' ז\"א דאצילות שכלול מחו\"ג דאו\"א מוחין דאבא מסט' דחסד בחי' מים ומוחין דאימא בחי' הגבורות (וכמו מוח החכמה קר ולח ומוח הבינה חם ויבש והתכללתו שניהם נמשך ללב שהן בחי' המדות דז\"א למעלה) וזהו נטוה שמים כיריעה שכל בנין ז\"א באו\"כ פנימיי' ומקיפים שנק' יריעה (וכמ\"ש בזהר ע\"פ בורא השמים ונוטיהם דאתקין תדיר כו' וכמו כונן שמים בתבונה שהן מוחין דמדות דז\"א שנמשך ממוחין דאו\"א כידוע) ותחלה כיריעה שהוא בחי' המקיף ודוקא אחרי שעוטה אור כשלמה תחלה כו' [הענין יובן עפ\"י המבואר במ\"א בענין הפרסא כו' בין כתר לחכמה כמ\"ש והבדילה הפרוכת בין קדש דחכמ' כו' ותרגום פרכת פרסא כו' והוא בחי' קרומא דאוירא כו' וזהו המקרה במים עליותיו כו' ולמעלה מזה בבחי' לבוש חשמ\"ל העליון שבין עצמות המאציל לנאצלים וז\"ש לבושי' כתלג חיוור חיוור דוקא והוא הטלית הלבן שע\"ז א' עוטה אור כשלמה כו' אינו ענין הצמצום דישת חושך סתרו שהרי זה נק' אור ולא אור שיצא מתוך החושך כנ\"ל אלא כפשוטו שהאור הוא עוטה כשלמה שנמצ' השלמ' כולו אור בהיר כמו לבושי' כתלג כו' ואח\"כ נוטה שמים כיריעה כו' ויש כאן ג' מדרגות אור מים רקיע ויובן זה עפ\"י המבואר במ\"א בענין ג' מיני בחי' פרסא שבג' מדרגות הללו דאור מים רקיע דפרסא הא' הוא מ\"ש עוטה אור כשלמה והוא לבוש חשמ\"ל דלובן העליון שמלבש ועוטה אור להתלבש בו והוא להיות שאין ערוך כלל בין העצמות לנאצלים ע\"כ בהכרח שיתעטף ויתכסה באור שנק' לבוש ולא להסתיר עצמו אלא שעל ידו יאיר אור בנאצלים שיהי' בחי' אור של תולדה אבל לא מתוך ההעלם כמסך ממש (וביאור זה ידוע ע\"פ הנותן שלג כצמר כמו השלג שעיקרו חסדים רק שמתכווץ ותחלתו מים וסופו מים רק שדרך הלוכו מתכווץ שיהא מתקבל למקבל כך חוטי לבן דצמד דטלית להשפיע ממקיף העליון וז\"ש לבושי' כתלג חיוור כו' במצות ציצית שעי\"ז יזכרו על כל מצותי שהן בחי' ארחין ושערות שנק' שער רישי' כעמר נקא) והב' בחי' הפרסא שנק' קרומא דאוירא בגלגלתא דא\"א שע\"זא המקרה במים כו' שבחי' מים הוא אור העצמי שנמשך לגלוי והתפשטות למטה כמים כו' וז\"ש והחכמה מאין כו' הוא הנק' אור כמ\"ש יהי אור אך כשמתפשט מאין ונמשך בבחי' יש כמ\"ש מאין תמצא נק' מים ושם יש בחי' פרסא מפסיק כו' ומשם נמשך להיות נוטה שמים כיריעה שהוא הרקיע דאגלידו מיא כו' כמ\"ש במ\"א בענין אור מים רקיע והוא בחי' התכללות אש ומים המוחין דאו\"א בבחי' מקיף לז\"א כנ\"ל ולזאת אם לא שעוטה אור כשלמה בתחלה לא הי' אור נמשך בנאצלים וממילא לא הי' נמשך אור ומוחין לז\"א בבחי' מקיף דיריעה אח\"כ וד\"ל] והנה ע\"ד הנ\"ל במאציל ונאצלים נאמר עוטה אור כשלמה ונוטה שמים כו' כך בין האצילות לבריאה שאין ערך ביניהן יותר משאין ערך האצילו' לגבי המאציל כו' ע\"כ גם שם אמר עוטה אור כשלמה והוא מה שארז\"ל שהקב\"ה מתעטף בטלית כו' ובחי' ד' כנפות"],[1700400357,"שלו שמשם נמשך למל' המקיפים דל\"ב נ\"ח שע\"ז א' ופרשת כנפיך כו' וכן מ\"ש בבגדו בה ומ\"ש שארה כסותה כו' וכן אשר תכסה בה קאי בטלית דכנ\"י כו' ואח\"כ נוטה שמים כיריעה שהוא בחי' הפרסא שבין אצילות לבריאה כו' וכמ\"ש לעולם ה' דברך נצב בשמים כו' וכמו ועל ראשי החיות רקיע כו' והכל ענין א' ע\"ד הנ\"ל רק ששם הוא מן המאציל לנאצלים וכאן הוא מאצילות לבריאה (אך ענין התכלת שמברר לעה\"ד טו\"ר לא יתכן בטלית דמאציל):\n(ח) <b>ובכל</b> זה יובן שרש ענין ועשו להם ציצית על כנפי בגדיהם כו' ואח\"כ ונתנו על ציצית הכנף פתיל תכלת וראיתם אותו כו' דהנה יש להבין מ\"ש בזכירה ראשונה מצות הוי' ובזכירה שני' אמר את כל מצותי דוקא כנ\"ל להיות ידוע בפי' מצות הוי' שהוא בבחי' המל' דוקא דהוי\"ה הוא בבחי' ז\"א ומצות הוי\"ה הוא בחי' המל' שמקבלת מז\"א ונק' מצות המלך (וביאור הדבר ידוע דפי' הויה היינו באצילות עצמו בבחי' או\"כ כמו חסד דרועא ימינא כו' וכך רמ\"ח פקודין רמ\"ח אברין דז\"א אבל מצות המלך שבבחי' מל' דאצילות זהו בחי' המשכות המצות בגלוי בעלמא דאתגליא מאין ליש כמו עד\"מ ציווי המלך בדבור לזולתו כמו מדוע כו' את מצות המלך והן מצות עליונות שבאין בגלוי אור למטה ע\"י בחי' המל' נק' מצות המלך) ואמנם בזכירה שני' א' כל מצותי למעלה גם מבחי' הוי\"ה דז\"א שהוא מדבר בבחי' אור עצמות המאציל שממשיך תוס' אורו בע\"ס דאצילות דהיינו בבחי' נר\"נ דז\"א ובמוחי דאו\"א ג\"כ כו' והענין הוא רק להמשיך תוס' אור בכלים ובבחי' נר\"נ יש כלים עד בבחי' א\"א וע\"י שזהו כמו בחי' חי' יחידה למטה שאינם מוגבלים בכלים כנ\"ל באריכות וזהו ידוע דבכל מקום שיש בחי' אור וכלי שייך שם ענין תוס' אור בכלי או מיעוט האור בכלי שזהו הנק' בחי' קטנות המוחין וגדלות המוחין כו' וכמו\"כ במדות דז\"א וגם במוחין דאו\"א שמקבלין מב' מזלות דנוצר ונקה כידוע מאחר שהמה מוגבלים בכלי ג\"כ כמו חכמה מוחא ונק' מוח אבא כו' [וע\"ד שאנו רואים באדם למטה שלפי שכלו יהולל איש שיקטן שכלו מצד קוטן הכלי בימי קטנותו ויגדל שכלו בגדלות הכלי כשיגדל וכן במדותיו יגדלו לפי ערך גידול שכלו מעט מעט כו' כמו מבן ו' שנה עד י\"ב שנה שהוא בקטנות המוחין והמדות ומי\"ג שנה עד בן כ' שנה הוא בא לכלל גדלות השכל שבמדות עד שיגדל יותר גם בעצם כח שכלו בהיותו בן ע' זקן שקנה חכמה והרי יש תכלית הקטנות בהיותו בן ו' עד תכלית הגדלות כו'] והיינו לפי שמשכן אור השכל במוח והמדות בלב כו' משא\"כ בבחי' חי' יחידה כמו הרצון והתענוג בלתי מוגבלים בכלי כלל שאין להם משכן בכלי וחומר מוכן בכלי הגוף כנ\"ל באריכות ע\"כ לא יגרעו ולא יתוספו לעולם מצד ריבוי או מיעוט הכלים מאחר שאינם מוגבלים בכלי הגוף כלל כנ\"ל [ומה שאנו רואים בחי' גדלות וקטנות גם ברצון ועונג שהקטן רצונותיו לדבר קטן הערך ורצון הגדול לדבר גבוה יותר וכן הענג שהקטן מתענג מדברים פחותים משא\"כ כל שיגדל יותר יותר יתענג בדברים גדולים יותר הנה זה הרצון הוא הנולד מן השכל או המדות שבלב שלפי שכלו כך יולד לו רצון והקטן שכלו קטן רצון הנולד לו קטן ביותר וכשיגדל שכלו יגדל תולדות הרצון עמו וכן במדותיו שעיקרם הרצון שנק' רעותא דלבא תלי לפי ערך גידול המדות באוי\"ר והתפארות ונצוח אם בענינים קטני' או בגדולים ואם בהשכלות ועיון עמוק או שלא בהשכל וכו' אבל הרצון עצמו שלמעלה מן השכל אין בו שינוי מבחי' קטנות לגדלות מאחר שאין טעם לרצון כלל א\"כ מה שינוי ימצא בו בין גדלות השכל לקטנות השכל וראיה לזה מרצון הטבעי שבטבעיות המדות שאין בו שינוי כלל להיותו למטה מן השכל ואין לו חיבור ושייכות עם השכל וכמו מי שהוא בטבעו כעסן או להיפך רחמני או אכזרי או פחדן או להיפך ע\"פ שבקטנת ימיו לא יוכל לשלוט בהם כלל ובגדלות שניו ישלוט להפוך בהם"],[1700400358,"מקצה לקצה אין זה היפוך בעצם כלל רק שליטה לבד והטבע שהיה לו בקטנותו נשאר לזקנותו בעצם בלתי שינוי כלל וממילא הרצון שנולד מצד טבעו אין בו שינוי כלל וכמו בטבע שלמטה מן השכל כך בעצם אור הרצון והעונג שלמעלה מן טבע השכל שבמוח ומדות שבלב כו' אין בהם שינוי מקטנות ימיו לגדלותו] ומ\"ש אך בצלם יתהלך איש שצלם הן מקיפים דחי' יחידה שיתהלך איש להיות בו תוס' אור מן ההעלם לגלוי כמו זקן שקנה חכמה הרי נמשך תוס' אור מן ההעלם לגלוי כמו זקן שקנה חכמה הרי נמשך תוס' כח מהעלם כח המשכיל וכך יוכל להיות תוס' גלויי אור בעצם הרצון או מיעוט כו' כנראה בחוש שגם נקודת עצם הרצון יש בו מיעוט וריבוי לעתים שונים וכמ\"ש במ\"א בענין עת רצון כו' כל זה אינו רק באופן הגלוי לבד אבל לא גידול בעצם או מיעוט בעצם כגידול שכל ומדות ומיעוטם לפי הכלי וז\"ש יתהלך לבד שזהו כניסת הצלם מהעל' לגלוי ובהשוואה א' כו' כנ\"ל וראי' לדבר זה שהרי גם עצם הרצון לטוב בבחי' מוטבע כמו מי שטבע שכלו לטוב ומדותיו לטוב כאוהב לאהובו כנפשו שעצם רצונו מוטבע לטוב עליו וממילא יטה שכלו לזכות עליו לחפות כו' ולהיפך לשונאו כו' ולכך השוחד יעור עיני חכמים מפני הטיית הרצון הטבעי למצוא שכל לזכות ולכך לא היו יושבין בסנהדרין רק זקנים שטבעיות שלהם נכנע ובטל בתכלית לגבי השכל שלא יגבר הטיית טבע הרצון להפוך השכל שלא כמשפט התורה כו' [ואע\"פ שיש חכמים להטיב ולהרע לזכות ולחוב זה לא יצא ממשפט התור' כמו שכל מטה כלפי חסד כב\"ה זהו מצד אור נשמתו בהשגה שבחכמ' שבתורה מבחי' חסד שבחכמ' ולא בטבע האנושית כלל] ולפ\"ז טבע הרצון המוטבע שלמטה מן השכל הוא עצמו טבע הרצון הפשוט ועצמי שלמעלה מן השכל ומ\"ש כי האדם עץ כו' קאי במדות ושכל השייך למדות לבד שיתכן בו לשון גידול ולא ברצון ועונג שלמעלה מבחי' אדם וגם לא בטבעיות המדות בטבע תולדתו הגם שמבואר במ\"א בענין עיבור יניקה כו' שמתגדלין טבעי המדות אבל בעצם מהותם הראשון אין שינוי כלל כנ\"ל (ולפ\"ז מ\"ש באד\"ז ז\"א בע\"י עצמו אחיד שלמעלה ממזלו' דאו\"א כו' היינו בקטנות שבו דוקא שהוא טבעי המדות שאין בכח זקן שקנה כו' לשנותם כו' כמ\"ש במ\"א) והנמשל מזה יובן למעלה מעלה בהיות ידוע שאור הרצון העליון הוא הנק' כתר הממוצע כו' ויש בזה ב' מדרגות כמו בחי' חי' יחידה למטה כנ\"ל באורך שלמעלה מבחי' נר\"נ כו' (כידוע בענין נקוד' ספי' פרצוף הרי ג' מדרגות נקודה אינו כלול מי' והוא בחי' הכתר דכתר וזהו בחי' א\"ק רצון לרצון כו' אדם דבריאה וספי' כלול מי' הוא בבחי' א\"א וע\"י שנק' אדם דיצי' וכמו ק' ברכות שהן ע\"ס דכתר כל א' כלול מי' ופרצוף בז\"א ואו\"א שבו שנק' שם הויה י\"ה חו\"ב שבמדות כידוע ונק' אדם דעשי' שהאור בכלים מכלים שונים בג' מיני כלים פנימי ואמצעי וחיצון כידוע) והנה כדי להמשיך בחי' תוס' אור מעצמות המאציל בבחי' מוחי' חדשים לאו\"א זו\"נ שכולל שם הוי\"ה יו\"ד חכמה כו' צריך לעורר בחי' הארת פנים העליונים דא\"א וע\"י שיומשך על ידם מעצמות המאציל אור חדש כי הם בחי' ממוצעים ועי\"ז יהיה תוס' אור בנר\"נ דז\"א כו' כידוע וד\"ל וזהו פי' את כל מצותי לשון צוותא וחיבור והוא מה שיש התחברות מעצמות אא\"ס בנאצלים בתוס' אור חדש תמיד ע\"י בחי' א\"א וע\"י שנק' ממוצע כנ\"ל נק' מצותי דוק' שזהו למעלה ממצות הוי\"ה מאחר שזה האור בא מן העצמות ע\"י המקיפים דכתר שלמעלה מבחי' הכלים לא נק' שם הוי\"ה עדיין כנ\"ל ושם הוי\"ה הוא בבחי' כלי לאור כידוע שזהו בבחי' זו\"נ ואו\"א יו\"ד אור אבא כו' כנ\"ל וד\"ל אך א\"כ יש להבין מ\"ש בסוף דברי הפ' אני הוי\"ה שמתצמצם בשם הוי\"ה דוקא ותחלת דבריו למען תזכרו כו' את כל מצותי שלמעלה משם הוי\"ה כנ\"ל הענין הואט דהגם שמבואר למעלה בפי' אני שהוא ידוע והכל מכירים אותו ובאמת הרי לית מחשבה תפיסא ביה ומופלא"],[1700400359,"ונעלם מכל רעיון כו' הנה פי' הב' באני להיפך שהוא לשון נסתר בעצם כאדם שאומר אני מי שאני כמו מי שאנכי דלא אשתמודע כלל דאני לשון גילוי הוא במדבר לזולתו לומר לו אני מצוה אותך וכה\"ג שזהו בבחי' המל' שנק' אני כמו אני מדבר בצדקה כו' ואני דכתר עליון להיפך הוא שהוא מדבר בדרך נסתר לעצמו אני מי שאני כו' וכתיב ראו כי אני אני הוא משום דנעוץ תחלתן בסופן וכתר שהוא הרצון הנעלם בא לגלוי בדבור וזהו אני ראשון בחכמה בראש ואני אחרון בחכמה בדבור כו' בהשווא' א' ממש משום דלית מאן דתפי' בי' כו' ע\"כ ראשון דחכמה עלאה ואחרון דח\"ת שוין וכמו את השמים כו' אני מלא בהשוואה א' משום שנסתר מהכל בשוה ע\"כ התלבשותו בהעלם בכולם בשוה כידוע וד\"ל וזהו אני ה' פי' אני הנסתר הוא שנתצמצם בשם ה' בחכמה יו\"ד עד ה\"א אחרונה בחי' מל' בשוה מראש לסוף כי הוא למעלה משם הוי\"ה כנ\"ל וכמ\"ש היש הוי\"ה בקרבינו אם אין דכתר עליון שהוא אני רק שמתצמצם מאין להיות אני הוי\"ה בבחי' או\"כ דאו\"א וזו\"נ כנ\"ל וזהו אני הוא אשר נקראתי בשם הוי\"ה להיוטת בבחי' המשכות או\"כ כו' ואין זה בא רק ע\"י סיבת מעשה המצות למעלה דוק' והוא במה שהקדי' בתחלה ועשיתם את כל מצותי דוקא שהוא תוס' אור מעצמות המאציל ע\"י אין דכתר הממוצע להיות אני הוי\"ה בתוס' אורות בכלים כו' וד\"ל:\n(ט) <b>והנה</b> אחר כל הנ\"ל יתפרשו סדר והמשך הפסוקי' דפ' זאת והוא במ\"ש וראיתם אותו דהיינו ראיית התכלת שהוא בחי' שם ב\"ן המברר ברורים דנגה דאכיל ושצי מצד גלוי אלקות דמלכות שמים בבחי' מצות מהלך שום תשים עליך מלך כו' שנק' יראה תתאה בטול היש כו' אז וזכרתם את כל מצות הוי' שהוא מצות עליונות שבבחי' או\"כ דז\"א דאציל' שנק' רמ\"ח אברי' דמלכא ובמצות המלך בעלמא דאגליא כנ\"ל והיינו ג\"כ כענין תכלת ע\"ג הלבך דציצית שזהו אש שחורה ע\"ג אש לבנה דכתיב בתורה מימינו אש דת כו' ואח\"כ זכירה שני' למעלה יותר והוא בבחי' עצמות אור המאציל להמשיך אור חדש תמיד בנאצלים שז\"ש כל מצותי כלומר התחברות אור עצמותו בנאצלים שאין זה אלא ע\"י שמחה וטוב לבב דוקא והיינו אחר ראי' דתכלת דוקא אז יבא לזכירה שני' זאת משום דנעוץ סופן בתחלתן כו' כנ\"ל ע\"כ אחר שביער וכילה את הרע דאתם זונים כו' ע\"י התכלת בבחי' בטול דיראה תתאה כנ\"ל וכמ\"ש וראיתם וזכרת' כו' ולא תתורו כו' מצד עוצם היראה ופחד אלקים בבחי' היש לגמרי דודאי את זלע\"ז כו' ולפ\"ע התגברות אור דקדושה האלקית בבחי' בטול ושקיעה בלב כו' כך לפ\"ע ידחה יניקות החיצונים ויגרשו מן הלב וכמ\"ש ולא תתורו אחרי לבבכם אע\"פ שכבר נמשכו אחריהם כו' משום דכהמס דונג כו' דזהו כל עיקר ענין התכלת דמבער הרע כנ\"ל ואז דוקא יגיע לבחי' שמחה וטוב לבב בזכירה שני' שזהו כל עיקר ענין חוטי הלבן שבציצית רק להוסיף ולהרבות אור חדש מעצמות אור העליון שבעצמות המאציל באצילות עצמו שאין שם ברורי' דעה\"ד לבער ולברר הרע כו' רק חדות ה' במקומו בשמח' ושעשועי אור העצמות והן בחי' הארת פנים כנ\"ל והן ג' מדרגות חג\"ת פני אריה פני שור כו' והגם שלמעלה מעל' לפני האצילות אין שם בחי' מרכבה דפני ארי' כו' רק הענין הוא בדומה לזה בבחי' וענין התכללות דג' גוונין כו' שזהו עד רום המעלות כידוע. דגם בבחי' ע\"י וא\"א שנק' אדם דיצי' נק' מרכבה לבד לגבי מל' דא\"ס שבא\"ק וכה\"ג שנק' אדם שרוכב על הכסא וכמו וע\"י יתיב וכרסוון כו' יש בחי' מרכבה לו ועליו נאמ' לבושי' כתלג חיוור כו' שהן חוטי הלבן כו' כנ\"ל כך הוא עד"],[1700400360,"רום המעלות וד\"ל (וזהו למען תזכרו למען דבר זה דוקא שהוא ראיה דתכלת בזכירה א' שהוא לבער הרע כו' הנק' טהרה כנ\"ל והיא המביאה לידי קדושה דוקא וזהו למען תזכרו ועשית' כל מצותי שקדשנו במצוותיו בבחי' קדושת העצמו' ממש וכנ\"ל בפי' והייתם קדושים לאלקיכם דוקא כמ\"ש כי קדוש אני למעלה מקדושתכם שע\"י המצות שזה ב' מדרגות זו למעלה מזו תחלה ועשיתם כל מצותי בקדושה שע\"י מצותי כנ\"ל ואח\"כ והייתם קדושים בקדושת עצמותו כו' ושרש הדברים כמ\"ש במ\"א בשרש ההפרש בין טה\"ע לטה\"ת דבחי' אור מקיף הכללי שמקיף לד' עולמות דבי\"ע שע\"ז אמ' אני ראשון ואני כו' אני מלא כו' תפיס בכ\"ע ולית מאן כו' נק' טה\"ת והוא ענין מח' הכללית שסובב הכל בסקירה א' מראש לסוף כא' כו' ונק' סופא דמח' כשבאה בבחי' מקיף להגביל דבר פרט כו' אבל טה\"ע הוא עצמות אור א\"ס כמו שהוא ושמו בלבד שאין זה רק גלוי אור עצמו שלא נק' מקיף למקיף עדיין וזהו עוטה אור שנק' אור פשוט בהיר בעצם רק עוטה אור זה כשלמה להיות בבחי' מקיף למקיף כו' וזהו כשלמה כמו לבושי' כתלג חיוור כו' והוא הנק' קדוש ונמשך משם להיות בחי' מקיף שנק' שמים שז\"ש נוטה שמים כיריעה שמקיף לכולם בשוה וכמו וכעצם השמים לטוהר לשון טהר יומא שנטהר מן החושך והסתר וזהו כמו התכלת שדומה לרקיע דוקא כו' שנק' טהרה כנ\"ל שמביא לקדושה הוא עצמות האור כלבנת הספיר שבהיר בעצם מתחלת הוייתו ואמנם כשעלה בתחלת הרצון קדם התחלה לסוף והוא מ\"ש עוטה אור כו' ואח\"כ נוטה שמים שהוא אחר הצמצום כו' אבל אח\"כ נהפוך הוא דסוף מעשה עבמ\"ת פי' לפני תחלת המחשבה למעלה גם מבחי' עוט' אור כו' דהיינו לעורר בעצמו לתחלת הרצון כו' כנ\"ל (בשער הק\"ש בסי' מ\"ג) וזהו שע\"י ראיה דתכל' שז\"ש נוטה שמים בחי' סופ' דמחשבה שבסוף מעשה לברר הרע עולה במ\"ת ולמען זה דוקא תזכרו כו' והיית' קדושים בקדושת עצמו דעוטה אור כו' דהיינו למעלה מתחלה וסוף כמ\"ש שם ובזה יתורץ ענין התכלת איך ימצא בטלית דלבושיה כתלג כו' עד מל' דא\"ס כי גם שם בחי' טה\"ת נק' תכלת שע\"ג הלבן דעוטה אור שבעצמות ממש כי' וד\"ל וזהו אני הוי\"ה אלקיכם דוקא דמה שמאין האמיתי שבעצמות ממש נעשה אני בחי' טה\"ת להיות אני ראשון כו' הוא ע\"י סוף מעשה דנשמות בגופים שמבערים הרע בבחי' יראה דמל' שנק' אלקיכם דוקא וכמ\"ש סוף דבר כו' את האלקים ירא כו' כי זה כל האדם כל רבוי לרבות גם מה שלמעלה מבחי' האדם הידוע שהוא שיעור קומת א\"ק עד גם בבחי' מל' דא\"ס ומטעם הנ\"ל וד\"ל. ומעתה יש להבין בשרש ענין התורה בפנימיות וחיצוניות הנ\"ל ותחלה יש להקדים ביאור מארז\"ל ג' נובלו' הן נובלו' חכמה של מעלה תורה ונובלות בינה ש\"מ שכינה וממה שנובלות בינה ש\"מ שכינה יובן עד\"ז ענין נובלות חש\"מ תורה והענין ידוע דחו\"ב שלמעלה הוא בחי' חו\"ב דאצילות עד חו\"ב דא\"א וע\"י עד חו\"ב דא\"ק ולמעלה מעלה בבחי' חו\"ב שבעצמות כו' ופי' נובלת הוא בחי' חיצוניות הנובל בבחי' השפעה למקבלים כי הפנימית לא יוכל לבא בבחי' השפעה ולזה גזר אומר דתורה זו הנגלית לנו אחר שבאה בבחי' השפעה למקבלים בהכרח ששרשה מנובלות חש\"מ דמפנימי' חש\"מ איך יומשך למטה לבע\"ג כו' אמנם לפ\"ז איך יתכן לומר כך במאמר שני דנובלות זה ודאי מחיצוניות אור שפע דבינה ש\"מ שבא למקבלים זהו שכינה שלמט' שבאה להיות ראש ומקור לבע\"ג למטה בג' עולמות בי\"ע כידוע וזה א\"א לומר דשכינה הוא בחי' המל' שהיא מע\"ס דאצילות דאיהו וחיוהי חד בבחי' א\"ס ולא בבחי' חיצוניות ונובלות אך הנה ידוע שבבחי' מל' בשפעה אור בבי\"ע יש בזה עצמו בחי' א\"ס כמ\"ש בס\"י מכאן ואילך צא וחשוב עד אין שיעור כו' הרי אין שיעור לאופני הצרופים דאותיות"],[1700400361,"הדבור דמל' וכמו שמתחדש בכל יום מע\"ב לאין שיעור וא\"כ אנו רואים דגם בשעורי' וגבולים דמל' שנק' חשבון כמ\"ש עיניך ברכות בחשבון לפי שהצרופי' במספר יבאו להתהוות הבע\"ג מאין ליש כידוע יש בזה עצמו מכח פנימית דאור א\"ס שבלתי גבול כו' וא\"כ למה א' דנובלות בש\"מ שכינה אם שרש המל' מחיצוניות בינה (עד\"מ צרופי הדבור שבאין במספר כמספר אותיות המח' המגבילים ההשגה דבינה שנק' חיצוניות ונובלות בש\"מ כו') אלא ודאי נשבח קאמר דנובלות זו יש בזה מכח הפנימית יותר וכידוע הכלל דמה שבא למטה מטה ביותר מזה מוכח ששרשו הגבה למעלה יותר וכך הוא ענין נובלות חש\"מ תורה לשבח קאמר דבנובלו' שהוא בחי' חיצוניות אור אבא שבאה למטה בשעורים וגבולין במצות כנ\"ל בענין דקדוקי סופרים כמו ח' חוטין בציצית ולא יותר וכה\"ג בתפילין ד' בתים וכו' זהו מורה על היות שרש אור דתורה מבחי' פנימית אור א\"ס שבח\"ע ביותר וז\"ש הנסתרות לה' אלקינו בחי' פנימיו' התורה שארוכה מארץ מדה כנ\"ל והנגלות לנו חיצוניות התורה שבאה אלינו בגבולין ושעורין כו' אין הכונ' בזה שיש הבדל ביניהן במעל' רק אדרב' שקולין כא' במדרג' א' ממש כמ\"ש דאוריית' סתים וגליא לפי שבחי' פנימית דא\"אס שבפנימית ח\"ע הוא שבא בהתלבשות בחיצוניות ונובלות חש\"מ זו תורה הנגלית לנו ולבנינו וזהו פי' הפשוט דהנסתרו' עצמן של ה' אלקינו ששם התורה בלי מדה כנ\"ל הן הנגלות לנו בשיעורים וגבולין והכל א' ולא ב' תורות הן ואין ביניהן חילוק כלל וכלל וד\"ל ושרש הדברים ידוע דבחי' פנימית אבא הוא בחי' פנימי' ע\"י לעול' כמ\"ש בע\"ח והיינו הנסתרו' לה' כו' בחי' סתים שבתור' שארוכ' מארץ מדה כנ\"ל בבחי' פנימית אא\"ס ממש משום דבבחי' פנימית יסוד אבא שם מאיר אור פנימית יסוד ע\"י שבו גלוי אור פנימית דעצמות אא\"ס מסתיים שם והוא בחי' אחרונה שבעצמות כו' שלמעלה מבחי' כלים מגבילים האור כו' ומה שהתורה נתנה לנו בגבולין ושיעורין כו' זהו מבחי' חיצוניות יסוד אבא שבו חיצוניות יסוד דע\"י כו' שבא במדידות אור ושפע כמ\"ש מי מדד בשעלו כו' במאמר קו המדה כך וכך יוכשר ולא כך וכך הוא מבחי' גבורה דע\"י שבחיצוניות יסוד להשפיע בשיעור כו' אבל בפנימיו' יסוד ע\"י ויסוד אבא לא נמדד לשיעורין וגבולין כו' ומה שיבא האור בכלי בהגבלה היינו בזו\"נ ששם נק' מצות הוי\"ה כנ\"ל וזהו מ\"ש הנגלות לנו ולבנינו לנו או\"א ולבנינו זו\"נ שהן נר\"נ ומוחין דאו\"א בחיצוניות השפע שנק' נובלות חש\"מ ונובלות בש\"מ (רק שנובלות חש\"מ תורה בבחי' ז\"א ונובלות בש\"מ שכינה בחי' מל' נוק' דז\"א) ושרש א' לפנימית וחיצוניות הגם שזה בלי שיעור וזה בא בשיעור מטעם הנ\"ל דדוקא הא בהא תליא וזהו מי מדד כו' דהמדידה עצמה מכח פנימית ח\"ע דוקא וכמ\"ש ז\"ל בג' דברים ברא העולם בסופר וספר וספור שהן תשב\"כ ותשבע\"פ שבא בשעור באותיו' בספר כו' ומזה נמשך המדידה בצרופי אותיות די' מאמרות אעפ\"י ששרשו באצילות בבחי' א\"ס למעלה מן המספר מ\"מ מוציא במספר צרופים כו' לג' עולמות בי\"ע בענין נובלות בינה ש\"מ שכינה שזהו ספר וספור וד\"ל (וכל זה יובן מארז\"ל יבא טוב ויקבל טוב כו' יבא טוב זה משה ויקבל טוב זה תורה מטוב זה הקדב\"ה לטובים אלו ישראל כו' וזה פלא גדול לכאורה דמשה כבר קיבל תורה מסיני ואיך יאמר שיבא עוד הפעם לקבל התורה שנק' טוב כו' אך הענין ידוע בענין וזרח השמש ובא השמש כו' דהשמש בשקיעתו למערב יוצא וזורח במזרח והיינו מדרגת משה שהוא בבחי' פנימית אבא לבד כידוע בפי' ונחנו מ\"ה ומדרגת משיח לע\"ל הוא בפנימית ע\"י שלמעל' מן החכמה כמ\"ש והריחו דמורח ודאין ולא למראה עיניו דחכמ' כמ\"ש במ\"א בענין כתר ש\"ט כו' ולפי שפנימית אבא הוא ממש פנימית ע\"י ע\"כ א' יבא טוב זה משה דגם לע\"ל יבא טוב בחי' משה דהיינו הך ממש וכמו השמש שנשקע במערב הוא עצמו שזורח במזרח למחר וידוע דבמשה נאמר כי טוב הוא והיינו בחי' פנימית יסוד אבא שזהו פנימית יסוד ע\"י דבחי' משיח כו'"],[1700400362,"כנ\"ל ואם הי' פנימית התורה נבדל בערך מבחי' חיצוניות התורה במה שבפנימיות ארוכה מארץ כו' משא\"כ בחיצוניות שבאה בגבול דוקא א\"כ תורה זו הנגלית לנו ע\"י משה כמ\"ש תורה צוה לנו משה בין בספר תשב\"כ שנק' מחוקק במדה וגבול ובין בספור בתשבע\"פ כו' איך יאמר בו יבא טוב לקבל פנימית התורה טעמי מצות ע\"י משיח כידוע אלא ודאי מוכרח לומר דפנימיות וחצוניות שבתורה אדרבה במדרגה ושרש וכח א' ממש באו מעצמות אא\"ס כנ\"ל דלכך א' יבא טוב דהכל א' ממש וד\"ל): ולהבין שרש ענין פני נשר הנ\"ל במ\"ש ישאהו על אברתו כו' ואשא אתכם אל כנפי נשרים כו' הנה ידוע בשרש ענין הרחמים שהוא בבחי' קו האמצעי דת\"י שעולה עד קצה העליון יותר מב' הקוין תת\"נ ובג\"ה כו' דהיינו שעולה עד בחי' כתר שבכתר שאין ב' הקוין הנ\"ל מגיעים לשם ושם הוא בחי' פנימית ועצמות אא\"ס דזהו עיקר יתרון מעלה בריח התיכון דקו האמצעי שמבריח מן הקצה לקצה יותר מב' הקוין כידוע (וביאור הדברים ידוע שברחמים יש ב' מדרגות א' שבא מדה זו דרחמים בשעור וגבול כמו ב' המדות דחו\"ג שבב' הקוין שהוא לעשות לפנים משה\"ד מצד הרחמים שכולל ב' הקוין דחו\"ג יחד ואמנם גם זה יש לו גבול דיותר מכפי המדה שיחייב מדת הדין ויגבר ביותר על החסד לא יועיל מדת הרחמים ויוגבל אורו באופנים פרטיים ע\"פ הוראת אור השכל דחו\"ב שרש הג' מדות וזהו בחי' ת\"ת קו האמצעי דישראל בחי' ז\"א שנק' רחמים סתם (ונק' וי\"ו אות אמת דכולל חו\"ג כו') ואמנם בחי' רחמים רבים דא\"א הנק' כתר הוא ברצון שלמעלה מן השכל וכמו ר\"ר העצמיים על עצמותו שלמעל' מטעם ושכל שלא יוגבל אורו במדות דחו\"ג דודאי גם ברצון יש חו\"ג שלמעלה מן הטעם כמו תכלית שנאה דעמלק שלא עפ\"י שכל ותכלית אה\"ר כו' ולכך הרחמים דשם ג\"כ למעלה מהגבל' אבל גם שם יוכל להיות הר\"ר מוגבל מצד כח הדין המגביר ביותר כמו תכלית שנאה שיגבר שלא ירחם לעולם והרי אנו אומרי' ברחמיך הרבים כו' אנכי אנכי הוא מוחה פשעיך כו' משום שיש בזה חילוק מדרגות דהיינו בחי' הכתר וכתר שבכתר דבכתר עצמו יוכל להיו' גם הרחמי' רבים בגבול שלא יאבה סלוח כאשר ירבו לפשוע ביותר מכפי המדה כמו שמצינו בכמה כתובים כו' אך בחי' כתר שבכתר הוא רחמים עצמיי' כאב על בנו ילד שעשועיו כמ\"ש המו מעי לו כו' דגם אם ירבה לפשוע עד שימאס וישנאנו בתכלית יגברו רחמים העצמיי' כו' מפני שנחשב מעצמותו ממש וכמו שע\"ע ירחם לעולם בבלתי שינוי כלל וכלל כו' ובלתי התעוררות כו' וכמ\"כ כתיב טרם יקראו ואני אענה שלא צריך התעוררות כלל כמו שע\"ע ממש כו' לכך בטרם יקראו כבר בצרתם לו צר ממש כמו ילד שעשועיו בטרם יקרא ויצעוק מצערו ירגיש האב ולא ימתין עד שיקראנו וירפאנו ויושיענו מצרתו כו' וכך יובן במ\"ש ואשא אתכם על כנפי נשרים כו' בחי' ר\"ר שבעצמות ממש שזהו בשוה ממש לבחי' עצמותו וזהו ואביא אתכם אלי ממש שזהו יתרון מעלת קו האמצעי דרחמים שעולה בבחי' העצמות ממש שהוא בחי' כתר שבכתר כנ\"ל וזהו מ\"ש ופני נשר לארבעתן כמו פני אדם לארבעתן כו' ומטעם זה וד\"ל ומה שאמר ישאהו על אברתו וכן על אברתו וכן על כנפי כו' דזהו עליית קו האמצעי למעלה מעלה בעצמותו כנ\"ל ומה שמבריח לקצה התחתון היינו כנשר יעיר קינו על גוזליו כו' שמתפשט ר\"ר העצמיים הנ\"ל למטה מטה גם להעלות משאול תחתית ממש כו' דהא בהא תליא דלםי ערך עומק רום למעלה כך עומק תחת להרים בחי' שפלות היותר למטה כו' כמ\"ש במ\"א וד\"ל]:"],[1700400363,"<b>בציצית</b> דוקא ול\"ב חוטין הן ל\"ב נ\"ח שבוקעים ויוצאים מהעלם אור המקיף כמ\"ש בפע\"ח ויש להבין תחלת בבחי' המקיף דטלית דהנה כתיב עוטה אור כשלמה נוטה שמים כיריעה כו' וכן מ\"ש לבושיה כתלג חיור כו' ויש להקדים תחלה במ\"ש נעשה אדם בצלמינו כדמותינו למה דוקא באדם הוא בצלם אלקים יותר מכל הנבראים וכן במרכבה פני אדם לארבעתן שכולל כולם כו' ועוד איך שייך לשון צלם ודמות למעלה באלקים חיים שאין לו גוף ולא דמות הגוף כו' וכתיב כי לא אדם הוא כו' שמושלל מכל תואר ותמונה כמ\"ש כי לא ראיתם כל תמונה כו' ועוד איך א' נעשה אדם בצלמינו שמשמעו שנעשה אדם ונברא מאין ליש בצלמו כו' ואם הוא נברא מאין ליש אין זה בצלמו ממש שהוא ית' בבחי' א\"ס והאדם הוא בע\"ג ותכלית ועוד שגם כל העולמות נבראו מאין ליש ומהו ההפרש של בריאת האדם שהוא בצלמו כו' אך ידוע שהעולמות לא נבראו מבחי' אור עצמותו ית' אלא רק מבחי' אור מעטה לבושיה שנק' הארה דהארה כמ\"ש כי עמך מקור חיים באורך נראה אור פי' נראה אור כמו אור הנכפל הנק' אור של תולדה שמאיר דרך מסך ולבוש כמ\"ש במ\"א אבל נעשה אדם בצלמינו היינו כמו שהוא באור עצמותו ממש וזהו פי' אדם אדמה לעליון וזהו פלא דא\"כ איך האדם בבחי' בע\"ג כו' ועוד דענין צלם ודמות היינו ג\"כ ענין ובחי' הארה דהארה שהצלם ודמות הוא רק בדומה לעצם אך הנה ארז\"ל בעשרה לבושים נתלבש הקב\"ה בחכמה ותבונה ודעת כו' הרי החכמה נק' לבוש לבד לגבי העצמות וכמ\"ש בראשית ברא ות\"י בחוכמתא ובראשית נמי מאמר הוא והוא הנק' בזהר מחשבה עלאה שלמעלה מהתחלקות המחשבה דחכמה בל\"ב ויאמר כו' שנק' ל\"ב נ\"ח כמו משל מח' הכללות באדם שנק' מחשבה אחת שכוללת ומקפת כל ריבוי התחלקות המחשבה שבאים בדבור כו' וזהו בחי' מחשבה אחת שצופה וכו' שנסקרים הכל בסקירה א' מראש כל ההשתלשלות עד סופו שנק' מקיף כללי שמקיף לאבי\"ע כידוע וגם על בחי' מח' אחת זו הכללות א' לית מחשבה תפיס' בך כלל אפי' מחשבה הקדומה זו כו' לפי שעצמות אא\"ס פשוט בתכלית למעלה מבחי' מחשבה שהוא מציאת דבר ויש כו' ע\"כ לית מחשבה תפיסא בך כלל כנל רק שנמשך ומתלבש ומתצמצם להיו' בתפיסת מחשבה כו' להיות בבחי' מקיף כללי שאין פי' מקיף וסובב יתכן רק בבחי' שפע אור מן העצמות שמה שבלתי יתקבל באו\"פ מקיף וסובב הכל כא' אבל בבחי' אור עצמותו ממש כמו שהוא לבדו מרומם ומתנשא מימ\"ע לא שייך ענין מקיף לעולמות גם בדרך כללות אם לא ע\"י צמצום גדול וד\"ל וזהו פי' עוטה אור כשלמה פי' עוטה שהוא מעטה ומלביש ומעלים את האור העצמות בבחי' בבחי' שלמה ולבוש שאור זה מאיר דרך העלם הלבוש והשלמה שאם היה מאיר האור כמו שהוא בעצם בלי צמצום והעלם בלבוש ושלמה לא היה מציאת ההשתלשלות כלל וזה שכתוב ישת חשך סתרו שקודם לגלוי האור היה חשך סתרו וכתיב מגלה עמוקות מיני חשך וענין חשך זה היינו בחי' העלם של האור העצמי כמו שהוא מתעלם בלבוש הנק' שלמה והוא לבוש החשמ\"ל העליון ואח\"כ יבקע ויוצא האור מן ההעלם הזה שבלבוש ושלמה ונק' אור זה הנולד בשינוי המהות מתוך ההעלם בשם הארה דהארה כמ\"ש באורך נראה אור כנ\"ל ובכלל הוא בחי' הקו\"ח שאחר הצמצום הראשון שנמשך ומאיר בע\"ס שאבי\"ע וז\"ש כי עמך מקור חיים שמתעלם תחלה בבחי' ההעלם בלבוש ואח\"כ יבקע אור בגלוי מתוך ההעלם והיינו נראה אור כו' ואח\"כ נוטה שמים כיריעה וכידוע בענין אור מים רקיע שאחר גלוי האור מן ההעלם נמשך ויורד כמים ונעשה רקיע כו' וביאור הדברים הנה יובן עד\"מ מבשרי אחזה כו' שאנו רואים בשכל וחכמה שבאדם שנק' אור כידוע ואור זה דחכמה אינו נק' אור בגלוי שכל המושג רק כשתחלה הי' בבחי' ההעלם והחושך שלמעלה הרבה מגלוי אור שכל וסברא הנק' מחשבה סתימאה כו' ואחר ההעלם דמ\"ס יצא לאור וגלוי שכל והתחכמות וכמ\"ש והחכמה מאין תמצא כידוע וד\"ל:"],[1700400364,"(יא) <b>ויובן</b> זה בתוס' ביאור ממה שאנו רואים בבחי' מח' המלבשת את אור השכל שנק' מחשבה תתאה (בחי' חשמ\"ל התחתון דחיצוניות בינה והוא בחי' רקיע דאגלידו מיא שז\"ש נוטה שמים כיריעה וכמשי\"ת דהנה באמת העיקר הוא אור השכל כמו שהור בעצם שנק' התחכמות בדבר מה והמחשבה מצד עצם מהותה רחוקה מאד מערך השכל כי תמיד משוטטת המחשבה גם בדברים פשוטים מאד שבלא דעת כלל עד שנעשית בכח המדמה לבד כידוע וא\"כ מדוע אנו רואים שא\"א שיבא בלבו אור שכל וסברא רק ע\"י התלבשות באותיות המחשבה דוקא גם שנק' מחשבת שכל בעיון אין זה רק בהיות העיון השכלי בא באותיות וצרופים שונים במחשבה הגשמית שחושב כל ענינים פשוטים דוקא כו' ואז דוקא יאיר אור השכל בהשגה גמורה עד שיוכל להשפילה ולהורידה לתנוק קטן או להתעפעל ממחשבה זו במדות שבלבו לאהוב ולירא כו' וכ\"ז שלא בא אור השכל בהעלם אותיות המחשבה פשוט' עדיין אינו משיג השכל בטוב ולא נק' השגה כי ההשגה נק' תפיסה כתופס דבר מה במציאתו ובלתי אותיות המח' נשאר אור השכל בהעלמו בלא גילוי אור במציאות שכל וסברא כלל ונמצא שאעפ\"י שהצרופים במחשבה הן כמו לבוש מסתיר למהות עצם אור השכל מ\"מ היא הנותנת דוקא שעי\"ז יבא אור השכל לגילוי השגה גמורה א\"כ בהכרח שיש במח' ב' הפכים העלם וגלוי כו' וזהו כמו המסך כשהוא עב וגס יחשיך האור לגמרי אבל אם אינו גס רק שהוא מעלים קצת לעצם האור ובוקע האור מתוך נקבי אריגת המסך אזי יוכל האור לבא למקבלים לגלוי משא\"כ בלתי המסך לא היו יכולים לקבלו כלל וא\"כ ההעל' של האור במסך הוא שעושה סיבת גילוי כרואה בכלי ההבטה וכאור השמש בענן דק שעוש' בליטת האור ביותר כמו גלוי גווני הקשת שנראים בענן שלא היו נראים בגוף השמש מצד עוצ' בהירתו כך אור עצם השכל אינו ניכ' ובולט רק ע\"י העלמו בצרופי' של המחשב' שאז יוצא אורו בהשגה גמורה יותר כנ\"ל וכן יוכל לבא בהתפעלות הלב באוי\"ר כנ\"ל אך מ\"מ נק' אור של תולד' בחי' הארה דהאר' ולא אור השכל כמו שהוא בעצם מהותו ואמנם אם לא הי' מתעלם עצם אור השכל בלבוש המחשבה לא הי' יכול כלי המוח להכילו ולהשיגו בהשגה גמורה הנק' תפיסה כנ\"ל כי נשאר בהעלמו העצמי כו' וד\"ל וכמו\"כ יובן במחשבה עלאה שנק' מחשבה סתימאה או מחשבה הקדומה שקודם להתהוות מציאות אור החכמ' והשכל שנק' אין כמ\"ש והחכמה מאין כו' שהוא בחי' החושך וההעלם שקודם לאור כמ\"ש יוצר אור ובורא חושך הרי האור ביצירה וחושך בבריאה כו' והוא בחי' כח ההעלם של אור החכמ' טרם שיצא לגלוי שעי\"ז דוקא יוכל לבא מציאת האור דחכמה בגלוי מאין ליש שנק' התחכמות והבנה כנ\"ל שהוא בחי' חשמ\"ל העליון מאחר שגם החכמה נמצאת במציא' יש מאין הרי בהכרח שהיה האור בהעלם תחלה ומחמת ההעלם דוקא הוא שבא לגלוי אור כו' כמו שאור השכל שבגלוי א\"א לבא חידי השגה גמורה כ\"א ע\"י המחשבה פשוטה שמעלמת לאור השכל ממש כנ\"ל שנק' חשמ\"ל התחתון וד\"ל אך מ\"מ הפרש גדול יש ביניהם שבחי' ההעלם דמחשבה הקדומה שנק' קדמות השכל אינו העלם גמור להעלים ממש רק להיות שהוא כח המשכיל ההיולי שממנו נבקע ויוצא אור מציאת כל שכל וסברא צריך להיות תחלה בבחי' צמצום והעלם האור כדי שמזה דוקא יוכל לבא גלוי אור דחכמה ונמצא הוא עיקר ומקור אור החכמ' כמ\"ש והחכמ' מאין תמצא משא\"כ אותיות המחשב' פשוטה שהיא מלבשת ממש לאור השכל כנ\"ל אבל מאחר שיש בה כח המביא לגלוי אור מן ההעלם שרשה בהעלם דחכמ' עצמה שנק' בשם תעלומו' חכמה או פלאות חכמ' כידוע (וזהו בחי' מחשב' דחצוניו' בינה חשמ\"ל התחתון ששרשו בחשמ\"ל העליון כידוע ומבוא' במ\"א) והנמשל מכל זה יובן למעלה במ\"ש עוטה אור כשלמה כנ\"ל שזה בחי' חשמ\"ל העליון שישת חושך סתרו כו' כנ\"ל להיות ידוע שבחי'"],[1700400365,"עצמות אא\"ס ב\"ב הוא בבחי' אח\"פ בתכלית כו' ויאן ערוך אליו כלל אפי' בחי' מחשבה הקדומה הנ\"ל וכמ\"ש למת\"ב כלל וכנ\"ל וא\"כ מ\"ש ישת חושך סתרו כו' וכה\"ג גם זה הי' ע\"י צמצום אור עצמותו ממש להיות מסתתר בבחי' ההעלם וחשך העליון כמו אתה אל מסתתר והיינו בהתעטף אור העצמי בבחי' מלבוש המכס' ומעלים לגמרי לעצמות אורו שנק' אור א\"ס ממש גם זה צמצום גדול הוא כו' ומבחי' העלם והסתר זה הוא שבוקע ויוצ' האור מן ההעלם וכמ\"ש מגלה עמוקות מני חושך כו' שנק' אור של תולשה ואז נק' מקור להאציל ע\"ס כו' ונמצא מבחי' אור של תולדה זו נאצלו ע\"ס (עד ע\"ס דעשי' כידוע שבין אצילות לבריא' ג\"כ יש פרסא ונק' חשמ\"ל והיינו בחי' כתנות עור שמלביש לזו\"נ דאצילות מתחת רגליהם כו' וכך מבריאה ליצי' ומיצירה לעשי') אך לפ\"ז בחי' צמצום הראשון שלפני הקו\"ח הנק' חשמ\"ל העליון בכלל כנ\"ל הוא כדמיון מחשבה הפשוטה שמעלמת ממש לאור השכל כך נתעטף אור העצמי במלבוש זה הנק' חשמ\"ל כו' ובאמת הרי נק' מחשבה הקדומה שנק' העלם העצמי להיות מקור לגלוי אור דע\"ס שאינו העלם ממש אדרבה בחי' מקור ועצם כנ\"ל וצריך לומר ששניהם אמת דלגבי בחי' עצמות האור דא\"ס נק' העלם ולבוש גמור וכמ\"ש ישת חשך סתרו וכן יושב בסתר עליון (וכמ\"ש במ\"א בענין כי בענן אראה כו' שהוא כמו סמך עגול מכל צד להסתתר בו) ואח\"כ יוצא לאור כמ\"ש כיתרון האור מן החושך וכן מגלה עמוקות כו' ונמצא יש בו ב' הפכים להסתיר ולהעלים ממש ולהיות מזה מקור לגלוי אור שהוא הנק' תעלומות חכמה כנ\"ל והא בהא תליא כנ\"ל במחשבה תתאה כך הוא ממש במחשב' עלאה (וכמ\"ש במ\"א בענין עד הגל הזה כו') וד\"ל\n(יב) <b>אך</b> הנה עדיין יש להבין במ\"ש עוטה אור כשלמ' שמשמעות הפשוט שמעטה אור זה לא שהוא מתעלם ונחשך בהתעטף בשלמה אלא אדרבה שהאור עצמו מעוטה כמו שלמה היינו שמתפשט בהארתו בלבוש שלמה באור בהיר וזך וכמו לבושי' כתלג חיוור שהלבוש לבן וזך כך הוא עוטה את האור עד שמתפשט כשלמה שהשלמ' בהיר' ומלאה אור בהיר' דוקא וכמו שאמ' בתורתו של ר\"מ היה כתב כתנות אור באלף שנקרא זיהרא עלאה כו' לבוש בהיר וזך וזה הרבותא שעוטה את האור לעשותו מאוד כלבוש שלמה כו' וכן נוטה שמים כיריעה שהוא כמו יריעות שלמה שהן בתכלית הלבנונית וזהו היפך ענין הנ\"ל בענין הצמצום דישת חושך סתרו שהוא בחי' ההעלם וההסתר לעצמות האור וכמו באורך נראה אור הארה דהארה כנ\"ל אך הנה באמת שני הפי' אמת בעוטה אור שהאור המאיר מתוך השלמה הוא בוקע ויוצא מתוך העלם ולבוש מכסה השלמה כפי' הא' הא' וגם זה אמת דהאור שבא בהתפשטות כשלמה הוא עצם האור דוקא ואינו בא בבחי' לבוש והעלם כלל כפשוטו כו' ויש להקדים תחלה בשרש ענין התורה דהנה כתיב כי נר מצוה ותורה אור הרי התורה נק' אור בעצם בלתי מלובש בכלי הנר והמצות נק' נר מצוה ואע\"פ שבכל מקום בתורה נאמר התורה והמצוה בענין א' כמ\"ש והתורה והמצוה אשר כתבתי להורותם כו' וכה\"ג מ\"מ ב' ענינים מחולקים המה ולכאורה איך אפשר לחלק ביניהן שהרי כל המצות אינן רק מאשר נמצא כתוב ומפורש בתורה כו' אך הענין ידוע שהמצות הן הבאין ומתלבשי' למטה בבחי' המעשה בפ\"מ וכמבואר במקומו' רבים לשמור ולעשות ושמרתם ועשיתם כו' לעשות את כל דברי התורה הזאת וכה\"ג ופי' לעשות שישראל המה העושין את התורה ע\"י קיום המצות בבחי' עשי' בפ\"מ דוקא אבל שרש בחי' אור דתורה הוא למעלה מעלה כמו שהיא בעצמות אא\"ס שע\"ז אמר ותורה אור פי' אור העצמות ממש רק שבא אור זה ומתלבש בנר מצוה וביאור הדברים ידוע בדרך כלל שיש בתורה עצמה ב' מדרגות פנימיות התורה והחיצונית שלה והוא מ\"ש בזהר דאורייתא סתים וגליא כו' ומבואר זה בכתוב במ\"ש הנסתרות לה' אלקינו"],[1700400366,"זהו בחי' סתים שבתורה שהן בחי' סודות ורזין וטעמי תורה שמוסתר ונעלם בעצמו' אא\"ס ב\"ה והנגלות לנו ולבנינו לשמור ולעשות כו' הוא בחי' הנגלה שבתורה שמתלבש בנר מצוה בחיצוני' שהוא בא לידי קיום המעשה בפ\"מ דוקא והנה ידוע שהתורה נתנה באש שחורה ע\"ג אש לבנה כמ\"ש מימינו אש דת למו ופי' אש לבנה מבפנים הוא בחי' פנימית התורה שהוא מכוסה ונעלם בחיצוניות התורה הנגלית לנו למעשה כו' שנק' אש שחורה והענין הוא דפנימית התורה מאיר שם מבחי' אור עצמות א\"ס ממש וע\"כ נא' בזה ארוכה מארץ מדה ורחב' מני ים שלא יכילנה ארץ ויש ב' עולמות עלמא דאתגליא ועלמא דאתכסיא שנק' ארץ וים כידוע (ובארץ נז' אורך לפי שזהו בחי' הירידה וההשפלה מגבוה לנמוך וע\"ז א' ארוכה מארץ מדה עד שלא יכילנה הארץ ואעפ\"י שהתור' ניתנה בראץ דוקא כמ\"ש לא בשמים היא כו' זהו בחי' הנגלה שבתורה דוקא אבל פנימית התורה שהיא בבחי' עצמות האור דא\"ס הרי אין לו סוף למטה וכך בבחי' הרוחב שבה א' ורחבה מני ים העליון בחי' עלמא דאתכסיא לפי שאין לה שיעור למעלה מעלה כמו שעצמות אא\"ס אין לו שיעור למעלה) אבל בחי' החיצוניות שבתורה הוא בהיפך שיש לה שיעור למט' דוקא שהרי באה בהתלבשו' למטה בדברי' גשמיים לעשות' בארץ דוק' בעשי' בפ\"מ ובאה בבחי' שיעורין וגבולין דוקא כמו שאנו רואים בכל מצוה שניתנה בשיעור ומדה כמו ד' בתים בתפילין ול\"ב חוטין כו' והרי כל דקדוקי סופרים הן באים בשיעור ומדה ושלא להוסיף ולא לגרוע כו' וה\"ז היפך גמור מבחי' פנימית התורה שהיא בלתי מוגבלת כלל וכלל כנ\"ל וזה הנסתרות לה' אלקינו בחי' סתים שבתורה שהוא לה' אלקינו למעלה עד אין שיעור כו' לפי שאור א\"ס מאיר בה אבל הנגלות לנו ולבנינו לשמור ולעשות הוא חיצוניות התורה שהן ההללות דש\"ס שבאו לשיעורין וגבולין איך ומה לעשותם וכללותם הן רמ\"ח מ\"ע ושס\"ה ל\"ת עם פירושיהן ע\"פ דקדוקי סופרים בצמצומים רבים דוקא כידוע שכל דין והלכה הוא מדוקדק ע\"פ חכמי ישראל שנק' תורה שבע\"פ והוא עיקר המעשה במ\"ש לשמור ולעשות את כל כו' וכידוע והנה לכאורה זהו דבר פלא ביותר איך ימצא ב' הפכים כאלה במקום א' שהוא בחי' אור דתורה שבפנימית שבה הרי היא בבחי' א\"ס ממש כנ\"ל ובחיצוניות שבה היא להיפך שבאה בבחי' גבול ומדה דוקא אך זהו ענין עוטה אור כשלמה דקאי על האור דתורה כמ\"ש ותורה אור כנ\"ל וביאור הדברים הנה מבואר למעלה בפי' עוטה אור כו' שיש בזה ב' הפכים א' שהוא עוטה ומעלים האור העצמי בלבוש שלמה והאור יותא ובוקע מן כיסוי והעלם זה כו' והב' להיפך שהאור העצמי מתפשט כלבוש והוא לבוש זך ובהיר כו' ושניהם אמת דהיינו ענין אור דתורה שע\"ז א' עוטה אור דתורה שהוא בבחי' אור העצמות ממש כשלמה והוא להעלימו ולהסתירו דוקא והיינו בחי' החיצוניות שבאור תורה עד שבאה למטה בהתלבשו' בדברי' גשמיים ובשעורים וגבולים דוקא כנ\"ל בענין הנגלות לנו ולבנינו לשמור ולעשות דוקא שנק' נר מצו' כו' והפי' הב' שעוטה ומתפשט אור דתורה כמו שהוא בבחי' אא\"ס כשלמה ומאיר באור זך ובהיר היינו בחי' פנימיות אור דתורה שע\"ז א' ארוכה מארץ כו' מפני שהיא בלתי מוגבלת כלל כמו שאור א\"ס אין לו שיעור למעלה למטה כו' כך כשעוטה אור העצמו' דתורה בבחי' לבוש הוא ג\"כ בבחי' א\"ס ונק' לבושו העצמי וכמו לבושי' כתלג חיוור כו' וכענין ובתורתו של ר\"מ כתוב כתנות אור באלף שזהו מבחי' אור דתורה כמו שהיא טרם שירדה לברר עה\"ד טו\"ר כו' ושרש הענין ידוע דהתורה שרשה בעה\"ח ממש שלמעלה מעה\"ד והוא מ\"ש ותורה אור ומה שירדה לברר לעה\"ד כו' הוא בחי' חצוניות ואחוריים שבה ולאחר הברור דעה\"ד עפ\"י התורה דבחכמ' אתברירו חזרה לקדמותה בבחי' פנימית האור דתורה וזהו כתנות אור בחי' זיהרא עלאה כו' משום"],[1700400367,"דפנימית אור דתורה הוא הנותן כח ועוז לחיצוניות התורה לברר בעה\"ד כו' וכמ\"ש חכמו' בחוץ תרונה ח\"ע דאתמשך בת\"ת כו' וזהו ההפרש בין לוחות אחרונות ללוחות הראשונות שבראשונות נא' משני עבריהם הם כתובים כו' וכמ\"ש במ\"א וד\"ל וזהו מימינו אש דת כו' אש שחורה ע\"ג אש לבנה פי' אש לבנה אור פנימית התורה מבפנים בלתי הגבלה כלל ואש שחורה חיצוני' שבה שבאה למטה בעה\"ד טו\"ר והן כללות רמ\"ח מ\"ע ושס\"ה ל\"ת להבדיל בין טמא לטהור כו' והן מ\"ט פנים טמא כו' וכידוע שזהו נובלות חש\"מ תורה וד\"ל וזהו כי נר מצוה ותור' אור נר מצוה בחי הנגלה שבתורה שבאה בגבול ומדה ובעשי' בפ\"מ ותורה אור כמו שהיא למעלה בפנימית שבה שהיא בבחי' אור א\"ס כנ\"ל והיינו ג\"כ ענין עוטה אור כשלמה כמו שאמ' ותורה אור אור א\"ס שמאיר בפנימית שלה ונוטה שמים כיריעה הוא בירידת אור דתורה למטה בשמים כמ\"ש מן השמים השמיעך כו' כי התורה מן השמים ניתנ' והוא באש ומים אמ\"ר בחי' מדות שבחכמ' שבא בבחי' ג' גוונין חג\"ת והיינו שמים שי\"ן מי\"ם כו' וד\"ל והנה עדיין אין מתיישב איך יוכל להיות דבר מהיפוכו שאם פנימית התורה הוא בבחי' א\"ס ממש איך יבא מזה היפוכו שהוא חיצוניות התורה בגבול ומדה כו' ולא עוד אלא שמפנימי' התורה הוא שנותן כח ועוז לחיצוניות והא בהא תליא והיו לאחדים ממש כנ\"ל אך הנה זה הכח ועוז לחבר ולקשר פנימית התורה שבלי גבול שיבא דוקא למטה במדה וגבול בכלים מכלים שונים הוא ע\"י ישראל דוקא שהן דוקא העושים את התורה כנ\"ל בפי' לשמור ולעשות את כל דברי התורה הזאת כו' והיינו שממשיכים מאור א\"ס שבפנימית התורה שיאיר אור א\"ס גם בחצוניות התורה ברמ\"ח מ\"ע למטה בבחי' עשי' בפ\"מ להיות לאחדים ממש למטה כמו למעלה ממש והגם שלמט' בא האור דתורה בבחי' גבול ושעור אבל שורה בזה דוקא מבחי' אור א\"ס שבפנימית התורה ממש ואין כחזה רק לישראל לבדם כמ\"ש ה' עוז לעמו יתן אין עוז כו' וד\"ל וראי' ממ\"ת שבאור פניו ממש האיר להם בי' הדברות שכלולים היו מפנימיות אור דתורה ומחצוניות יחד שהרי על כל דבור פרחה נשמתן כו' שזהו ענין אש שחורה ע\"ג אש לבנה כנ\"ל וגם בכל דור מקבלים כנ\"י בלימודם בדבר ה' בתשב\"כ ושבע\"פ מב' מדרגות שבתורה פנימיות וחיצוניות יחד כמ\"ש בברכת התור' נותן התורה לשון הווה וכן אנו אומרים באור פניך נתת לנו תורת כו' והטעם הוא לפי שישראל עלו במח' היינו ג\"כ בבחי' פנימית אור א\"ס שבפנימית התורה וכמ\"ש במ\"א ע\"פ יפה את רעייתי כתרצה כו' משום דס\"ר נש\"י שרשם בס\"ר אותיות התורה כמ\"ש זה ספר תולדות אדם דתלת קשרין הן אורייתא כו' וכמו דאורייתא וקודב\"ה כולא חד בב' מדרגות דסתים וגליא דפנימית וחיצוניות שלה כנ\"ל כך ישראל מתקשרין באורייתא וז\"ש והנגלות לנו ולבנינו דוקא לעשות כו' וד\"ל וזהו עוטה אור דתו' שקדמ' לעולם הנאצל והנברא כו' כשלמה בבחי' מקיף העליון אך גם שהוא בלי גבול כמ\"ש ארוכה מארץ כו' נמשך ומצומצם בגבול ואע\"פ שבהשתלשלו' העולמות הרי בחי' אור מקיף נבדל בערך ולא בא בבחי' גבול דאו\"פ או\"כ ונק' סובב כ\"ע כו' זהו מפני שגם בחי' המקיף דסובב כ\"ע אינו מפנימית אור עצמותו ממש כמ\"ש כי עמך מקור חיים כו' וכתיב ה' מלך גאות לבש לבוש חיצוני כו' אבל אור העצמות ממש זהו מ\"ש באורך העצמי שהוא אור דתורה נראה אור גם שהוא בבחי' הארה דהארה אבל אנחנו בנ\"י נראה ממנו האור העצמי והוא גם ע\"י התלבשות האור בתו\"מ בפ\"מ דוקא כמו במ\"ת שראו אור פנימית התור' גם ע\"י התלבשות בדברי' פשוטים וכן לעתיד נראה אור גדול שבעצמות המלובש בתו\"מ בפ\"מ והוא העוה\"ב שאינו בא רק מן המצו' בפ\"מ כמ\"ש כ\"י יש להם כו' וכתיב ביה עין לא ראתה כו' רק אנחנו נראה אור זה ואין זה רק מצד שלגבי פנימי' ועצמות אא\"ס גם בגבול ושעור ובתחתי' המדרגה הוא שורה כמו למעלה ממש וכמ\"ש"],[1700400368,"איזה בית כו' כי השמים ושה\"ש לא יכלכלוהו ומ\"מ צמצם שכינתו בהיכל ק\"ק כו' בלוחות וארון כו' וזהו נוטה שמים כיריעה שבמשכן להיות שכל ההשתלשלות דמקיף ופנימי בכלל אינו בא רק מפני ירידת אורו העצמי שעוטה אור כשלמ' בפנימית ואח\"כ נוטה שמים בחצוניות דאור תו\"מ וכמ\"ש אם לא בריתי כו' משום דסוף מעשה עבמ\"ת ונעוץ תחלתן בסופן דוקא וז\"ש ואשים דברי בפיך שהוא בחי' חיצוניות התורה לנטוע שמים וליסוד ארץ שהוא סובב וממלא בכלל כו' ולזאת יובן שגם בזה יש הפרש דאו\"מ דתו' יוכל לבא בגבול ומדה בתו\"מ הנגלות לנו בכלים מכלים שונים ואין זה דבר והיפוכו כלל כמו השראת עצמות אא\"ס בהיכל ק\"ק במקום מדה וגבול וכה\"ג וד\"ל:\n(יג) <b>ובכל</b> זה יובן כללות ענין מצות ציצית במ\"ש וראיתם אותו וזכרתם את כל מצות ה' ועשיתם אותם שאין זה רק במצות ציצית ששקולה כנגד כל המצות ולמה לא ע\"י מצוה אחרת להיות שכל עיקר כללות ענין הטלית הוא בחי' אור מקיף עליון שבפנימית אא\"ס דוקא וכמו עוטה אור כשלמה הנ\"ל וזהו כמאמר שהקב\"ה מתעטף בטלית כו' כמו עד\"מ אדם התחתון שמתעטף בטליתו שמוקף ונכסה בו ראשו ורובו והוא לבן וזך כו' וכך נא' בבחי' ע\"י לבושי' כתלג חיור כו' ול\"ב חוטין דציצית הן אורות עליונים שבוקעים ויוצאים מבחי' מקיף העליון כמו דאור תורה נמשך ובא למטה בבחי' לב\"ב נ\"ח להתלב' במצו' (וממיל' נמשך ל\"ב ויאמר דמע\"ב מבחי' סובב דמע\"ב כמ\"ש לנטוע שמים כו' כנ\"ל) וע\"כ במצות ציצית א' וזכרתם את כל כו' מפני שזהו שרש הראשון לבחי' המשכת ל\"ב נ\"ח דאור תורה מבחי' מקיף דעוטה אור כשלמה כנ\"ל וד\"ל אך מה שעיקר הזכירה הוא ע\"י ראי' דתכלת דוקא כמ\"ש וראיתם אותו כו' הנה יש להקדים תחלה בשרש ענין חוטין שבציצית שהן חוטי לבן וחוטי תכלת דהנה בחי' המרכבה עליונה כלולה מד' מדרגות פני ארי' ופני שור ופני נשר שהן ג' גוונין דחג\"ת ופני אדם כולל את כולם וכמ\"ש ופני אדם לארבעתן כו' לפי שפני אדם הוא בצלם האלקים כמ\"ש נעשה אדם בצלמינו כו' ויש להבין תחלה ביאור ענין פני ארי' ופני שור שהן חו\"ג לבן ואדום כו' וידוע דפני ארי' להימין היינו במדת האהב' והתשוקה האלקית לדבקה בו י\"ת בתשוקה נפלא' דהיינו באהבה ברשפי אש הגובר בלב בתגבורת גדולה כמו שאגת ארי' שישאג מתוך גבורת הלב כו' כך כתיב אחרי ה' ילכו כארי' ישאג כאותו בחי' ארי' עלא' שבמרכב' שישאג תמיד באה\"ר ותשוקה גדול' כו' והוא כמו התפעלו' האהבה והדביקות שבלב האדם בהתגברות הנק' בחי' רצוא כמא' אם רץ לבך כו' שמתקרב הולך וקרב תמיד אבל פני שור מהשמאל הוא בחי' היראה ופחד וקבלת עול מ\"ש באימה שהוא בחי' שוב היינו שמחמת היראה והבושה מאלקי' חיים נסוג אחור ולא ימצא מקום להתקרב בסיבת עוצם השפלות שמשפיל עצמו לפני אלקים ונק' שמאל דוחה שמדחה א\"ע וכמו במ\"ת שנא' וינועו ויעמדו מרחוק וכה\"ג והן ב' מדרגות דחו\"ג שהן ב' גוונין דלבן ואדום כידוע וד\"ל ובחי' פני נשר הוא מדרגה הכלולה משניהם מאוי\"ר והוא מדת הרחמים כמו שהנשר רחמני למטה כך למעלה עבודה האלקי' דפני נשר הוא בבחי' הרחמים לעורר ע\"ע ר\"ר שזה בא מצד האהבה האלקי' שחפץ לידבק ולא יכול מצד שרחוק ערכו בעוצם השפלות ונמיכת רוח שהוא היראה ע\"כ מעורר ר\"ר על נפשו כו' ובבחי' זו דרחמים יכולה הנשמה לעלות למעלה הרבה מעליית' באוי\"ר גם שנק' גדפין אבל הרחמים נק' כנפי נשר כו' והוא בחי' פני נשר וד\"ל (וזהו ואשא אתכם על כנפי נשרים כו' שהוא בחי' יעקב בריח התיכון שעולה עד קצה העליון שבפנימית הכתר וזהו ואביא אתכם אלי ממש וכמשי\"ת מפני שבמדת הרחמי' יכולה כנ\"י להתעלות בעצמות אא\"ס ממש וז\"ש ופני נשר לארבעתן כו' אך הנה בחי' פני אדם שבמרכבה הוא"],[1700400369,"העולה על הכל כי אדם אדמה לעליון ממש וכולן כלולין בו והענין הוא דעיקר בחי' אדם הוא שם מ\"ה גי' אדם והוא בחי' חכמ' שבתורה שבא במצות בפ\"מ ברמ\"ח פקודין רמ\"ח אברין דמלכא ושס\"ה ל\"ת כו' בזה דוקא נק' אדם אדמה לעליון וביאור הענין הנה מבואר למעלה בפי' עוטה אור כשלמ' שהוא אור דתורה שהוא בבחי' פנימית אא\"ס ממש והיינו בחי' פנימית מ\"ע שבתורה שהי' מאיר בדבר ה' בי' הדברות שע\"ז נא' חכמת אדם תאיר פניו וכתיב פנים בפנים דבר ה' עמכם וא\"כ הרי קיבלו הארת פנימית אא\"ס שבחכמ' עלאה ואז נק' אדם שלימו דכולהו כו' וכך גם עתה כאשר יקשר אדם מחשבתו ודבורו בדבר ה' זו הלכה ובקבלת עמ\"ש שלימה לקיים רצונו וחכמתו שבתו\"מ היינו לבטל כל רצונותיו נגד רצון העליון שבועשה טוב במ\"ע וסור מרע בל\"ת כמ\"ש עשה רצונו כו' בטל רצונך מפני רצונו כו' והוא הלומד ע\"מ לעשות את כל דברי התורה כו' כנ\"ל ה\"ז מחבר ומקשר מפנימית אא\"ס שבתורה אור למעלה שיומשך למטה כנ\"ל ודאי אז הוא בדומה לעליון ממש שהוא עצמות אא\"ס ב\"ה שע\"י לימוד התורה במחשבתו נכלל ונקשר במחשבתו ית' שבתורה אור העליון ובדבורו שמדבר בד\"ת נקשר ונכלל בדבר ה' ה\"ז ממילא חיבור וקשר פנימית התורה בחצוניות לשמור ולעשות וזהו עיקר בחי' אדם (כמ\"ש במ\"א שיש אדם פנימי ואדם חיצוני ופנימית אדם הוא בפנימית עצם הנפש שהוא פנימית רצונו וחכמתו ומדותיו כו' עד פנימית רצונו שבמעשה וחיצוניות שלו הוא הבא בהתלבשו' או\"כ במוח ולב וכל האברים כו') אך עיקר שלימות אדם גם כשמחובר הפנימית בחיצוניות דוקא כשבא לפ\"מ כל פנימית שבו והוא ענין המעשה של המצוה בפ\"מ כמ\"ש סוף דבר כו' את האלקים ירא ואת מצותיו שמור כי זה כל האדם משם דנעוץ תחלתן בסופן כנ\"ל והיינו כמו מעשה הצדקה להחיות רוח שפלים שכוללת כל המצות כידוע בפי' וצדקה תהיה לנו כי נשמור כו' פירש צדקה העליונה שנקרא מעשה כמה שכתוב והיה מעשה הצדקה כו' והוא בחי' שפע אור האלקי שנמשך במל' דאצילות שנקרא צדקה להחיות רוח שפלים בג' עולמות בי\"ע וכמ\"ש אשרי משכיל אל דל כו' כי ירידה גדולה היא מעצמות אלקות כידוע וכמשל שכל וחכמה המלובש במעשה הכתב וצייר שנק' שכל שבעשיה שמצומצם כח שכלו רק למעשה זו שלמטה הרבה גם משכל וחכמה שבמדות שבלב וכ\"ש לגבי השכל שבמוח כו' כך גם בחי' חכמה שבמל' דאצילות שמתלבש בי' מאמרות לחדש בכל יום מע\"ב בג' עולמות מאין ליש עד עוה\"ז השפל וכמ\"ש כולם בחכמה עשית גם זה צמצום גדול הוא מאוד והוא רק ע\"ד מעשה הצדקה לבד כי צדיק ה' צדקות אהב להוריד ולהשפיל אור שפע גם בחכמה שבעשיה לבד כו' ולהשפיע להם חיותם וקיומם מג\"ע העליון לנשמות עד שפע חסדו לכל בשר עד ד\"י גשמיים כידוע וכאשר האדם למטה יעשה ג\"כ מעשה הצדקה וחסד לחוס על דלים כמו שמבואר בהלכות צדקה שהיא עפ\"י מצות ה' כמו שהוא עושה צדקה העליונה כנ\"ל אז ודאי דומה הוא במעשיו למעשה ה' למעלה וכן אמרו הדבר במדותיו מה הוא רחום כו' ובמחשבתו ודבורו נדבק ונכלל באותיות התורה אור שבפנימית אדם כנ\"ל ונמצא דומה לעליון בג' אלה במוח ולב ומעשה שכולל כל ציור אדם בפנימית כמו שהוא מחובר ומקושר בחצוניות שהן רמ\"ח מ\"ע שנקרא רמ\"ח אברים דמלכא בפרט כנ\"ל ובכלל כלולים במעשה הצדקה כנ\"ל וזהו כללות ענין פני אדם העליון שע\"י תו\"מ וצדקה בפ\"מ דוקא וזהו הטעם שפני אדם שבמרכבה כולל הכל לפי שדומ' לעליון ממש וד\"ל: אך הנה עדיין יש להבין דהלא פני אריה ופני שור ופני נשר הן ג' מדות חג\"ת שגם הם כוללים כל בתו\"מ כי האהבה שורש רמ\"ח מ\"ע כו' ויש בכלל מאתים מנה ובפרט פני נשר שהוא בחי' הרחמים שכולל הכל ונקרא בריח התיכון כנ\"ל ולמה פני אדם שבמרכבה יותר נעלה מהכל ודוקא בחי' פני אדם דכנ\"י שעושין תו\"מ בפ\"מ דוקא הענין הוא כי הנה ודאי ע\"י"],[1700400370,"העלאת מ\"ן דאהבה רבה שבבחי' פני אריה להימין מלמטה למעלה מעורר מלמעלה למטה אה\"ר וע\"י פחד ויראה דפני שור מעורר למעלה פחד ה' וכה\"ג במחנה מיכאל ומחנה גבריאל בכל עולם לפי ערכו וכ\"ש פני נשר במדת הרחמים שמעורר ר\"ר העליוני' שלמעלה משניהם כנ\"ל אך הענין הוא שיש בזה ג' מדרגות האחד העלאת מ\"ן דמרכבה תתאה שמעורר למעלה רק לפי אופן הגבלת הכלי שלהם לבד באוי\"ר ורחמים המצומצם בכלי השגתם לפי ערך צמצום האור האלקי שהוא מקור חוצבם מאין ליש בלבד כמו מהעלא' התפעלות התשוקה ברשפי אש דפני אריה להימין נמשך אור חסד עליון ר' לפי המד' בכחל עול' ועול' לפי מדרג' העלא' שלה' וכך בהעלא' היראה והרחמים דפני שור ופני נשר כו' כידוע והב' בהעלאת מ\"ן דאבות שהן המרכבה שלמעלה מזה כידוע דיש ב' מדרגות במרכב' א' מרכבה תתאה דהיינו בחי' חג\"ת דבי\"ע שהן שרפים וחיות ואופנים שרפים בבריאה וחיות ביצירה ואופנים בעשיה כו' והב' מרכבה עלאה דאצילות שהוא בחי' חג\"ת דז\"א דאצילות והאבות היו מרכבה לחג\"ת דאצילות דוקא כידוע דאברהם אוהבי רחימא דמלכא באהבה ודביקות שלו וחסד שעשה למטה בפ\"מ העלה מ\"ן לחסד דאצילות וכן יצחק בפחד ויראה לגבורה דאצילות ויעקב כלול משניהם כמ\"ש אלקי אבי אברהם ופחד יצחק היה לי שהוא בחי' הרחמים שכלול משניהם כו' ונמשך ע\"י העלאת מ\"ן שלהם מלמעלה למטה תוס' אורות באצילות מאה\"ר העליונה שבעצמות המאציל נמשך תוס' אור רב באור חסד דאצילות ומגבורה עליונה שבמאציל נמשך תוס' אור באור הגבורה דאצילות ע\"י פחד יצחק וכן ע\"י הרחמי' דיעקב נמשך תוס' אור מר\"ר העליונים שבעצמות ונק' בריח התיכון שמעורר מעצמותו ממש כנ\"ל וזהו והאכלתיך נחלת יעקב אביך שנק' נחלה בלי מצרים בהיותו עולה למעלה עד אין שיעור כו' וכנ\"ל בפי' ואשא אתכם על כנפי נשרים וכן כנשר יעיר קנו וכה\"ג וד\"ל והמדרגה הג' הוא בחיי העלאה מ\"ן דאוי\"ר ורחמי' שבכנ\"י אעפ\"י שהן למטה הרבה מן האבות כי הן רק ענפים שלהם אך ע\"י אוי\"ר שלהם שמלובשים בתו\"מ שעושין בפ\"מ דוקא עי\"ז מעוררים למעלה ממקום ומדרגה היותר נעלה מהעלאת מ\"ן דאבות והענין הוא כמ\"ש במ\"א ע\"פ יפה את רעייתי כו' ואמר הנך יפה ב\"פ דפי' יופי זה הוא כשכלול מד' גוונין דוקא והיינו לאחר התכללות המדות דחו\"ג אוי\"ר ברחמי' שנק' בריח התיכון כנ\"ל נכללין הכל בבחי' פני אדם גוון שזהו דוקא בקיום התו\"מ בפ\"מ כנ\"ל וביאור הדברים הנה מצד התלבשות נש\"י בגופים אין העלאת מ\"ן שלהם עולה רק למרכבה תתאה דמלאכים דבי\"ע היינו ענין פסד\"ז ויוצר אור עד ק\"ש אבל בק\"ש שאומר שמע ישראל שהן נשמות מצד שרשם למעלה שקיבלו עליהם תו\"מ בפ\"מ והיינו ואהבת את הוי\"ה אלקיך דוקא ע\"י מצות ת\"ת ודברת בם וכל המצות בפ\"מ הנה זהו העולה למעלה מכל העלאת מ\"ן גם משל האבות וכמ\"ש וארא כו' ושמי הוי\"ה ממש לא נודעתי להם כו' ואמנם זהו דוקא ע\"י מצות אוי\"ר שנוגעים למעשה כו' דהיינו ע\"י התפעלות האהבה ודביקות שבק\"ש ויש בזה הסכם לענין מעשה דוקא שמצד האהבה לה' ידבק במצותיו כל היום ויחפוץ לעשות רצונו בכל קיום הטוב דמ\"ע מפני שסוף מעשה עבמ\"ת והוא עיקר פנימית אדם למעלה מצד שקדשנו במצותיו ממש שנק' רמ\"ח אברין כו' כנ\"ל הנה מעורר אתעדל\"ע מאה\"ר העצמי' ממש שלמעלה מאה\"ר שנמשך ע\"י כל העלאת מ\"ן והוא שיאר ה' פניו לכנ\"י בימין מקרבת שלמעלה מבחי' או\"כ והיינו מבחי' מקיף דרב חסד העליון שלא יכילנו הכלי (ולע\"ל יתגלה למטה ועכשיו תוס' אור זה באצילות לבד כמ\"ש במ\"א) שהוא בבחי' א\"ס ממש וכן ע\"י היראה ופחד אלקים שמעורר בק\"ש ותפלה עיקר המכוון הוא שישאר מזה העול מ\"ש שיהיה רק סו\"מ בפ\"מ כל היום ונופל פחד ה' פתאום כי עליו חופף כל היום בבחי' מקיף בהעלם כמ\"ש שמאלו תחת לראשי וימינו תחבקני"],[1700400371,"באה\"ר בבחי' מקיף בהעלם כל היום גם בטרדתו בעסקיו ובן בהתעוררות ר\"ר על נפשו האלקית במרירות גדולה נמשך על נפשו ר\"ר העליונים להעלותם למעלה מעלה כנ\"ל עד שמחבר מקצה העליון שהוא פנימית התורה אור שארוכה מארץ כו' לקצה התחתון שהוא בתו\"מ בפ\"מ וגם לקטני הערך נשמות היותר שפלים כדור האחרון הזה שנק' עקביים שיהיו שלמים בתו\"מ בפ\"מ עכ\"פ וכן בכל דור ע\"י ר\"ר מחב' מראשי אלפי ישראל לקצה התחתון שהן הדיוטים וקלים כו' שכולם צדיקים בתו\"מ וכמ\"ש כולך יפה רעייתי מראש לרגל כו' וזהו יפה את רעייתי ביופי דפני אדם העליון וכמו שכפל ב\"פ הנך יפה מלמטה למעלה בהעלאת מ\"ן דאוי\"ר שבתו\"מ שנק' פני אדם ועי\"ז הנך יפה להמשיך מאור פני אדם העליון כו' וזהו ישראל אשר בך דוקא אתפאר שהוא פאר דתורה אור שמאיר מפנימית אא\"ס כנ\"ל שכלול מד' גונין מפני שכלולים בו הג' גונין דחג\"ת דמרכבה עלאה ותתאה דפני אדם לארבעתן וזהו נעשה אדם בצלמינו כדמותינו תושב\"כ ותושבע\"פ בפ\"מ דרמ\"ח מ\"ע שהוא עיקר צלם ודמות דאדם העליון מטעם הנ\"ל וד\"ל:\n(יד) <b>וזהו</b> ועשו להם ציצית על כנפי בגדיהם כו' על כנפי בגדיהם דוקא דהנה מובן עפ\"י כל הנ\"ל בענין עוטה אור כשלמה שאמיתית הארת עצמות אא\"ס כמו שהוא א\"א להאיר כ\"א בבחי' מקיף העליון שז\"ש עוטה אור כו' והאורות הבוקעים ויוצאים ונמשכים מבחי' מקיף הן ל\"ב חוטין דציצית בפרט שהן ל\"ב נ\"ח ובכללות הן ד' ציצית שעל ד' כנפות הטלי' דוקא כי הטלית הוא בחי' עצם המקיף העליון שבו שורה בחי' עצמות האור דא\"ס ממש שא\"א להתצמצם ולבוא בבחי' או\"פ גם ברצון וחכמה לכך מתעטף בטלית ע\"ג הראש וזהו עיקר מצותו כו' וד\"ל (משא\"כ התפילין הן רק בחי' מקיפים שע\"ג המוחין שבראש כידוע) ואמנם הציצית שעל הכנף הוא האור המציץ ובוקע מעצמות אור המקיף דטלית ונק' גם הן מקיפים רק שבאין בדרך צמצום והמשכה והן בד' כנפות בכלל ול\"ב חוטין בפרט והן בחי' ד' גוונין שבמרכבה הנ\"ל שכלולים בפני אדם רק שבמרכב' בא האור הזה בבחי' גלוי לפי ערך הכלי ובציצית על ד' כנפות בא האו' מעצם אור המקיף דטלית וד\"ל (ויובן זה בכל נשמה אלקית בפרט להיות ידוע בבחי' נרנח\"י שבחי' יחידה שבנפש הוא כח העצמות שבנפש ממש שמשם נובע כל התפשטות רצון לרצון ותענוג כו' וגם כל כח המשכיל כל שכל וגם כח העצמי של כל מדה ומחשבה עד גם כח הדבור ומעשה כו' וכל אשר יולד רצון ותענוג ושכל ומדות ומדו\"מ כל היום הכל נמשך ובא מעצמות כח הנפש הנק' יחידה שכלול שם הכל בהעלם העצמות כו' ולזאת כאשר יאיר אור האלקי במקיף דיחידה זה מזה נמשך כל תולדות רצונו' ומדות ושכל לטוב כל היום בכל אשר ילך כו' והיינו ענין הטלית שבו שורה אור האלקי בבחי' מקיף על כח עצם הנשמה ונק' כח קדישא כמ\"ש בזהר שמזה נמשך כח ועוז בעצם כח הנשמ' להאיר בכל פרט ופרט מכחות הנפש גם ברצון ותענוג ושכל ומדו' עד כל פרט מחשבה דו\"מ והן הנה ל\"ב חוטין שבציצית שהן בחי' אורות מקיפים רק שבאין דרך המשכה מיוחדת בכל חוט כמשי\"ת וכללותם בד' כנפות לימין ושמאל וכו' וע\"כ הזהיר במצות ציצית דוקא נשמר מכל רע ועושה טוב כל ימיו כי זה המקיף נק' שומר בעצם דהיינו שבעיטופו בטלית נמשך כח אלקי בעצם כח הנשמה ומתפשט הארתו בציצית וראיה לזה ממה שמצינו דבר פלא ביותר באחד שהיה זהיר במצות ציצית לבד באו לו הציצית וטפחו על פניו ונמנע מעשות העבירה כו' וד\"ל) וזהו גדילים תעשה לך על ד' כנפות כסותך אשר תכסה בה דוקא והיינו אשר תכסה עליך בבחי' מקיף והוא ענין עיטוף הטלית פרישו דמלכא כו' כי א\"א להאיר מעצם המקיף העליון בנש\"י באו\"פ במוחם ולבבם כו' כ\"א רק בבחי' מקיף דוקא להיותו בבחי' א\"ס ממש כנ\"ל והן ענין הד' כנפות נגד ד' מדרגות הנ\"ל פני אריה פני שור כו'"],[1700400372,"כמו בכנף של צד הימין מאיר מבחי' מקיף של אור החסד העליון ימין מקרבת כמ\"ש וימינו תחבקני כמשל החובק לחבירו שהוא בבחי' מקיף כן אור האהבה העליונה מאירה ומתפשט' לחבוק הנשמה בהתעטפה בטלית בכנף הציצית שבימין לשומרו כל היום מדבר רע ולהיות רוח אהבה ודביקות נתעורר בה לכל דבר מצוה כו' וכן בכנף השמאל נמשך מבחי' יראה ופחד שבמקיף העליון שיהיה סו\"מ וכן בב' ציצית האחרים וכללותם נכללים בפני אדם שהן כללות ל\"ב נ\"ח שמאירים בכנ\"י בבחי' מקיף דוקא רק שמפני שא\"א שיאיר אור המקיף כמו שהוא בעצם כ\"א ע\"י הבקיע' שבוקע ויוצא מעל הכנף של הטלית והן החוטין התלויין בו וכל חוט וחוט הוא ענין המשכה מיוחדת כמו הקו ההולך בצמצום וכמו שערות באדם ולכך נק' בשם ציצית כמו ויקחני בציצית ראשי כו' והן המשכות דקות ומצומצמות שמאירים ויוצאי' מן המקיף העליון לכנ\"י והן ח' חוטין בכל כנף נגד ח' אותיות דב' שמות הוי\"ה אד' בחי' חו\"ג והן בעצם שתים שהן ארבע לבד היינו חו\"ג דלבן ותכלת ונכפלים כו' (וכמו שיש ל\"ב חדרים במוח שהן ד\"פ ח' והכל בבחי' או\"פ אור בכלי כך יש במקיף דטלית ד\"פ ח' והן ל\"ב חוטין ח' חוטין בכל כנף וד' הן בכלל שהן ד' כנפות הטלית והוא למעל' הרבה ממקיף דד' מוחין שבראש שבד' בתי דתפילין ע\"כ מצות עטיפת הטלית קודם לתפילין וד\"ל) וכל חוט שזור וכפול מד' חוטין כמו בחי' ד' גונין העליונים שבמרכבה פני אריה כו' כל א' כלול מד' כמו אהבה רבה דפני אריה כלול מיראה ופחד דפני שור כו' וכמ\"כ בד' מחנות מחנה מיכאל באהבה כלולים מיראה ומחנה גבריאל ביראה כלול מאהבה וראיה מן האבות דאברהם שהיה במדרגת האהבה נאמר לו עתה ידעתי כי ירא אלקים אתה כו' כי היה כלול בו היראה ופחד רק שהאהבה היה בו בגלוי והיראה ופחד אלקים היה בו בהעלם וביצחק היה להיפך שאהב' דאברהם היה בו בהעלם והפחד בגלוי ע\"כ נק' פחד יצחק וביעקב היה בחי' הרחמים בגלוי כו' אמנם כל א' כלול מכולם וכן במחנות דמלאכים כל א' כלול מכולם וכמ\"ש בזהר כלילין ושליבן דא בדא כו' וד\"ל ואמנם הנה אע\"פ שהחוטין הן ל\"ב ונחלקים לד' כנפות ובכל כנף ח' חוטין אבל כללות ענינם הן רק ב' גוונין לבן ותכלת לבד והתכלת הוא עיקר וכמ\"ש ונתנו על ציצית הכנף פתיל תכלת וראיתם אותו וזכרתם כו' וקאי וראיתם אותו על התכלת דוקא כידוע וביאור הדברים הנה ידוע בפי' תכלת לשון כליון כמו אשא תכלא דאכיל ושצי כו' והוא כח האור מקיף שמבער את הרע ומגרשו בדרך כפי' לאכפייא לסט\"א כו' וכמו לע\"ל דכתיב ואת רוח הטומאה אעביר כו' העברה זו יהיה בכח תוקף אור המקיף שמדחה ומבער כל רע כו' והיא בחי' התכלת שהוא בחי' המל' שמברר לעה\"ד טו\"ר כו' ונק' אש שחורה וכנ\"ל בפי' עוטה אור באור דתורה שבא למטה לברר ע\"הד כו' וכמו באדם למטה שיש בו מהארת כח המקיף רוח טהרה לטהר לבבו מכל רע וגרש יגרשנו ויבערנו וכמ\"ש ובערת הרע מקרבך והוא מבחי' הגבורה שמאל דוחה כו' אבל בחי' חוטי הלבן שבציצית הן מבחי' החסדים שבאור המקיף שאין שם מקום ואחיזה לרע כלל והוא מבחי' עה\"ח שלמעלה מעה\"ד טו\"ר כו' וכמאמר אין רע יורד מלמעלה כו' דלא יגורך רע כלל והוא בבחי' אור האצילות שאין שם רע כלל וע\"כ יש ביכולתו להפוך הרע לטוב להיות מואס ברע ממש שלא בדרך כפיי' לבד אלא לאהפכא חשוכא לנהורא כו' וד\"ל [ויובן זה ממ\"ש למעלה בענין ב' מדרגות שבתורה שבפי' עוטה אור כו' דשרש התורה שקדמה לעולם הוא בבחי' עה\"ח שלמעלה מן עה\"ד ע\"כ למעלה היא מבירור עה\"ד כי אין שם רע כלל ולכך יש ביכולת אור התורה להפוך רע לטוב כמאמר לעולם יעסוק אדם בתורה אף שלא לשמה שמתוך שלא לשמה בא לשמה וכן אמר אין גהינם שולט בת\"ח כו' ואין עבירה מכבה אור תור' וגם ראיה מבע\"ק שמותר בד\"ת שאין ד\"ת מקבלים טומאה ולפעמים א' להיפך למ???רנים בה סמא דחיי ולמשמאילים בה סמא"],[1700400373,"דמוחא זהו מצד התלבשות התורה בעה\"ד טו\"ר והוא אש שחורה לברר עה\"ד כו' וכך הוא ענין ב' מדרגות הללו בנשמות א' חלק האור העצמות של הנשמה דבוקה למעלה מושלל' מכל בחי' רע דעה\"ד כו' כי הוא אור זרוע לצדיק עליון כו' וע\"ז נא' כולך יפה רעייתי ומום אין בך כלל ומשם יאיר אור שיוכל למאוס ברע שלא בדרך כפי' והכרח כלל כו' אבל חלק הנשמה שבנר\"נ בגוף מלובש בעה\"ד טו\"ר כו' יכול לבא לבחירה לפעמים לבחור בטוב ולפעמים בהיפוכו כו' וע\"ז נא' ובחרת בחיים כו' והיינו מחות התכלת שבציצית לבער הרע בדרך כפי' ולבחור בטוב עפ\"י בחירה דוקא והוא מ\"ש וראיתם אותו שהוא חוטי התכלת דוקא וזכרתם לבחור בטוב ולא תתורו לאכפייא כו' וד\"ל\n(טו) <b>וזהו</b> וראיתם אותו וזכרתם כו' ע\"י ראיה דתכלת דוקא שבא ונמשך בעה\"ד לברר בין טו\"ר והן רמ\"ח מ\"ע ושס\"ה ל\"ת והיינו וזכרתם את כל מצות ה' לבחור בטוב ולא תתורו כו' להיות סור מרע היינו לאכפייא כנ\"ל שזהו יסוד כל התורה כולה וד\"ל ולפ\"ז מ\"ש וזכרתם כו' ולא תתורו כו' הוא ע\"ד הבחירה דוקא ולפי פשוטו משמעו דע\"י ראיה על התכלת ממילא יזכרו על כל המצות לעשותם ולא תתורו כו' ממילא לא תתורו כו' כמו ובעבור תהיה יראתו על פניכם לבלתי תחטאו כו' ועוד שלפי פי' הנ\"ל הרי העיקר הוא התכלת ולמה הוצרך לחוטי לבן כלל ולכאורה ב' מצות הן כמ\"ש התכלת אינו מעכב את הלבן ופרש\"י דאע\"פ שמצוה ליתן ב' חוטי תכלת אי עביד ד' חוטי לבן או ד' חוטי תכלת יצא אך הנה באמת מצוה אחת הן (כמ\"ש הרמב\"ם פ\"א מה\"צ וז\"ל נמצאו במצוה זו ב' ציווים שיעשה על הכנף ענף יוצא ממנה ושיכרוך על הענף חוטי תכלת שנאמר ועשו להם ציצית ונתנו על ציצית הכנף פתיל תכלת והתכל' אינו מעכב וכו' כיצד הרי שאין לו תכלת עושה לבן לבדו כו' אע\"פ שאין אחד מהן מעכב את חבירו אינן ב' מצות אלא מ\"ע אחת אמרו חכמים הראשונים והיה לכם לציצית מלמד ששניהם מצוה א' עכ\"ל) וצריך לשתיהן רק שהן באים בשני אופנים מחולקים זה בבחי' החסד וזה בבחי' הגבורה והמכוון א' ובשתיהן הכוונה כמ\"ש וזכרתם ולא תתורו למעלה מן הבחירה כנ\"ל ויש להקדים בענין שרש הלבן והתכלת מהו דהנה שרש הראשון שלהם הוא בבחי' אור מקיף העליון שבעצמות אא\"ס והוא מ\"ש עוטה אור כשלמה כנ\"ל והוא כמ\"ש לבושי' כתלג כו' וב' מיני חוטי' דלבן ותכלת היוצאי' מכנפיה לבוש דעוט' אור כו' היינו בבחי' חו\"ג דמקיף דע\"י שהוא בחי' או\"י ואו\"ח בכלל והנה מבואר למעלה בענין חוטי לבן שהוא המשכה מאור רב חסד העליון בבחינת מקיף דאה\"ר והוא כמו מבחינת אהבה בתענוגים שמתענג על ה' כו' בכל פנימית עצמות הנפש בעריבות מתיקות ידידות עד שתכלה נפשו באהב' ותשוק' כו' יש בכחה עוז להתמשך עד למטה מטה היינו גם במדות דק\"נ שבנה\"ב להפוך הרע לטוב להיות מואס ברע בתכלית שזהו מצד עוצם דביקות אור האלקי בפנימי' נפשו עד שגם החשך יאיר כמו האור דהיינו שגם גופו קדוש בקדושה האלקי' כמו אור נשמתו ממש וזהו הנק' בחי' או\"י שנמשך מגבוה לנמוך מאד ולמעלה היינו מבחי' מקיף דחסד דע\"י כו' ודוגמא לזה הוא מה שמצינו במ\"ש ויורהו ה' עץ וישלך אל המים שזה היה בחי' עה\"ח שלמעל' מעה\"ד טו\"ר ע\"כ הי' בכחו להמתיק מים המרים שמעורבים רע גמור דמיין מרירן מסט' דמוח והרע כו' גבורות קשות לגמרי וכשמתקו המים המרים למתיקות נתוסף כח מתיקות ביתר עוז מעצם המתיקות כידוע וזה הכח להפוך גם הרע ומר לטוב ומתוק זהו מתוקף כח אור החסדים עליונים שבמקיף היותר עליון דוקא וזהו יסוד כל התו\"מ לאהפכא חשוכא לנהורא ומרירו למיתקא שהוא להמתיק הג\"ק הנ\"ל רק שבא בשני אופנים או רק להבדיל הרע מן הטוב או למאוס ברע ולהפכו לטוב שזהו לאהפכא כו' והוא לאכללא שמאלא בימינא כו' שכל גבורות קשות שמסתעפי' מקו השמאל יוכללו"],[1700400374,"ויומתקו בחסדי' העליונים וזהו כי גבר כו' חסדו וכן ימין ה' רוממה ועושה חיל והיינו ב\"פ ימינך נאדרי בכח ותרעץ אויב ששובר ומכלה כל הג' קשות (ונק' גבורה שבחסד וכמו קומה ה' ויפוצו אויבך וינוסו משנאיך כו' שבסיבת תוקף גלוי האלקי למטה בארון ולוחות יפוצו הקליפו' כו' וכן תרעץ אויב ע\"י ימין מקרב' דוק' וכמו והשמיע ה' את הוד קולו כו' שמזה נפלו מחנ' סנחרב וכה\"ג) וכמו שרואה אדם בעצמו בכל א' לפי ערכו בעת הכושר וכ\"ש בשבת שמתענג על ה' בתוקף גלוי אור אלקי באה\"ר בתענוגי' שממילא יפול כל הרע שבו בשעה זו וראי' מאכילת שבת שאינו מגשם וכמ\"ש פרש חגיכם ולא פרש שבתכם ואין אור הגיהנם שולט בשבת כו' משום דבחי' שבת הוא בפנימית אור אבא שהוא עה\"ח כו' שלא יגשם כלל ועוד ראי' מאור תורה ששרשה בעה\"ח כנ\"ל) וכל זה נק' מיתוק הגבורות ע\"י החסדים המקיפים שבבחי' או\"י והוא הנק' קדושה וברכה מלמעלה למטה וכאשר יתקדש האדם מעט מקדשין אותו מלמעלה הרבה עד שממילא הוא מואס ברע בתכלית ובוחר בטוב למעלה מן הבחירה ואין כל קטרוג יכול לנגוע בו מפני שהקטרוג בא מן הרע ואין מקום לרע כלל כי נהפך לטוב וע\"כ ממילא קטיגור נעשה סניגור כמיתוק המר למתוק כנ\"ל וזהו בחי' חוטי לבן שבציצית שהן בחי' ירידות אורות החסדים העליונים שמן מקיף העליון ביותר דלבושי' כו' לאהפכא חשוכא לנהורא ומרירו כו' כנ\"ל אבל חוטי תכלת שרשם הוא בא מבחי' אור הגבורה דמקיף העליון והוא בא ג\"ע לאהפכא חשוכא לנהורא ומרירו למיתקא כו' כמו שמבואר למעלה ממש אך הנה היא בא באופן אחר היפוכו היינו להמתיק הדינין קשין בשרשן בבחי' הדין והגבורות ולא ע\"י חסדים כלל וזהו מיתוק יותר אמיתי ויובן זה ממה שמצינו בענין הקטורת דהנה ידוע בזוהר וספרי הקבלה בשרש ענין הקטרת שנמתקו הדינין בשרשן כי י\"א סממני הקטרת עולין למעלה בבחי' או\"ח בהעלאת הריח בעצמות התענוג כמ\"ש ישימו קטורה באפך וכתיב שמן וקטרת ישמח לב להמתיק כל הדינין הקשין די\"א ארורים דקליפה עד שנהפכו לחסדים טובים כ\"כ שיוכלו לעצור המגפה כידוע באהרן שעצר המגפה ע\"י המחתה דקטרת דכתיב ויעמוד בין המתים והחיים ותעצר המגפה והטעם הוא לפי ששרש המות הוא נמשך מן הרע דנוק' די\"א ארורים דקליפה וע\"י הקטרת נמתק הדין והרע בשרשו ולא יכול המות לשלוט כלל וכעובדא דר אחא בכפר טרשא הנזכר בזהר רק שזהו תלוי בתשובה דוקא כמ\"ש שם בזהר דמ\"מ עלמא בחיובא אשתכח אם לא עשו תשובה כו' והענין הוא דע\"י התשובה מכל פנימית הנפש עד כלותה כראב\"ד וכה\"ג הרי הרע עצמו נהפך לטוב וזה מיתוק הדין מצד עצמו שלא ע\"י תגבורת החסדים כלל הרי זהו מיתוק יותר אמיתי ממיתוק מים המרים בעץ המתוק שמ\"מ עצם מרירותם לא כלה רק שמפני כח ותוקף המרירות נהפכו גם הם למתיקות אבל כשהמר נעשה מתוק מצד עצמו ודאי הוא מתוק בכח רב ביותר וכמו סם חיים שמרפ' ומחי' גם המסוכן למות ממש כו' וזה כח התשוב' אמיתי' שעוש' מן הרע עצמו טוב שזהו ממש כמו שמן המות עצמו נעשה חיים שהוא בתוס' כח חזק מחיים עצמו כמא' טוב מאוד זה מ\"ה כשנהפך לטוב וחסד והוא קטיגור שנעשה סניגור וארור נהפך לברוך מצד עצמו וכמ\"ש במ\"א ע\"פ ולא אבה ה' כו' ויהפוך הקללה עצמה לברכה שהיא בתוס' מרובה על עיקר הברכה מטעם זה וזהו ענין תחה\"מ לע\"ל שהמות יהפך לחיי' משום שנ' ורוח הטומאה אעביר כו' והעברה זו יהיה מב' סיבות א' מבחי' מקיף דאו\"י שהוא תוקף גלוי אור האלקי מבחי' החסדים המקיפים כנ\"ל וכמו נגלה כבוד ה' וראו כל בשר כו' וכולם ידוע אותי וכה\"ג ואשפוך רוחי כו' והב' מצד בחי' או\"ח שע\"י התשובה אמיתית שזהו כמו ריח הקטרת שנהפך המות והרע לחיים וטוב שנק' טוב מאד כו' והמכוון א' משתי אלה דאו\"י ואו\"ח והוא שנהפך"],[1700400375,"הרע עצמו לטוב אך ע\"י החסדים דאו\"י נמשך מלמעלה למטה כנ\"ל וע\"י הגבורות דאו\"ח עולה מלמטה למעלה וזהו כמו האש שאוכלת האש שמבערו לגמרי מכל וכל כך ביעור הרע לגמרי מעיקרו ושרשו ע\"י המרירות העצומות דבע\"ח יותר נעלה ממיתוק הרע ע\"י תגבורת הטוב ולכך אמר רבי יש קונה עולמו כו' דבע\"ת גדול מצ\"ג כידוע שזהו הנק' טהרה שמביאה לידי קדושה והוא ענין התכלת דאכיל ושצי כאש אוכלת [וכמו כהמס דונג מפני אש יאבדו רשעים מפני כו' וכך למעלה כתיב ה' יחתו מריביו כו' וכמו וישלח חיצים ויפיצם ברק כו' שהוא ע\"י כח הגבורה שמאל דוחה ומגרש ומבער כו' וזהו ואשמיד פריו ממעל ע\"י בחי' או\"י ושרשיו מתחת ע\"י בחי' או\"ח וד\"ל) ולכך א' וראיתם אותו על התכלת דוקא מפני שמזה יבא לקדושת המצוה משום דטהרה מביאה לידי קדושה דאו\"ח עולה למעלה מאו\"י ומ\"מ צריך לחוטי לבן להמשכת הקדושה דאו\"י לאהפכא כו' ולכך מצוה אחת הן והכל למעלה מן הבחירה וד\"ל:\n(טז) <b>ויובן</b> זה בתוס' ביאור בענין טהרה וקדושה דאו\"ח ואו\"י הנ\"ל להיות שעיקר ההפרש ביניהן עדיין אינו מובן אם המכוון משניהם א' הוא שהרע עצמו נהפך לטוב מהו ההפרש אם זה בא מצד או\"י מלמעלה למטה או מצד או\"ח מלמטה למעלה אך הנה יש להבין בתוס' ביאור בענין התכלת דאכיל ושצי כו' דלכאורה אין זה רק ענין התשובה האמיתית שהרע מצד עצמו נהפך לטוב כנ\"ל וא\"כ למה נקרא בשם אש אוכלת אש דמשמע שזהו אש האלקי דאכיל ושצי לאש זרה דק\"נ אך הענין הוא דשרש האש הזה הוא למעלה מבחי' האור דחסדים הנ\"ל דהנה ידוע בענין אויר ואור שהאויר למעלה מן האור ויש בו' ב' מדריגות א' בחי' ההעלם ומקור דחכמה והיינו היו\"ד שבאויר שמשם נמשך גלוי האור דחכמה מאין ליש אבל הוא לא נמשך רק ע\"י צמצום דמא' יהי אור ויהי אור כו' וגם מ\"ש עוטה אור כשלמה שהוא בחי' מקיף דאור החכמה כנ\"ל באור דתורה מ\"מ מאחר שהוא מקור לגלוי פנימי בכלל אור יחשב וזה האו' ובין החושך כו' כמשל מי שעצם מציאותו נתהווה באור ולא ראה חשך מימיו שאינו מכיר מהות חשך כלל ואמנם אנו רואים שיש בכח זה האור להאיר את החשך ג\"כ כנ\"ל וד\"ל אך מדרגה הב' דאויר הוא בחי' עצם חשוך ונעלם בהעלם עצמי בלתי מתגלה להיות גם מקור לחכמה שנק' אור גם לא בבחי' מקיף והוא הנק' אוידא דכיא ששם הוא בחי' אש היסודי בהעלם גדול כמ\"ש בס' החקירה שהאש הגשמי הגם שנתפס במישוש וראו' גבוה גם מיסו' הרוח להיות שרשו באש היסודי שהו' אויר דק בתכלי' הדקו' (וע\"כ הרוח מגדיל האש כי שרשו מרוח האויר דק הנ\"ל) והז יש יתרון מעלה לאש גשמי על האור המאיר כי יש באור ב' דברי' א' מה שמאיר אור בגוון הלבן שבו שנק' אש שחור' וידוע ששרש אש השחור' השורף ומכלה או שאוכל אש הוא באש היסודי שהוא בבחי' אויר דק שלמעלה מעלה גם ממקור התהוות אור המאיר כנ\"ל כי טבעו להפוך ולכלות דבר מה שנאחז בו לעלותו לשרשו שהוא בחי האויר הנעלם הנ\"ל וזהו היפך טבע האור המאי' שיורד ונמשך להאיר כו' ומזה יובן גם בהאיר אור בחשך שאור המאיר אעפ\"י שמאיר גם בחשך היינו שהחשך נדחה מן האור במקום שהוא מאיר אבל לא שנהפך החשך עצמו לאור אך בבחי' האויר הנעלם הנ\"ל שלמעלה מהתהוות האור המאיר ודאי גם חשך לא יחשיך כחשיכה כאורה שוין שם ומובן מזה שאש הגשמי ששרשו באויר דק הנ\"ל יש בכחו להפוך החשך עצמו לאור כי שרש החשך למטה הוא בחשך העליון שהוא אויר הדק הנ\"ל וזהו כמו לע\"ל דכתיב ולילה כיום יאיר ולא מצד אור השמש כלל רק חשך הלילה יאיר כיום שכאשר יגולה אויר הנעלם ודאי יהיה יתרון אור הרבה מן האור שנתהווה ע\"י צמצום המא'"],[1700400376,"דיהי אור וכן לא יהיה אז הבדלה כלל בין אור לחשך ששניהם כא' יאירו לילה כיום וד\"ל והדוגמ' מכל זה ההפרש בין או\"י וא\"ח טהרה וקדושה דתכל' ולבן שבציצית הנ\"ל דהנה ידוע שהנשמות נק' אור המאיר כמ\"ש נר ה' נשמת אדם וכן כי אתה תאיר נרי כו' וכה\"ג ושרשם הראשון מבחי' האור דחכמה שנתהווה מאויר הקדום הנ\"ל והיינו מה שהנשמה תהלל יה בהתפעלות אה\"ר בתענוגים כמו בשבת שא' אז תתענג על ה' כו' כנ\"ל ודאי יומשך תוס' כח ועוז מאור זה להאיר גם את החושך הנה\"ט להיות גם מואס ברע כנ\"ל וראיה מאכילה דשבת כנ\"ל וכמ\"כ התורה נק' אור מבחי' עה\"ח שלמעלה מעה\"ד כנ\"ל ע\"כ יאיר אור דתורה גם בעה\"ד טו\"ר לברר וגם לאהפכא חשוכא לנהורא כנ\"ל בענין העץ שהשליך אל מים המרים וימתקו כו' אך אנו רואים שאין אור האלקי שבנשמה מאיר לחושך הגס דגוף רק לפי שעה לבד ולא הנפך טבעו הרע לגמרי מכל וכל גם שהוא מואס ברע לגמרי בעת תוקף האור האלקי בנשמתו וכן באור תורה בשעה שעוסק בה בלבד וכל זה מפני שנק' בשם אור עכ\"פ ויש הבדלה בין האור והחושך רק שבמקום אור נדחה החושך כנ\"ל וזהו הנק' קדושה שמנגד לזה סט\"א רק שנדחה הקליפת מפני הקדושה כו' (וכמו קומה ה' ויפוצו כו' וכן תרעץ אויב כנ\"ל) אבל מדרגה הב' בנשמות למעלה מזה הוא בשרשם הקדום שלמעלה מאור החכמה שנק' אויר קדמון כו' (וע\"כ נק' בשם רוח כמו והרוח תשוב כו') והוא כמו שהנשמה נק' נצוץ כנצוץ מן השלהבת וכמ\"ש רשפי' רשפי אש שלהבת יה ואעפ\"י שאנו רואים שהאש למטה מן האור אבל שרשו באש היסודי שבאויר הדק כנ\"ל כך בחי' שלהבת יה הוא למעלה מבחי' אור דיה וביאור הדבר הנה אנו רואים בהתפעלות אלקים ב' ענינים מחולקים ומשונים זה מזה הא' התפעלות אלקים שמצד אור הנשמה כמו בהלו נרו עלי ראשי וכן תהלל יה כו' כאה\"ר בתענוגים שהוא התפעלות הנפש מצד עצמה כפי שרש חוצבה באור החכמה שנק' אור אבא כמ\"ש כי אתה אבינו כידוע שאעפ\"י שיכול להאיר גם החושך לפעמים בחושך גם לא תאיר (וכן אור דתורה בחושך גם לא תאיר (וכן אור דתורה בחושך גס כמו העובר על התורה א' ולרשע מה לך כו' ונק' סמא דמותא כנ\"ל אבל ענין השני בהתפעלות אלקות הוא הנק' שלהבת יה שמתפעל ברשפי אש האלקי ממש שהוא דומה כמו אש הטבעי החומרי אבל הוא באמת בחי' שלהבת אלקי ממש כידוע לי\"ח (ורבים טועים בזה שמדמים התפעלות התשוקה האלקי' בבחי' שלהבת יה ממש להתפעלות חום הטבעי בלב בשר לא לה' רק שיחם לבבו שרחוקים זה מזה מן הקצה לקצה ממש) וכמו לבי ובשרי ירננו כו' הרי הלב בשר בוער באש שלהבת יה אז ודאי להפך חומריות התאות רעות כנראה בחוש שכל איש שלבו ובשרו יתלהב בלהב אש האלקי שנק' שלהבת יה יאכל אש הזרה החומרי שבלבו כאש אוכלת ויבערנו מעט מעט עד שנהפך לאיש אחר בכל המדות ותאוות רעות מכל וכל ואינו מואס ברע לפי שעה לבד כי נעשה לבו חלל בקרבו לבלתי יתפעל באש זרה לעולם מצד אש האלקי ששורף ומכלה לכל אש זרה שבלבו ונעשה גופו טהור הנק' הזדככות החומר כי אין טהרה רק שיצא מכלל טומא' כמו טהר יומא וכן כעצם השמים לטוהר שנק' טהירו עלאה (וזהו נשמה שנתת בי טהורה היא שלמעלה מקדוש' הנשמה במקור חוצבה כו' וזהו טהרה שמביא' לידי קדושה הנ\"ל וכתיב מי יתן טהור מטמ' לא אחד עצמו היינו מפני ששרש זה הכליון והזדככו' שיטהר הטמא באש האלקי האוכלת דאכיל ושצי הרע לגמרי הוא בא מבחי' אש היסודי שבבחי' אויר קדמון הנעלם הנ\"ל שביכולתו לעשות גם עצם החושך לאור והוא גם מה שלב ובשר דאש זרה החומרי יטהר מכל שמץ רע לגמרי ויוכל להאיר באור שלהבת יה ממש זהו יותר עליון מגופו של אור הנשמה שנק' נר ה' מטעם זה מפני ששם חושך ואור שוין שניהם כא' יאירו ולא עוד אלא שיש בשלהבת יה יתרון אור מאור המאיר"],[1700400377,"דחו\"ב שנק' יה מטעם הנ\"ל שבחי' אויר שקדם גם למקור האור כשתגלה יאיר בתוס' מרובה על עיקר האור וד\"ל (וכן באור דתורה כשנק' מאור שלמעלה מאור דחכמ' שמאיר בגילוי יש ביכולתו לבער הרע לגמרי וזהו כשנתנה באש שחורה דוקא לבער ולברר עה\"ד טו\"ר שלאחר הברור דעה\"ד עולה לשרשו שקודם לאור וזהו כי נר מצוה ששרשה למעלה מתורה אור ונק' משל הקדמוני שהוא בחי' אויר קדמון שלמעלה גם ממקור אור דחכמ' כנ\"ל וד\"ל) ובכל זה יובן בתוס' ביאור ענין ההפרש שבין התכלת והלבן שיש יתרון מעלה לתכלת ואכיל ושצי שנק' אשא אוכמא דאכיל ושצי על הלבן במה שגם החושך עצמו יאיר והוא ענין התשובה שמן החושך החומרי יאיר ויעלה למעלה (וע\"כ א' בבע\"ת שגדולים מצ\"ג וכר\"ע שרא' לנתן דצוציתא כו') מפני שנק' נצוץ שנמשך בשלהבת יה ששרשו למעלה ממקור חוצב כל הנשמות דצדיקים שנמשכים רק מבחי' האור האלקי הזרוע לצדיק עליון שהוא רק בחי' יסוד אבא כידוע וד\"ל ויובן כל זה עוד עפ\"י משל ההפרש בין מי שלא ראה חושך מימיו כנ\"ל למי שכל ימיו הי' בחושך ולא ראה אור כלל כשיראה אור יתפעל ביותר ויכיר יותר בהפלאת יתרון מעלת האור על החושך וגם יכיר ביותר שפלו' ערך החושך שהי' בו שלא הי' מכיר בתחלה כי כאשר לא ראה אור עדיין שם חושך לאור ולא ידע כי בחושך הוא אך לאחר שראה האור יכיר שפלות החושך וכן הניצול מן המות לחיים כמו חולה המסוכן או מוצל מלסטים ואש ונחש או מלחמ' יתפעל בנפשו הרב' יותר ממי שלא הי' עליו שום דבר רע ולא יוכל כל רע ומזיק לבא בגבולו עד שלא ראה מות ורע המזיק מעולם וכמ\"ש ההפרש בין בע\"ת שיוצא מן המות ורע לחיים וטוב שגדולים מצ\"ג שלא ידעו מרע ומות וכך הוא ההפרש בכלל בין בחי' או\"י שמצד תוקף גלוי האור כי טוב עד שלא ישלוט המות שם כלל וכמו לע\"ל דכתיב בלע המות לנצח כו' וכאדה\"ר קודם החטא בעה\"ד שהי' חי לעולם כו' אבל אחר ברור העה\"ד מכל רע הרי נהפך המות לחיים זהו יותר גדול שזהו ענין תחה\"מ כנ\"ל וה\"ז כמי שהי' בחושך ויצא לאור גדול שהתפעלותו נפלאה מאד כניצול מן המות לחיים זהו מעלת יתרון האור מן החושך עצמו הנ\"ל וד\"ל:\n(יז) <b>וזהו</b> וזכרתם את כל מצות ה' כו' ולא תתורו אחרי לבבכם כו' וקאי הכל על ראי' דתכלת כמ\"ש וראיתם אותו וזכרתם כו' דהנה מבואר למעלה שהתכלת הוא אשא תכלא כו' והוא בחי' המל' שע\"ז אמר כי ה' אלקיך אש אוכלה הוא כו' וכמ\"ש כהמס דונג מפני אש כך ממש יאבדו כו' והוא ע\"י קבלת מ\"ש באימה ופחד כמו הרואה את המלך ברוממתו וגדלותו תיפול עליו אימתו לקבל עול מצותיו ושלא ימרוד בו לקבל עול אדון זולתו כך וראיתם אותו דתכלת שהוא בחי' הגבורות דמל' ממילא עי\"ז יזכור על כל מצות ה' שהוא מצות המלך כמ\"ש שום תשים עליך צלך לעשותם והוא מצות הוי' להאיר את החשך שבנפשו משם הוי' שבכל מצוה יו\"ד צמצום כו' וה\"ז כמו מי שהי' בחשך כל ימיו וראה אור שיתפעל ביות' כנ\"ל משא\"כ אם לא יראה אור שם חשך לאור והולך בשרירות לבו ופורק עול לגמרי אבל בראותו את האור יכיר יותר הפלאות האור מן החשך ויכיר יותר פחיתת ערך החשך שהי' בו עד הנה וממילא יתפעל לסור מכל רע ולא ילך אחר ההבל בשרירות לבו והא בהא תליא מצד יתרון האור ועל החשך הרבה כמו היוצא מן המות לחיים ממש כנ\"ל וזהו וראיתם אותו כו' כאשר יראה אור האלקי בנפשו בקבלת מ\"ש שלימ' וזכרתם לשם הוי' שהוא האור וממילא ולא תתורו כו' כי אז יכיר וידע יותר איך שהיה בחשך גס וחומרי וימאס מאד בהבלי תענוגי עה\"ז החומרי ולא יחפוץ לקבל שום תענוג זר בלתי לה' לבדו וזהו ולא תתורו ממילא לא תתורו אחרי לבבכם לא יתן אור לבו לתור ולימשך אחר ההבל לטמא נפשו להיות כזונה לקבל שפע מזרים"],[1700400378,"שהן כתרין דמסאבותא וז\"ש אשר אתם זונים אחריהם דהנה עד\"מ הזונה שתזנה תחת בעלה ותלך אחר מנאפי' לקבל שפע תענוג מהם ולהתקשר עמהם באה\"ר בתענוגים נק' בחי' מקבל שתקבל לה משפיעים אחרים זולת בעלה גם שלא תעזוב לבעלה זונה היא כו' וכך יובן בכנ\"י שנק' כלה שהן בחי' מקבל לקבל אור האלקי בתוך תוכם במוח ולב כאשה שכורתת ברית לבעלה ואינה נזקקת אלא לבן זוגה כך כנ\"י לב א' להם לאביהם שבשמים כמ\"ש מי לי בשמים ועמך כו' בלתי לה' לבדו והיינו שלא יהיה לאדם רצון אחר זול הרצון והדביקות לה' לבדו ואם דבר זה אינו רק בעובדי ה' בתמידות כל היום בתורה ומצות ובאהבה ודביקות והתקשרות אמיתית בה' לבדו כצדיקים הגדולים כמו אמר דוד בכל לבי דרשתיך וכן נכספה וגם כלתה נפשי כו' צמאה לך נפשי כו' וכה\"ג היה יותר באבות שהן המרכבה כמ\"ש באברהם התהלך לפני וכה\"ג אבל בסתם בנ\"י שטרודים בעסקיהם ופרנסתם בכל כלי מוח' ולבבם ומחשבתם קשורה תמיד בהבלי עולם גם שהן בדברים מותרים כעסק פרנסה וכה\"ג דכתיב ואספת דגנך ואמרו הרבה עשו כרשב\"י ולא עלתה בידם ורוב ההמון תורתם עראי ומלאכתם קבע אך עכ\"ז זה ביכולת כל אדם מישראל שלא יהיה להיפך עכ\"פ דהיינו שלא יהיה כזונה שמורדת על בעלה והולכת אחרי מנאפים זרים כו' והוא שלא יהיה אדם סר לבו ודעתו וישכח על ה' לגמרי כמ\"ש השמרו פן יפתה לבבכם וסרתם כו' ואם אינו עובד ע\"ז בפו\"מ אבל הרי אמרו ישראל שבח\"ל עובדי ע\"ז בטהרה הן לפי שכל לבבם מקושר ופונה רק אל ההבל ולא יבטח בה' שהוא המשפיע לו כל חיות פרנסתו וממנו מקבל כל שפעו ברוחניות וגשמיות ולא יאמר שמקבל שפעו עפ\"י הטבע מן המזלות אשר חלק ה' אותם לכל העמים וע\"ז א' אותי עזבו מקור מים חיים לחצוב להם בארו' שברים שאין מזל לישראל כי חלק ה' עמו כו' וכן בהתקש' אד' לילך לקבל בנפשו תענוגי' זרי' מהקליפו' שנק' כתרין דמסאבות' וידוע שהן כחות הטומא' שמשפיעי' כל מיני טומאה במ\"ז וכל הבלי רצונות תענוגים זרים שלא לה' המה וכו' וכמו שאמרז\"ל המביא עצמו לידי הרהור זנות במזיד אין מכניסין אותו במחיצתו של הקב\"ה כו' לפי שבהתקשרות נפשו במזיד בהרהור זנות הזה מביא וממשיך ע\"ע כח הטומאה דרוח אייתי רוח ואמשיך רוח בסט' דקליפה כמו בסט' דקדושה דאת זלע\"ז עשה האלקי' ונמשך עליו משפיע זר' מסט\"א לטמא ולשחת נפשו בכל טומאה והוא שמביא לידי קרי בליל' כמ\"ש בזהר והו' מה שהזהיר ולא תתורו אחרי לבבכם (כמ\"ש בר\"ח באורך) שלא יכין לבבו להיות כמו זונה לילך לקבל רצונות זרים ממשפיעים זרים מסט\"א לומר בשרירות לבי אלך כו' והיינו שלא יתור אחר לבבו ואחרי עינו כו' להיות בחי' נוק' לקבל מהם רצונות ותענוגי' זרים שישפיעו לו בהכרח גם אם לא יחפוץ מפני שכבר העלה והכין לתור אחר לבבו ולהיות זונה אחריה' וכמ\"ש אשר אתם זונים אחריהם כמו הזונה ממש שתכין עצמה לילך ולתור אחרי מנאפים כו' ואם שלא עזבה את בעלה אבל עשתה העיקר טפל כו' וכך נאמ' כי קצר המצע מהשתרע מהשתרר עליו ב' רעים כא' וזה יראה כל אדם בנפשו אם לא ירצה להטעו' א\"ע שלבבו חלק מיעוטו להש בפיו ושפתיו יכבד מן השפה ולחוץ בתפלה ותור' ואם אפס קצה הלב מתפעל אבל הוא כטפל לגבי עיקר בהטותו נקודת לבבו רק לרע כל היום לכל אשר טמא טמא יקרא אליו נושא את נפשו וכל לבבו לטמאות נפשו בכל מיני רע שמשפיעים לו כתרין דמסאבותא שנק' שערי טומאה מצד שהוא כלי ראוי לזה מאשר כבר הכין לבבו לדרוש ולקבל כל תועבה אשר תאב ושנאוי בעיני ה' שע\"ז הזהיר לא יהי' לך אלקי' אחרי' כו' וכמאמר הבא לטמא פותחין לו שע\"ט הבא לטמא הוא ממש אשר אתם זונים אחריהם כזונה שמוכנת ליזקק לזר זולת בעלה כו' וזהו שהוכיח אליהו לעובדי הבעל עד מתי אתם פוסחים על שתי הסעיפים אם ה' האלקים לכו אחריו ואם הבעל כו' דודאי היו עובדי' את ה'"],[1700400379,"בקרבנות ומאמינים באחד אך גם לבעל היו עובדי' והוא מ\"ש קצר המצע כו' כך גם עתה בגלותינו עובדי ע\"ז הן בטהרה ואת ה' וזהו וזכרתם כו' ולא תתורו כו' שלא ישכנו כא' בלב ח\"ו אלא לב' א' יהי' לה' לבד ואין זר אתו וגם אם טרוד בעסקיו וחושב מחשבות רבות שלא לה' אבל הכל יבטח בה' וישליך על ה' יהבו וכו' ולא יביא עצמו לידי הרהור זנות וכל מחשבת עון במזיד בשרירות והכנת לבו לרע אדרבה בנפול לו איזה מחשבה רעה ידחנה ויצר לו מזה ויעשה תשובה ועכ\"פ בזה אינו נקרא זונה ואין בלבו משפיע אחר זר זולת ה' לבדו בתפלה ותו\"מ ובזה יש יכולת לכל אדם וד\"ל ומ\"ש ולא תתורו לשון ממילא היינו שכאשר הכין לבבו נדרוש אלקים לבדו ולא לפנות אל רצון זר זולתו הכנה זו בלב שלא ירצה להטות לבבו לחפוץ בכל דבר רע וטמא המטמא נפשו היינו הנק' טהרת הלב שמטהרנו מכל סוג ואז נק' בר לבב שהוא אשר לבו לא חפץ בכל טומאה וזורק מלבו לגמרי הוא אשר לא יתור אחרי לבבו ממילא וזה בא מחמת שכל לבו הכין לדרוש אלקים בלב א' שלם לאביו שבשמים לבדו ואין זר אתו כלל והיינו ע\"י הראיה דתכלת ע\"י קבלת עמ\"ש שלימה בנפשו בהתבוננות גדולת אימת מלכותו ית' בהכרה טובה שבלב ומוח שאז דוקא מתוך האור הזה יכיר יותר איך שהוא בחשך גס וחומרי ויברח וימאס בהבלי רצונות תענוגי עוה\"ז ולא יתור ממילא כו' כנ\"ל וד\"ל ואמנם אם לא היה רואה אור האלקי בנפשו במצות מ\"ש שלימה עפ\"י ראיה דתכלת כנ\"ל לא ירגיש בעצמו שהוא בחשך ורע ולא יתן לבבו לזה כלל ונדמה לו שאינו בחשך כלל ושם חשך לאור שממילא אינו נותן לב לבלתי ילך אחרי ההבל וכל רצון ותענוג זר יקבל בלבו באין מרגיש כי ברע הוא כלל וכו' וזהו עיקר התערובת קשה שבפיו ולבו בתפלה ותו\"מ לה' וכל היום הולך אחר כל תאות לבו רק רע ואינם סותרים זא\"ז כלל כי דרך האויל בעיניו ולא יכיר בפחיתת ערכו כלל וכל דרכיו זך וישר רק כשרואה א\"ע נקי מעבירות חמורות וגם זאת מיקל לעצמו וכו' אבל כל שיכיר באור האלקי יותר יותר ירגיש בנפשו אפי' עון שדש בעקביו כו' וגם תאות היתר יצר לו עד שרואה א\"ע כמו ברע ממש המגשם לבו ודעתו בדקות שבדקות כטמטום הלב והמוח כידוע וזהו עיקר ענין התכלת דאכיל ושצי גם לרע הדק שבדקות כו' וד\"ל:\n(יח) <b>והנה</b> מעתה יש להבין ענין ההפרש בין זכירה ראשונה דוראיתם אותו וזכרתם את כל מצות ה' לזכירה שניה למען תזכרו כו' את כל מצותי ולמה כפל הדברים וגם למה הזכיר קדושה בזכירה שניה והייתם קדושים לאלקיכם ולא הזכיר בזכירה ראשונה והנה יש להקדים תחלה בביאור ענין הפסוק שמסיים בפ' זו והוא מ\"ש אחר ב' הזכירות אני ה' אלקיכם דוקא ויש להבין תחלה מ\"ש אני הוי' מהו פי' אני דהנה ידוע בפי' אני ואנכי שהוא כמו שאדם או' ע\"ע אני שמשמעו שהוא איש ידוע לכל מי הוא כו' וזה א\"א למעלה באלקים חיים שהוא ידוע לכל בכל העולמות דהידיעה הוא ענין התפיסא וההכרה בעצם מהותו מה הוא ובאמת הרי הוא ית' סדכ\"ס ולמחת\"ב כלל וכלל לא בנאצלים וגם לא למעלה מאצי' שנק' סתימי' הוא סדכ\"ס ועלאה על כל עלאין ולא ידע ליה בר איהו כו' ומה שנודע לנאצלים ולנבראים כו' אין זה עצם מהותו רק בחי' הארה דהארה מעצמו' אורו הפשוט כמ\"ש באורך נראה אור והוא ע\"י צמצום הראשון הנק' מק\"פ וחלל כו' כידוע בע\"ח אך הנה ידוע בס' הקבלה בפי' אני שהוא אותיות אין והוא בחי' אור הכתר בכלל שנק' אין כמו היש ה' בקרבינו אם אין כנז' בזהר וכמו והחכמה מאין תמצא ונק' ג\"כ אני והיינו לפי שאור הכתר הוא בחי' ממוצע בין עצמות המאציל לנאצלים ופנימי' כח\"ב שבו הוא סוף עצמו המאציל וחצוניו' שבו הוא נק' שרש וראש לנאצלים והיינו מבחי' חכמה שבכתר"],[1700400380,"בחיצוניות שבו שנחלק לג' קוין חח\"ן מימין כו' כמ\"ש בפרד\"ס בשע' הצינורות וכידוע בע\"ח שכאשר הכתר נמנה עם הי\"ס הוא מן בחי' חצוניות שבו זהו בחי' אני שידוע מפני שנעשה שרש לנאצלים וכשאינו נמנה עמהם הוא הנק' אין בחי' כתר שבכתר כו' וביאור הדברים הנה יובן עד\"מ מבשרי אחזה כו' בהיות ידוע שנפש האדם כלולה מה' מדרגות נרנח\"י ונר\"נ מלובש בג' כלים מוחא ולבא כו' ובחי' חי' יחידה נק' מקיפים שבלתי מוגבלים בכלים כלל והוא ענין ל' מ\"ם דצלם כו' ובאור הענין ידוע שבחי' נר\"נ הרי הנשמה משכנה בכלי המוח בבחי' או\"כ צורה וחומר כאור הראיה במזג חומר העין כך אור השכל משכנו בחומר כלי המוח וגם מקיף שבו הוא לפ\"ע האו\"כ כו' וכמ\"כ משכן הרוח בלב הרי הרוח שורה בלב בבחי' או\"פ בכלי כצורה בחומר וכמ\"ש תוכן לבות ה' תוכן רוחות כו' ואין לב א' דומה לחבירו ואין שכל והשגה של זה דומה לזה כמ\"ש נודע בשערים כו' וא' בזהר בכל חד לפום מה דמשער בשכלו ולבו שנק' נשמה ורוח וכן בחי' נפש שהוא המעשה שהדם הוא הנפש ואדם א'ד\"ם והיינו בג' כלים אלה מוח ולב ומעשה שהן בחי' כלים לנר\"נ ובצלם אלקים כו' כך הוא למעלה בחי' נר\"נ דאדם העליון דאצי' שנק' מוחא ולבא כו' וכידוע דאור החכמה דז\"א דאצי' שוכנת בכלי שהוא מוחא ומדות חג\"ת דאצי' בלב אדם העליון כמו ויאמר ה' אל לבו כו' ודרך כלל או\"א דאצי' נק' חו\"ב וז\"א הוא בחי' המדות שבלב ומל' הוא בחי' הדבור והמעשה כו' אבל למעלה מבחי' חו\"ב דאצי' שהוא בחי' כ\"ע הוא למעלה מהתלבשות או\"כ וזהו כמו בחי' מקיפי' דנר\"נ שבאדם התחתון שנק' חיה יחידה שאין משכנה בבחי' כלי מוגבל בבחי' צורה וחומר כלל וביאור הדבר ידוע שזהו בחי' אור הרצון והתענוג שבנפש האדם למטה שאין להם בחי' כלים כלל שישכנו בהם ואע\"פ שאור הרצון משכנו בכל אברי הגוף כי גם אברי האדם נשמעים לרצונו אבל אינו שורה בהם בבחי' או\"כ כלל כי א\"א לומר שמהות המחשבה ורצון מלובש ברגל להניעו כשרוצה כי אין ערך חיות הרגל להיות כחומר לצורה אור הרצון הרוחני כלל וגם גידי המוח שהרצון מלובש שם אינו בגדר כלי אליו כמו הרגל ומ\"מ ע\"פ הרצון שבמוח יתנהג כל תנועה שבאברים וכן התנהגות המדות שבלב יהיה ע\"פ הרצון וכן גם במדות שבשכל לחו\"ג כידוע ומבואר במ\"א וא\"כ שורה הרצון בהשוואה א' בכל כחות הגוף מן השכל עד תנועת חצוניות שברגל בשוה וזהו הנק' מקיף כללי שסובל ומלובש בתוך הכל בשוה ומושלל מהם בבחי' מקיף על הכל וכמ\"כ אור התענוג שמתלבש בשכל ובמדות ובמעשה בכל א' בפ\"ע כמו בראי' ודבור וריח וכו' ולא בבחי' או\"כ כלל וכלל ואמנם זהו בחי' מקיף דחי' שהוא עכ\"פ שורה בהשוואה א' כו' (וכמו החרדה שנפל על אנשים שהיו עם דניאל דמזלייהו חזי ועשה רושם בגופם במוחם ולבם וכן התעוררות תשובה מצד מזלי' שהוא אור המקיף דחי' וכה\"ג) אבל מקיף דיחידה הוא למעלה גם מהיות בחי' מקיף בהשראה בגוף כידוע והוא בחי' מ\"ם דצלם שדבוק למעל' ואינו בא ולמטה בגוף כלל וכמ\"ש במ\"א באריכות וזהו את השמי' ואת הארץ אני מלא בשוה שזהו בחי' סובב הכללי ונק' כתר עליון שהוא בחי' ממוצע ונק' בחי תחתונה שבעצמות כנ\"ל והוא שרש וראש לנאצלים כו' והיינו כמו ב' מדרגות דחיה יחידה הנ\"ל דמה שכ\"ע מקיף כללי לאבי\"ע זהו כמו בחי' מקיף דחי' באדם ששורה בראש וסוף בהשוואה א' כו' ולגבי עצמות אא\"ס הוא רק בחי' האחרונה שעצמות המאציל מתנשא ומרומם לבדו כו' ונק' סדכ\"ס דלמת\"ב כלל אפי' מחשבה הקדומה שסוקר הכל כא' שהוא סובב הכללי דרצון ותענוג אין לו בו תפיסא כלל וכמ\"ש עושה פלא וכו' וכמו בחי' מקיף דיחידה כו' וד\"ל ולמטה באדם התחתון ידוע שהן ב' מיני רצון א' רצון מורכב בשכל ולב ומעשה בהשוואה א' והוא כמקיף דחי' הנ\"ל שמעורר למעלה ג\"כ מקיף וסובב דכ\"ע אבל לא בכלים דנר\"נ כ\"א ברצון שלמעלה מן הטעם כו' בזה ממשיך תוס' אור מהעלם דכ\"ע בע\"ס דאצי' בחכמה ומדות עד שנמשך תוס' אור"],[1700400381,"בע\"ס דבי\"ע כמו יהי רצון מלפניך שיכבשו רחמיך כו' וכידוע והן ח\"י ברכות דש\"ע אבל בסדכ\"ס עצמו גם זה הרצון לא יגיע כ\"א במס\"נ בכל עצם נקודת הנפש שלמעלה גם מבחי' רצון ותענוג להתענג על ה' כו' והוא הנק' רצון פשוט ועצמי כידוע שזהו דוקא בבחי' בטול הרצון כבע\"ת וכטהרת הלב מכל רע הנ\"ל שהטהרה מביאה לידי קדושה שיומשך מקדש הקדשים שהוא עצמות אור א\"ס ממש להיות שורה בתו\"מ שעושין כו' וזהו והייתם קדושים לאלקיכם ע\"י טהרה דוקא שמביאה לקדוש' וכמשי\"ת ב\"ה וד\"ל וזהו פי' אני הויה אני אותיות אין שיש ב' מדרגות בכתר א' כשנק' אני שידוע מי הוא והוא כאשר יאיר בחי' סובב הכללי הנ\"ל שהוא בבחי' אור רצון ותענוג העליון בבחי' מקיף בחו\"ב ומדות דאצי' עכ\"פ נק' אני ושרש המשכתו הוא בא מן ההעלם שבעצמות המאציל שנק' אין דלית מחשבה תפיסא בי' כלל לגלוי עכ\"פ הרי זהו שמאין נעשה אני שמהעלם פנימי' הכתר שנכלל בעצמות נמשך לגלוי להיות בבחי' מקיף בהשראה בשוה כמו את השמים כו' אני מלא דלית אתר פנוי מיני' אע\"פ שהוא הכל בהעלם ולא בגלוי או\"כ כלל כנ\"ל מ\"מ שורה בהם עכ\"פ עד שגם בע' שרים של מעלה אמר כמצביי' עביד בחיל שמיא וכן אנו אומרים ומסדר הכו\"מ כרצונו להשפיל ולהרים שזהו הרצון שמלובש ברגל וכידוע שהארץ נק' הדום רגליו כו' וכמ\"כ ברצון זה עצמו מאיר לראשית דאור ח\"ע דאצי' כו' וגם הוא מקיף לכללות אבי\"ע בשוה ממש וזהו מאמרז\"ל הוא מקומו של עולם פי' סובל ומלובש בתוך כ\"ע בשוה כנ\"ל ואין העולם מקומו כלל כאשר הכתר אינו נמנה עם הספי' והוא כשנק' אין ופלא ולא נמשך להיות מאין אני ומתפלא אלף מקור לחכמה כו' ואמנם אין ואני שהוא פלא ואלף שוין ממש לגבי עצמות הא\"ס ממש שכל זה שייך לענין השפעה עכ\"פ שיהיה מאין ההעל' אני בגלוי וכן מפלא אלף וכמ\"ש עושה פלא שעושה מפלא אלף או שגם הפלא דאין דכתר עשי' נחשב כו' שהרי בשעה שהוא מקש\"ע אין העולם מקומו כו' וראיה מהשראת אור העצמות בהיכל ק\"ק כנ\"ל בפי' עוטה אור כו' ואמנם מ\"ש אני הוי' פי' אני בעצמי ממש ולא כסדר ההשתלשלות דאין ואני הנ\"ל דלפעמים נק' אין מופלא ולפעמים אני אלא אני זה בגלוי אור אור העצמות ממש משום שע\"י תו\"מ בפו\"מ שורה למטה כמו למעלה בעצמותו ממש בלי הפרש בין מעלה ומטה כלל והיינו אני כמו שאני בעצמותי ממש הוא הוי' אלקיכ' דוקא שלא נתפס אפי' במחשבה קדומה כו' וזהו ראו כי אני אני הוא ואין כו' פי' שיש ב' מדרגות באני כמ\"ש אני ראשון ואני אחרון דהיינו אור הכתר הממוצע בין המאציל לנאצלים וזהו אני ראשון שלפי האצי' ואני אחרון הוא בחי' מל' דאצי' שנעשה כתר לבי\"ע שגם שם מאין נעשה אני מן ההעלם לגלוי דכמו שאין ערך לאצי' לגבי המאציל כך אין ערך לבי\"ע לאצי' ומ\"מ אני ראשון ואני אחרון דנעוץ תחלתן בסופן וסופן בתחלתן ששניה' שוין בהשוואה א' ממש משום דלגבי אור העצמות ממש אני ראשון שלפני האצי' עם אני אחרון שאחר האצי' שניהם שוין וזהו מ\"ש ראו כי אני אני הוא כו' שאין בו בחי' מעל' ומטה כלל וכמ\"ש במ\"א על פסוק המגביהי לשבת המשפילי לראות שבשעה שמגביהי לשבת בעילוי אחר עילוי עד אין שעור למעלה בעצמות אז דוקא הוא משפילי לראות כו' וכן מא' הוא מקומו של עולם כו' ואיהו תפיס בכ\"ע ואז למדת\"ב וזהו מצד אור העצמו' וזהו אני הוי' אני ממש שמתלבש בשם הוי' שבתו\"מ שהוא למעלה הרבה מן הוי' שבד' עולמו' דאבי\"ע אצי' יוד כו' ומה שהשפלתי א\"ע להקרו' בשם הוי' באורות וכלי' דע\"ס דאצי' זהו רק כדי שיהי' הויה אלקיכם דוקא בתו\"מ והוא מפני שסוף עלה במחשבה תחלה שישראל עלה במחשבה וכמאמר במי נמלך בנשמתן של צדיקים שיקיימו תור' ומצות בפו\"מ דוקא ששמי הוי' העצמי ממש הוא בתו\"מ בפ\"מ וכמ\"ש ושמי הוי' ממש לא נודעתי להם וכנ\"ל בפי' נראה אור דעוה\"ב שהוא מן המצוה בפו\"מ"],[1700400382,"דוקא זהו הי' הגורם להיו' במקום גדולתו ענוה יתרה להאציל ולברוא כו' וזהו אני הויה אלקיכם דוקא וד\"ל:\n(יט) <b>וזהו</b> והייתם קדושים לאלקיכם דהנה סדר הדברים כך הם וראיתם אותו וזכרתם ואח\"כ ולא תתורו כו' שזהו ענין הטהרה שמביאה לידי קדושה האלקית ואם לא יוקדם הטהרה תחלה עדיין אין מקום להשראת הקדושה להיות נק' קדושים לאלקיכם וזהו שאחרי מ\"ש ולא תתורו אחרי לבבכם אז דוקא אמר למען תזכרו כו' והייתם קדושים כו' דטהרה מביאה לידי קדושה אך א\"כ איך אמר תחלה וזכרת' את כל כו' ע\"י התכלת ואם הקדושה דמצוה בטהרת הלב תלוי' כמו וטהר לבינו לעבדך באמת והעבודה היא במצות איך יאמר וזכרתם את כל מצות ה' כו' תחלה אך הנה באמת ב' מדרגות יש בקדושה א' במצות הויה והב' קדושת עצמותו ממש כמ\"ש בסמוך בזכירה שני' ועשיתם את כל מצותי שז\"ש בברכת המצות אשר קדשנו במצותיו והיא לא באה רק אחר הטהרה וכמו וטהר לבינו לעבדך אבל קדושה ראשונה שבזכירה ראשונה שהוא הקדושה שבמצות הוי' קודמת לטהרת הלב הנכלל בלא תתורו כו' ולהבין כ\"ז יש להקדים תחלה בשרש ענין הקדושה למעלה דהנה ידוע בפי' קדוש לשון הבדלה והפרשה שנבדל בערך כמ\"ש קדושים תהיו פי' מובדלים וכמו אל תגש בי כי קדשתיך כידוע ולא שייך לשון זה רק שקדוש ומובדל מזולתו הקטן בערך ממנו אבל כשהוא יחידי ואין לו חבר להתייחס עמו גם לא בהבדלת הערך ויחוס לא שייך כלל לשון קדושה והבדלה כידוע וכך יובן למעלה שבעצמו' אא\"ס ממש לא שייך ענין קדושה כזו שהיא ההפלאה והבדלה רק באור המאיר מעצמותו להיות מקור חיי כל העולמות ששם יתכן שיהיה נק' אור מופלא ונעלם וסתו' כנ\"ל בפי' אני ואין כו' שזהו בחי' הקדושה ג\"כ כמלאכים למטה שאו' קדוש וכך למעלה מעלה גם לפני האצי' כמ\"ש אין קדוש כהויה כו' וזהו כשבא אא\"ס בכלל השתלשלות דע\"ס או\"כ שהוא שם הוי' בכלל וגם למעלה מאור החכמה שהוא הכתר שנק' קדש העליון או קדש הקדשים גם אור זה אוכם הוא לגבי עה\"ע דלית מח' ת\"ב אפי' מח\"ק כנ\"ל אך כ\"ז היינו בבחי' השתלשלות דמפני שאין ערוך לבריא' עם הבורא וכן מאצי' למאציל וכך עוד עד עצמות א\"ס ממש יתכן לשון קדוש' מעליון לתחתון שנבדל הימנו בערך וכן מתחתון לעליון מפני שקדוש ומופלא העליון מן התחתון כו' אבל יש עוד בחי' קדושה עליונה מזו והוא בבחי' עצמות אא\"ס ממש אך לא שענינו קדוש ומובדל ומופלא מההשתלשלות דקו\"ח כו' אלא קדושה זו נק' קדושת העצמות ממש שהיא רק מצד עצמותו לבד ולא שייך לענין ההשתלשלות כלל וביאור הדבר ידוע ומבואר במ\"א ע\"פ קדושים תהיו אמרז\"ל יכול כמוני ת\"ל כי קדוש אני קדושתי למעלה מקדושתכם הרי קדושה זו שקדוש מצד עצמו גדולה הרבה מקדושת המצות שעי\"ז נק' ישראל קדושים וז\"ש כי קדוש אני בעצמי ע\"כ אני הוי' מקדשכם וכן ונקדשתי בתוך כו' והענין הוא כידוע דעצמו' אא\"ס ממש הוא למעלה מעלה בעילוי אחר עילוי בעצמותו עד אין שעור ולמטה מטה עד אין תכלית ומה שהוא ית' בבחי' עלי' בעצמותו לאין שעור הוא הנק' קדושת עצמותו דוקא ומה שהוא בבחינות ירידה למטה עד כו' נק' ברוך וזהו פי' הקב\"ה כידוע ועל בחי' קדושת עצמותו שאין לה שעור למעלה הוא למעלה מעל' מכל קדושה שהוא לגבי ההשתלשלו' דאבי\"ע כו' וד\"ל וזהו כי קדוש אני קדושתי קדושה שמצד עצמותו ממש למעלה מקדושתכם שע\"י המצות כי הנה הגם שבמצות שהן פנימי' רצונו הפשוט שבודאי נמשך בהן בחי' אור קדושת עצמותו שלמעלה מעלה כו' ולז\"א קדושים תהיו כו' וכמ\"ש אשר קדשנו במצותיו ולכך א\"א וישמחו בך ישראל מקדשי שמך וכמ\"ש במ\"א בענין קידוש השם הזה שהוא שמו העצמי"],[1700400383,"שנק' שמך ממש אזל אין זה רק אפס קצה ההארה מקדושת העצמו' ממש שנמשך ומתלבש בקדושץ המצות (וכנ\"ל בפי' חוטי לבן במ\"ש לבושי' כתלג כו') ולכך א' קדושתי למעלה מקדושתכם כו' ואמנם מפני שישראל ממשיכין לקדושת עצמותו לבא בהלבשה במצות נק' גם הם קדושים לאלקיכם להתייחס בערך קדושת עצמותו ומ\"מ נבדל קדושתו מקדושתכם וכמ\"ש בזהר ע\"פ אין קדוש כה' כמה קדושאן אית לעילא אוריי' קדישא וישראל קדישי אך אין קדוש כה' כו' הרי גם שרש קדושת התו\"מ לא יגיע לקדוש' עצמותו ממש רק לעוה\"ב שיתגלה קדושת עצמותו ממש ואז יגיעו לקדושת העצמות ממש ע\"ד שאמרו עתידים צדיקים שיאמרו לפניה' קדוש כו' לפי שאדם אדמ' לעליון ממש יהי' בעוה\"ב דוק' וד\"ל וזהו שאנו או' נקדישך שאנחנו ממשיכים אותו להיות בבחי' קדוש וזה פלא איך נש\"י שבגופים ימשיכו לקדושת העצמו' שנבדל בערך לגמרי מקדושה זו שנק' קדוש לגבי העולמות כנ\"ל ועוד שאין מלאכים או' קדוש עד שישראל או' כו' הענין הוא מטעם דנעוץ תחלתן בסופן דוקא דהנה ידוע שיש במצות ב' מדרגות א' כמו שהמצות הן למעלה מעלה בעצמו' פנימי' רצונו הפשוט שמגיעי' בקדושת העצמו' ממש שאין לו שעור למעלה כנ\"ל והן הנק' מצותי ממש כמו הקדב\"ה מניח תפילין ומתעטף בציצית ועוסק בתו' ועושה צדקה וחסד כו' שזהו הבא בגלוי לעוה\"ב דוקא כנ\"ל דקדושת העצמו' ממש לא יתגלה רק בעוה\"ב מטעם שאז יתגלה כל עצמות קדושתו שבמצותיו ממש וכמ\"ש להנחיל אוהבי יש יש האמיתי כו' והוא בא מן מעשה המצוה בפו\"מ שבעוה\"זדוקא וע\"כ כל ישראל יש להם חלק לעוה\"ב ואפילו פ\"י כו' והוא מדרגה הב' שבמצות כמו שהן נעשים למטה בפ\"מ ועושין בהם יחודי' עליונים למעלה בע\"ס או\"כ כמו במצות ת\"ת בפ\"מ נעשה היחוד בגלוי תוס' אא\"ס באור אבא וכן במצות שמירת שבת דהיינו יוד דשם הויה בתפילין בה\"א וכו' וכה\"ג הכל נק' מצות הויה בכלל ובפרט בכל מצוה ומצוה רק למטה בא האור בהתלבשות בגשמיות המעשה והוא אותיות מ\"ץ דמצוה שהוא בחלוף א\"ת ב\"ש די\"ה כו' ונק' קדושה זו שבמצות הויה באצי' עד התלבשותו בגשמיות קדושת שם הויה כמו ענין מקדשי שמך וכן פי' נקדישך שמאנחנו עושין קדושה זו ואמנם שרשה היא למעלה מעלה הרבה מכל קדושאן דלעילא באבי\"ע ע\"כ א' גם דאורייתא וישראל קדישין באמצעות קדושת המצוה אך מצד שרשה בקדושת העצמות ממש א' קדושתי למעלה מקדושתכם שע\"י המצות ומ\"מ הא בהא תליא שמחמת בחי' קדושה זו שע\"י המצות עכשיו דוקא יתגלה בחי' קדושת העצמות שבמצותיו ממש בעוה\"ב וזהו שכ\"י כו' כנ\"ל והיינו משום דנעוץ תחלתן בסופן דוקא וד\"ל ובכ\"ז יובן ענין ההפרש בין זכיר' ראשונה שא' וזכרתם למצות הוי' לזכירה שניה שא' למען תזכרו את כל מצותי ולא הזכיר מצות הויה כנ\"ל דמצות הויה הוא בחי' קדושה שני' הנ\"ל שנמשך אפס קצה ההארה מקדוש' העצמות ממש בקיום התו\"מ בפו\"מ שנק' מצות הויה דוקא להיותו שרש כל היח\"ע בתוס' אור א\"ס בע\"ס או\"כ שהן בכלל ד' אותיות דשם הויה יו\"ד ע\"י מצות ת\"ת ושבת וכה\"ג וה\"א ע\"י ק\"ש ותפילין וכנ\"ל וזה קודם להיות ממצות שלנו בחי' הכנה רבה להיות בחי' גלוי קדושת העצמו' שבמצותיו ממש בעוה\"ב כנ\"ל שהוא קדוש' העצמו' שאין לו שיעור למעלה והוא שא' בזכירה שני' והייתם קדושים לאלקיכם בבחי' קדושת עצמותו ממש וכמו אשר קדשנו במצותיו וזהו שלא הזכיר בלשון מצות הוי' אלא מצותי ממש וכידוע בפי' מצוה לשון צוותא והתחברות ומצותי היינו ענין התחברות אור עצמותו ממש שבמצותיו שהוא מתייחד ומתחבר בהן כמו שהן בעצמותו ממש כנ\"ל וד\"ל וזהו ג\"כ הטעם שבזכירה ראשונה לא הזכיר לשון קדוש' כי עיקר קדושה העצמי' הוא לע\"ל וזהו פי' והייתם קדושים להבא משמע שהוא בעוה\"ב בשכר מצוה והיום לעשותם ולמחר כו' וגם קדושת שם"],[1700400384,"הוי' שבכל מצוה היא בהעלם רק להוסיף אור באצי' בלבד וכ\"ש קדושת העצמו' לע\"ל שנא' בזה עין לא ראתה כו' רק יעשה למחכה לו בעוה\"ב וכמ\"ש באורך נראה אור בעוה\"ב דנראה לשון להבא דוקא ופי' נראה אור אור העצמו' ממש אבל באורך דוקא נראה אור הגדול והקדוש שבקדוש' עצמותו ממש שהוא אורך העצמי הגנוז ומלובש בסו' מעש' במצו' דעכשיו דוקא משו' דנעוץ תחלה כל התחלות שבעצמות ממש בסוף הכל דוקא וכמ\"ש סוף דבר כו' ואת מצותיו שמור בפ\"מ דוקא כי זה כל האדם כו' כל האדם דאדם אדמה לעליון ממש שיהי' בעו\"הב דוק' וד\"ל:\n(כ) <b>וזהו</b> למען תזכרו ועשיתם את כל מצותי כו' פי למען תזכרו קאי אדסמיך ליה ולא תתורו כו' שהוא הטהרה שמביאה לידי קדושה הנ\"ל וזהו למען תזכרו שזכיר' שניה זו ההיא לעשות מצותי שבה קדושת העצמות שלמעלה הרבה ממצות הויה שבזכירה הראשונ' שע\"י ראיה על התכלת כנ\"ל וזה פלא גדול לכאורה איך ע\"י טהרה מן הרע דלא תתורו אחרי לבבכם כו' יעלה ויבא למדרגת קדושה גדולה כזו שבמצותי ממש להיות קדושים בקדושתו ממש ולמה בזכירה ראשונה במצות הויה לא הזכיר תחלה הטהרה רק וראיתם אותו שהוא התכלת בקבלת עמ\"ש לבד בבחי' מצות המלך שהיא מצות הויה כנ\"ל והנה יש להקדים תחלה בטעם סדר הדברים הללו בפ' זאת עד למען תזכרו כו' דמשמעו שכאשר תעשה כסדר הזה דוקא אז תוכל לבא למדרגה דמצותי כו' והיינו כאשר יעשו ציצית על כנפי בגדיהם תחלה ואח\"כ ונתנו על ציצית הכנף פתיל תכלת וראיתם אותו בקבלת מ\"ש כו' וכל זה למען תזכרו כו' דהנה מבואר למעלה באריכות בענין ההפרש בין חוטי לבן לחוטי תכלת שהלבן מבחי' מקיף דאו\"י כמ\"ש עוטה אור כו' והתכלת מבחי' או\"ח כו' ותחלה אמר ועשו להם ציצית על כנפי כו' שזהו חוטי לבן דוקא (כמ\"ש ברמב\"ם דלעיל שהוא ענף היוצא מן הבגד והוא הכנף מן כנף לפי שהטלית עצמו מצמר לבן כמ\"ש לבושי' כתלג כו') וזהו מצוה א' ואח\"כ א' ונתנו על ציצית הכנף פתיל תכלת שהוא חוטי תכלת מצוה ב' ואח\"כ א' והיו לכם לציצית (שמצוה א' הן כמ\"ש בספרי וכמ\"ש ברמב\"ם) ומ\"ש וראיתם אותו הוא התכלת שמזה דוקא וזכרת' מצות הויה ורמ\"ח מ\"ע שרשם מבחי' ה\"ח דאו\"י הרי הקדים תכלת שבבחי' או\"ח ללבן כו' ואח\"כ ולא תתורו כו' שזה ע\"י התכלת דאכיל ושצי לבער הרע עצמו לטוב כנ\"ל ואח\"כ למען תזכרו ועשיתם כו' מצותי ממש כו' דטהרה זו מביא' לידי קדושת העצמות שבמצותי דוקא כנ\"ל והענין כידוע שיש ע\"ס באו\"י וע\"ס באו\"ח ובע\"ס דאו\"י הכתר קודם והמל' אחרון ובע\"ס דאו\"ח נהפוך הוא שהמל' קודם והכתר לבסוף כו' וזהו ג\"כ ענין הפלוגתא דח\"א שמים קדמו לארץ כמו בבחי' ע\"ס דאו\"י שכו\"ח ומדות נק' משפיעים וארץ בחי' מל' היא המקבל וח\"א ארץ קדמה לשמים כמו בבחי' ע\"ס דאו\"ח דמל' קודם ונק' המל' כתר וכתר נק' מל' וזהו שארץ קדמה כו' וכמ\"ש ביום ההוא יצאו מים חיים מירושלים חצים אל הים הקדמוני כו' ומ\"ד ארץ ושמים כא' נבראו הוא למעלה מע\"ס דאו\"י ואו\"ח ששם אין בחי' מעלה ומטה כלל ולא בחי' משפיע ומקבל כלל כו' ע\"כ שמים וארץ כא' נבראו משם וכמ\"ש קורא אני עליהם יעמדו יחדיו והוא מ\"ת רבב\"ח לדידי חזי לי היכא דנשקי כיפא דארעא ורקיע אהדדי' (וכך הוא גם למטה בבחי' יסוד שמחבר ומקשר השפע למקבל דהיינו מ\"ש כי כל בשמים וארץ דאחיד בשמי' וארע' וזהו ר\"ת אהו\"ה את השמי' ואת הארץ גי' טוב וזהו שאמר שראה היכא דנשקי כו' וד\"ל) ועפי\"ז יובן גם כאן בפ' ציצית סדר הדברים בתחלה א' ועשו להם ציצית מחוטי לבן דוקא על כנפי הטלית שהוא ממקיף דאו\"י שמקיף לאבי\"ע שמאיר שם מאור העצמות ממש כנ\"ל בפי' עוטה אור כשלמה והולך ונתצמצם בחטי לבן אלה עד להאיר את החשך גם למטה מטה בהיכלות דנ\"ק כנ\"ל בענין ודוגמא דמיתוק המים בעה\"ח כו' בימין מקרבת דימינו"],[1700400385,"תחבקני וגם כמו ימינך ה' תרעץ לדחות החיצונים ולשברם ולהמתיקם כו' והיינו כמו בחי' ע\"ס דאו\"י שמאיר האור מן העצמות בהעלם המקיף דכתר ובוקע ויוצא ע\"י הלבן עד למטה מטה כו' ואח\"כ א' ונתנו על ציצית הכנף פתיל תכלת שהוא בחי' המל' לקבל עליו עול מ\"ש ביראה ופחד אלקים לקיים מצות המלך ומשום דסוף מעשה עבמ\"ת ה\"ז קודם לאור הכתר דאו\"י כו' וכמ\"ד ארץ קדמה לשמים כנ\"ל ע\"כ ראיה דתכלת גורם ירידות והמשכות החסדים דרמ\"ח מ\"ע דוקא וכמ\"ש וראית' אותו אז וזכרת' את כל מצות ה' פי' כמאמר ריב\"ק במשנה למה קדמה פ' שמע לוהי' א\"ש כדי שיקבל עליו עמ\"ש תחלה שזהו ע\"י וראיתם אותו דתכלת שהוא שום תשים עליך מלך כנ\"ל ואח\"כ יקבל עליו עול מצות שזהו מ\"ש וזכרתם כו' וד\"ל אך הנה בחי' המשכת אלקות שבעצמות הויה הוא רק אפס קצה הארה בעלמא מקדושת העצמות שמתצמצם בשם הויה בע\"ס דאו\"י באו\"כ כנ\"ל ולא יוכל לבא ולהגיע מזה לבחי' הקדושה העצמית שאין לו שעור למעלה כנ\"ל אלא רק ע\"י טהר' דוקא שמביאה לידי קדושה זו שבעצמותו דוקא והוא מ\"ש ולא תתורו כו' ועי\"ז דוקא למען תזכרו ועשיתם כו' מצותי ממש והייתם קדושי' בקדושתו העצמית כנ\"ל והענין הוא כמבואר למעלה בשרש ענין הטהרה שע\"י התשובה מעומקא דלבא עד כלות הנפש שמבער הרע עצמו ונהפך לטוב והטמא עצמו לטהור שזהו כמו שהמות עצמו נעשה חיים שהוא יותר נעלה מגוף אור החיים וזהו שרש ענין תחיית המתים שיומשך טלא דנטיף מפנימית להחיותם שמזה דוקא יהיה אח\"כ העוה\"ב שנק' קדושת העצמות (וכמו יו\"כ שהוא מעין העוה\"ב עולם החירות נק' קדוש הויה מכובד שאין בו אכילה כו' וכך על בע\"ת כתיב ואביוני אדם בקדוש ישראל כו') וכמו הקטורת שארור נעשה ברוך ע\"כ מעצרת המגפה כו' וזה עיקר יתרון מעלת או\"ח שעולה למעלה מאו\"י היינו שמגיע עד בחי' עצמות א\"ס ממש להמשיך מבחי' אור העצמות שהוא ענין המשכת הקדושה שמצד עצמותו שיביא למטה כמו שהוא למעלה מעלה במוה\"ע שאין לו שיעור כו' ששם אין בחי' מעלה ומטה משפיע ומקבל כלל כידוע שזהו טעם מ\"ד שמים וארץ כ' א' נבראו כנ\"ל והוא העוה\"בשאחר תחה\"מ דוקא וכמ\"ש ואין דומה לך מושיענו לתחה\"מ כו' וזהו למען תזכרו אחר שיהיה כסדר הזה דוקא תחל' יומשך מאו' מקיף העצמו' ע\"י הלבן באו\"י ואח\"כ יעל' בבחי' או\"ח ע\"י התכל' ומז' יומשך אורו' בכלי' ברמ\"ח מ\"ע רמ\"ח אברי' שנק' מצו' הויה ואח\"כ התשובה להפוך גם עצם הרע לטוב תעלה על שני המדרגות דאו\"י ואו\"ח וימשיך מקדושת העצמות ממש שאין תו\"מ מגיעי' לשם כלל והוא מ\"ש למען תזכרו מעצמיכם ולא ע\"י עול מצות כזכירה הראשונה והייתם קדושים לאלקיכם בקדושתו העצמית ממש כמ\"ש כי קדוש אני קדושתי למעלה מקדושתכם שע\"י תו\"מ כנ\"ל ואך עדיין אינו מתורץ ענין הנ\"ל במה שאנו אומרים וטהר ליבנו לעבדך באמת דמשמע דגם כדי שיומשך קדושה בעבוד' המצות במצות הויה צריך ג\"כ טהרת הלב מקודם וגם ודאי טהרה למטה מן הקדושה כי טהרה אינו רק שיצא מטומאה וקדושה הוא בעצם הווייתו כידוע שזהו ההפרש בין כהנים ללוים שבלוים נאמר העבירו תער על כל בשרם שבשער שלהם יש יניקה לחצונים לפי שהן מקו השמאל דבחי' או\"ח וע\"כ אמר הזה עליהם מי חטאת לטהרם והכהנים שרשם בבחי' קו הימין דאו\"י ע\"כ אמ' ופאת זקנם לא יגלחו כו' ששערות שלהם כל קדושה נמשך על ידם וכמ\"ש כשמן הטוב על הראש יורד על הזקן זקן אהרן כו' כמשי\"ת אך הנה ארז\"ל הבא לטהר מסייעין אותו ומבואר במ\"א שטהרה זו הוא טהרת השם שגורם וממשיך קידוש השם במצות וענין טהרת השם היינו לתקן ולטהר את אשר הוטמאה ונפגם נפשו בצלם האלקים באותיות שם הוי\"ה שבנפשו ביו\"ד וה\"א כו' והיינו ע\"י תשובה תתאה במרירות והכנעת לבו בתענית למעט חלבו ודמו שבזה יתוקן פגמיו מח\"נ והרהורים רעים וכו' וזהו"],[1700400386,"הבא לטהר לבו מטומאת עונותיו הרבה מסייעין אותו מלמעלה וכמ\"ש היה לי בעוזרי לשון רבים והוא רוח קדושה שנמשך לעזור לבא לטהר והוא אורות הקדושה שבעבודת המצות וזהו ג\"כ ענין וטהר לבינו לעבדך שטהרה זו דתש\"ת הכנה רבה לעבודה בלב שלם באוי\"ר במצות בפ\"מ וכמו ויחד לבבינו לאוי\"ר יחוד והכנה זו היינו רק והרת הלב ע\"י תש\"ת הנ\"ל אבל בחי' תש\"ע שהוא להפוך הרע בעצם לטוב הנ\"ל שרשו מגיע למעלה מקדושה זו שבמצות בפ\"מ וראיה מבע\"ת אמיתית שגדולים מצ\"ג ומשיח אתא לאתבא צ\"ג כו' ומתש\"ע זו נמשך תחה\"מ והעוה\"ב לפי שבחי' החשך הנעלם הנעלם דישת חשך סתרו יאיר אור העצמות ממש מה שאין באור מקיף דעוט' אור כשלמה הנ\"ל כי זהו מגיע בעצמות אור א\"ס ממש כמו שהוא טרם שמעט' את האור בלבוש וזהו שחשמ\"ל דכתנ' אור שע\"י ברור הרע לגמרי גדול הרבה מלבוש של אור דשלמה שבאור העצמות דתו' בפנימית שלה הנ\"ל וע\"כ הוא הגורם גלוי אור עצמותו ממש הנק' קדושה העצמות שז\"ש למען תזכרו כנ\"ל וד\"ל ונמצא מובן מכל זה שכמו שיש ב' מיני קדושה כנ\"ל כך יש ב' מיני טהרה א' טהרה שמביאה לידי קדושה שבמצות הויה וטהרה הב' שמביאה לקדושה העצמית והיינו תש\"ת ועש\"ת כנ\"ל אך טהרה זו דתש\"ת שקודמת לקדושה שבמצות הוי' לא נז' בפ' זו רק ע\"י וראיתם אותו דתכלת שהוא קבלת עמ\"ש ביראה ופחד אלקי לבד כנ\"ל. והענין הוא כמ\"ש עבדו את ה' ביראה וגילו ברעד' וארז\"ל במקום גילה שם תהא רעדה ויש להבין דלכאורה יש סתירה לזה שא' עבדו ביראה ממש עבדו את ה' בשמחה בואו לפניו ברננה וכך הוא בפסד\"ז ברינה ושמחה שהוא הכנה לק\"ש כידוע וגם בפי' אמר תחת אשר לא עבדת בשמחה וטוב לבב כו' והיראה היפך השמחה כי השמחה באה מן הקירוב והדביקות בהשגות אור פני מלך כו' שכל מה שיתקרב ויתפעל בהשגות אלקות יותר יותר תגדל השמחה האלקית כו' והיראה היא לעמוד מרחוק בשפלות בבחינות שוב שאחרי הרצוא כידוע אך הנה באמת מ\"ש עבדו את ה' ביראה קאי על מצות ציצית ותפילין שקודם לפסד\"ז כי מצות הטלית הוא רק קבלת עמ\"ש ביראה ופחד כמו שום תשים עליך מלך שאימתו עליך כו' ואין שם שמחה כלל ומ\"ש עבדו את ה' בשמחה הוא בפסד\"ז וק\"ש וכה\"ג וכך הוא סדר המדרגות האלה בפ' ציצית עצמה דמ\"ש וראיתם אותו ביראה ופחד אחר קבלת עמ\"ש בפרישת ועטיפת הטלית והוא עול מצות שאחר עמ\"ש כנ\"ל ומ\"ש ולא תתורו כו' שהוא ביעור הרע מכל וכל הנה כתיב באבוד רשעים רנה והרי צריך להיות רנה ושמחה כמו שיוצא אדם מאפילה לאור גדול וכנצול ממות לחיים ממש ומשמחה זו בתשובה האמיתית שמן המות ורע נהפך לחיים וטוב כנ\"ל הוא שגורם בחי' שמחה עליונה שהוא וטוב לבב שבמצות כמו שהן למעלה שנקרא מצותי ממש כמ\"ש וישמחו בך ישראל מקדשי שמך ממש כאשר מגיעים לקדושת העצמות שבמצותיו ממש הרי שמחתם בך ממש בשמחה עליונה שבמוה\"ע ומה שא' עבדו את הוי\"ה בשמחה ש\"מ היינו במצות ה' שעושין למטה שגורמי' ג\"כ שמחה עליונ' וזהו כמ\"ש עבדו את ה' ביראה שעבודה זו במצות בקבלת עמ\"ש שלימ' תחל' שנק' עול מצות כמ\"ש הקים על כו' שנעוץ סופן בתחלתן להגיע לשמחה שבמוה\"ע וכן ע\"י התשובה אמיתית הנ\"ל וז\"ש וגילו ברעדה במקום גילה ושמחה של מצוה זו תהא רעדה וכן מ\"ש ואביוני אדם שהן בע\"ת בקדוש ישראל שבמוה\"ע יגילו אבל במקו' גילה זו דוקא תהא רעד' יראה פנימית דמ\"ש שלימה משום דנעוץ תחילתן בסופן וסופן בתחלתן וד\"ל:\n(כא) <b>ולהבין</b> בתוס' ביאר כל הדברים הנ\"ל הנה יש להקדים בענין שרש הכהני' והלוים שזהו ג\"כ ענין טהרה וקדושה שזהו ענין חוטי לבן ותכלת דציצי' כנ\"ל דהנה אמרו בטעם סמיכת ענין מחלוקת קרח לפ' ציצית שבשלח לך [לפי שכל עיקר קנאת קרח ועדתו"],[1700400387,"הי' על זקן אהרן כנ\"ל וכמ\"ש בזהר) שהביא קרח לעדתו בטליתי' שכולה תכלת ושאלו ממשה טלית שכולה תכלת חייבת בציצית א\"ל חייבת ושחקו אמרו אפשר טלית של מין אחר חוט א' של תכלת פוטרה זו שכולה תכלת לא תפטור א\"ע ע\"כ והנה באמת זה פלאי מה ענין טלית שכולה תכלת לענין עיקר המחלוקת שהוא הקנאה על זקן אהרן כנ\"ל והנה יש להקדים להבין תחלה בתוס' ביאור ענין הנ\"ל בב' מקיפים דחי' יחידה שלמעלה מהגבל' או\"כ כנ\"ל דהנה כתיב השמים ושה\"ש לא יכלכלוך שהן ב' מקיפים הללו ויש להקדים ביאור שני כתובים דקדוש הויה צבאו' מלא כה\"כ שזהו סובב וממל' וכתי' את השמים ואת הארץ אני מלא שזהו מורה בבחי' סובב לפי ששוה ומשוה שמים וארץ כא' ולשון מלא כמו בחי' ממלא כ\"ע אך הנה יובן עד\"מ מבשרי אחזה היות שאנו רואים במהו' הרצון והמח' שבאדם שהיא בשני פנים א' בבחי' או\"כ צורה וחומר כמו מחשב' שבמוח שעיקר משכנ' בכלי גידי המוח ולא בשאר האברים כצורה וחומר שהרי בלבול המחשבה יקרה בקלקול כלי המוח בהכא' וחולי וכה\"ג ולא תתבלבל המחשבה מקלקול והכא' אבר היד והרגל וגם לא מאברי' פנימים רק באותן שתלוין בגידי המוח כי אין הכנת חומר וכלי למחשב' רק המוח שהוא מזג תרכבתו ולא אבר זולתו וכל כלי מעין ודוגמ' האו' כידוע שהכלי מהתעבו' האו' וככלי העין לאור הראי' וכה\"ג בכל האברי' במזג טבעי חומר אברי' חיצוני' ופנימי' ע\"כ מזג הרכב' הרגל והיד לא תקבל אור המחשבה להתיישב שם רק כלי המוח ולכך אם יכוהו ברגל וביד לא תתקלקל המחשבה כי אין לה שייכות כלל עם הרגל והיד ולא עם שאר אברים פנימית וחיצונים ואמנם הנה אנו רואים להיפך מזה ממש שמהות המח' הרוחניות ממש כמו שהיא מלובשת ונתפסת ביד ורגל ובכל אברים פנימית כמו הכרס ואצטומכא וכה\"ג שהרי מיד שיעלה במחשבתו ורצונו שבמוח להניע תנועה ביד ורגל תפעול היד והרגל מיד התנועה ופעולה בלי איחור ועיכוב כלל וכלל וכן כח ההרגשה בכאב שבהם שבאה ג\"כ מהתפשטות גידי המוח (שנק' נערוין כידוע בספרי הרפואה) ואם נא' שאין זה התלבשות מהות המחשבה ברגל בתנועתו רק כח הארתה והתפשטותה לבד הי' צריך שיהי' שהות ועיכוב זמן מה עד שיתפשט הארתה וכחה ביד ורגל ואנו רואים שתיכף ומיד במעט רגע בלי שיהוי כלל וכלל מעצמו וממיל' ימיע היד והרגל מיד שעולה ברצון ומחשבה שבמוח פושט ידו ורגלו או כופפם כאילו מהות המחשבה ורצון זה מותפס ושוכן בכלי היד ורגל כצורה בחומר נראי' בעין וכמחשבה שבמוח עצמו וכן באברים פנימים כמו בכלי האצטומכא שהמחשב' שבמוח עוצר הכח הדוחה שבה וכה\"ג יש בכח המחשב' לעשות התפשטות או כיווץ בריאה ולב כמו ביד ורגל כידוע (רק ההרגשה בריאה אין שם מגידי המוח כידוע בס' הרפואה) וכן גידי ההרגשה שאם יארע קלקול בגידי המוח יחסר כח ההרגשה בכאב בכל האברים כידוע בנסיון כו' אך צריך לומר שיש ב' אופנים בזה א' בבחי' גלוי והב' בבחי' ההעלם דהיינו שבגלוי באו\"כ חומר וצורה אין מהמח' ביד ורגל כלל שהרי לא תתבלבל מקלקול היד ורגל כנ\"ל אך בבחי' ההעלם הוא שיש למהות ומציאת כח המחשבה בתנועת הרגל והיד לפושטם או לכופפם כרצונו בלי שיהוי כלל ולא שצריכה להתמשך ממוח אל הרגל והיד אלא ישנה שם במציאותו ומהות' ממש ע\"כ א\"צ עיכוב כלל וכלל רק שאינה שם בבחי' אור וחיות בהרכבה צורה בחומר אלא רק בהעלם (בנערוי\"ן הדקין ביותר שהן בלתי מתייחסין לדם הוא הנפש כלל רק רוחניים ודקים מאד כמ\"ש בס' הרפוא' והן המסתעפים מנערוי\"ן שבמוח לאלפים ורבבות כו' ובלעדם יחסר התנועה וההרגש לגמרי שהוא חולי מאניי\"ע כו') אבל יש מהות הרצון והמחשבה גם ברגל כמו במוח ממש בשוה רק שבמוח יש בהרכבה שבמוח לקבל אור המחשבה בגלוי אור וחיות וברגל הוא דוקא בהעלם גדול אבל מלובשת מהותה שם"],[1700400388,"לעשות ברגל כרצונה כנ\"ל וזהו הנק' בחי' מקיף דחי' באדם התחתון כידוע והוא מה שהרצון ומחשבה נתפסת מהותה בהעלם ומקיף בכל פרטי האברים מראש לסוף בהשוואה א' לכולם כי ודאי אין אנו רואים שום הפרש בין בידי הרצון שבמוח לראות בפתיחת עין או לסגרה ובין התפשטות היד או כפיפתו ע\"פ הרצון שבמוח וכן בין הכיווץ והתפשטות שבלב ע\"פ הרצון ובין כווץ והתפשטות האצטומכא הגשמי עד כווץ והתפשטות במדות חו\"ג שבלב עד מדות שבשכל ורצון ותענוג עצמו שאם לא יאיר אור גידי הרצון שבמחשבה להרהר בדבר התענוג ורצון לא יקבל ולא ירצה להתענג ואם יאיר אורו כן יגבר אור התפעלות התענוג והרצון לדבר האהוב וכן להיפוכו לדבר השנאוי או להפחד מן דבר המזיק כלסטים ונחש תלוי בהרהור שבגידי המחשבה ורצון שבמוח כמו ששולט בכווץ והתפשטות שבתנועת היד ורגל ממש וד\"ל והדוגמא מכל זה יובן למעלה במ\"ש את השמים כו' דזהו ההפרש בין בחי' ממלא כ\"ע לסובב כ\"ע בכלל שממלא כ\"ע בא האור וחיות האלקי בגלוי או\"כ מראש לסוף בחלוקי מדרגות בכל עולם לפ\"ע מג\"ע דבריאה שהוא מקור חיי הנשמות ששם מאיר בחי' בינה שבמל' דאצי' עד סוף עולם העשי' בע' שרים שנק' הדום רגלי השכינה כמשל חיות שברגל וכידוע בענין ע' שרים דעשי' שהן נשמעין לרצון העליון כגרזן ביד החוצב וכמו אשור שבט אפי הרי זהו בא מרצון העליון שבמחשב' עלאה שהוא חו\"ב דמל' שמאיר בג\"ע כו' כמו באדם התחתון רצונו שבשכלו ומדותיו עם רצונו המאי' בתנוע' האברי' עד רצוון תנוע' הרגל הכל א' ומ\"מ יש תפיס' הרצון בכל א' בפ\"ע כדוגמת הגלוי אור וחיות שבבחי' או\"כ כי הרצון ומחשבה לפתוח העין או לסוגרו הוא בא בפרט בפ\"ע וכן בתנועת הילוך בפ\"ע וזהו הנק' מקיף דחי' שמאיר בדרך פרט בכל אבר בפ\"ע ומ\"מ הרי הוא בא בהשוואה א' בכולם כי אין הפרש במהות הרצון ומחשבה שבמדות שבשכל להטו' לזכות וכה\"ג היותר רוחני לרצון שמניע תנועת הילוך הרגל וכה\"ג וד\"ל ונמצא מובן מזה הנמשל למעלה במקיף העליון ששוה ומשוה הארת אור שפעו בעולם העליון עד היותר תחתון כמו מג\"ע דבריאה עד דצח\"ם דעשי' אבל מ\"מ מלובש בכל פרט בפ\"ע עד שאמ' וכמצבי' עביד בחיל שמיא כן בחלקי דצח\"ם שזהו כמו תנועת הרגל ויותר מזה היינו כגרזן ביד החוצב וכה\"ג כנ\"ל וזהו את השמים ואת הארץ אני מלא בהשוואה א' ממש כמו שמשגיח בשמים כרצונו בבחי' התלבשות בהעלם כך משגיח בארץ סוף הכל בלי הפרש כלל וזהו אני מלא שנק' ג\"כ בשם ממלא ואעפ\"י שהארה זו היא באה בהתלבשו' בהעלם כמשל התלבשות המחשבה ברגל להניע כנ\"ל מ\"מ מאחר שבא בדרך פרט כמו בחי' ממלא בתוך כל גלוי אור וחיות של כל עולם כו' והיינו שא' דלית אחר פנוי מיני' מיני' מעצמות אור המקיף שנק' סובב וע\"כ נק' אור מקיף המאיר בבחי' אור ושפע עכ\"פ רק שבאה דרך העלם והתלבשות מפני שמאיר בכולם בהשוואה א' כו' וע\"כ נק' בשם סובב להיותו מקיף וסובב כל בחי' הגלוי דאו\"פ מראש לסוף וד\"ל וזהו שארז\"ל הוא מקומו ש\"ע דעולם היינו גלוי אור אלקי בכל עולם בבחי' א\"וכ כנ\"ל ומקומו ש\"ע הוא בחי' סובב שבו והוא מה שסובל את כל כו' והוא בתוך כל כו' ומ\"מ אין העולם מקומו שהוא בבחי' מקיף נבדל וזהו ברוך המקום כו' וע\"כ אנו אומרים הקדוש בשמים וארץ ונק' קדוש וברוך כידוע וכן בשמים ממעל ועל הארץ כו' ומתחת זרועות כו' וד\"ל אך הנה מדרגה הב' הוא הנק' מקיף דיחידה ולמעלה נק' שמי השמים והוא בחי' טהירו עלאה שלמעלה מהיות בחי' מקיף כללי לאבי\"ע בשוה וזהו כמו בחי' יחידה שבאדם שא\"א לומר בה גם בחי' התלבשות בהעל' כרצון ומחשבה הנ\"ל אלא היא בבחי' מקיף דמקיף שאינו מאיר בכלי הגוף כלל ושורה במקומו של אדם בד\"א שלו ע\"ג ראשו מלמעלה כמ\"ש אך בצלם יתהלך איש והוא בחי' מ' דצלם"],[1700400389,"כידוע ולמעלה היינו אור עצמות א\"ס שמרומם לבדו ומתנשא מימות עולם גם מהיו' מקור כללי וכמ\"ש כי עמך מקור חיים כו' והיינו מבחי' קדוש' העצמו' שבאא\"ס למעלה מעלה עד אין שעור וכו' שזהו בחי' ההתנשאו' שמצד העצמות שנבדל הרבה בערך מהתנשאות שנק' מקיף כללי כו' וזהו המגביהי לשבת המשפילי לראות בשמים ובארץ שהן ב' מדרגות שבאא\"ס למעלה עד אין שיעור למטה עד אין תכלית ואמנם שניהם ענין א' הוא שהרי גם מה שאא\"ס נמשך למטה מטה כו' יש בזה בי' עליות רבות עד אין שיעור למעלה מעלה כו' וכידוע בענין נ\"א יובלות דהנה כתיב ויטע ה' אלקים גן בעדן ולשון ויטע היינו כמו פועל הנטיעה בפ\"מ כאדם הנוטע אילן שהוא בחי' עשי' לבד וכן מ\"ש מה רב טובך אשר צפנת ליראיך שהוא זיו השכינה שבג\"ע שנטע מקדם קדמונו ש\"ע כו' וזהו פעלת לחוסים בך פעלת בחי' פעולה ועשי' גשמי' נחשבת לגבי עצמות המאציל ויש בזה בחי' כח עצמות אא\"ס הבא בבחי' גלוי זיו העדן לכל הדורות בכלים מכלים שונים לאין שיעור למטה להיותו בבחי' א\"ס להתפשטות לכך בעליות הנשמות בג\"ע הרי הולך ועולה בעילוי אחר עילוי מעשי' ליצירה ומיצירה לבריאה ומבריאה לאצילות עד אין שיעור למעלה בעצמות ממש הרי גם לבחי' גלוי האור דא\"ס אין לו שיעור לעליות כמו שאין שיעור למעלה בבחי' מקיף וסובב העצמי הנ\"ל מפני שהארת הסובב הוא בממלא כמ\"ש כי ה' הוא האלקי' כולא חד וכמ\"כ ו' אלפי שנין דעכשיו באלף הז' שנק' שבת יעלה עשי' דעכשיו בבחי' יצירה ויצירה בבריאה וכך יהיה עד נ\"א יובלות וזהו ואין דומה לך מושיענו לתחה\"מ כו' ועכ\"ז ב' המדרגות דירידו' ועליות הללו יגיעו לעצמות א\"ס ממש רק ע\"י תו\"מ כמו שהן בעצמותו ממש שז\"ש קדושתי בתו\"מ שלו דוקא למעלה מקדושתכם וכמ\"ש ושה\"ש לא יכלכלוהו אבל בתו\"מ שורה למטה כמו למעלה במוה\"ע ממש מטעם שזהו פנימית עצמותו ממש וזהו המגביהי ביו\"ד ח\"ע תו\"מ שלמעל' במוה\"ע ומשפילי ביו\"ד ח\"ת בתו\"מ שלמטה הכל א' ועי\"ז משפיל להשגיח בשמים וארץ כו' וזהו קדוש ה' צבאות מלא כה\"כ וזה נרא' כסותר זא\"ז דאם קדוש ה' ומובדל איך מלא כה\"כ אך הנה אמרו אין כבוד אלא תורה והכונה כך הוא דבחי' קדושת עצמות הויה הוא מלא כל הארץ היינו בתורה שנק' כבודו העצמי דוק' וידוע שכבוד גימ' ל\"ב והן ל\"ב נ\"ח ח\"ע שבתורה העצמית דאורייתא מח\"ע שבעצמות ממש נפקא וכמ\"ש בה ואהי' אצלו אמון כו' והיינו ענין ל\"ב חוטין דציצית שבוקעי' ויוצאים מעצמות אור מקיף דטלית דהיינו לבושי' כתלג כו' כנ\"ל בפי' עוטה אור כשלמה באורך וביאור ענין נתיבות חכמה זהו כמשל הנתיב ההולך מעיר לשדה ומדבר שהוא דרך דילוג הערך שיצאו אנשי העיר לשוטט בשדה ולבא לעיר אחרת חוץ למקומם שנק' ירידה להם לצאת החוצה וכך ענין השערות שבוקעים ויוצאים ממותרי המוחין שהוא ג\"כ דילוג השפע ביציאה לחוץ ואמנם הנה בזה יש הוראה במה שיוצא לחוץ שזה בא מפנימית ועצמות המקור למוחי' שלא יכילוהו הכלי מוחין כלל ע\"כ בוקעים ויוצאי' כמו חבי' המלא' שמצד המילוי בוקעי' המים בסדקין כו' וכמו חכם מופלא מצד רוב העומק יצא ממנו מותרי שפע הנק' נובלות כך התורה מצד שרשה בעצמות ממש שלא יכילנו כל כלי גם במקור האצילו' יוצא דרך נתיב ושביל לבד או כמו השערה שבוקע ויוצא כנ\"ל והוא באמת בחי' פנימית ועצמות חכמתו ית' שלתבונתו אין מספר כלל וזהו נובלות חש\"מ תורה כידוע וכן ענין הנתיבות דח\"ע וזהו ענין פנימית ועצמות דח\"ע העצמות ממש וזהו אין כבוד אלא תורה שע\"ז א' מלא כה\"כ כנ\"ל וכמו במ\"ת בי' הדברות כשאמר אנכי ולא יהי' לך וכו' שהן נמשכו מעצמות חכמתו ית' הפנימי' שלתבונתו אין כו' וע\"ז נאמ' חכמת אדם תאיר פניו וכן באור פניך נתת לנו כו' והדברי' היו פשוטים"],[1700400390,"בהתלבשות גשמיות ה\"ז הי' בא בבחי' דילוג אור השפע מח\"ע העצמית שאין כל עליות דנ\"א יובלות מגיע כנ\"ל נתגלה בשעה זו שאמר אנכי מי שאנכי כו' ונתלבש בי' דברות הללו רק שנק' נתיבות ח\"ע כנתיב ההולך חוץ וכמו השערה כנ\"ל וד\"ל וזהו מלא כה\"כ בי' הדברות שנק' כבודו העצמי שהוא פנימית ח\"ע שבעצמו' שאין כבוד אלא תורה כנ\"ל רק שהי' זה בדרך דילוג גדול מעצמות פנימית חכמתו לבא בדבור כו' וזהו מי הוא זה מלך הכבוד ה' צבאות הוא מלך הכבוד והיינו כאשר מתלבש בתורה ומצות המלך נק' מלך הכבוד בגלוי דל\"ב נ\"ח הנ\"ל וזהו קדוש ה' ומלא כה\"כ וד\"ל וזהו ג\"כ ענין ל\"ב חוטין דציצית שהן חוטי לבן וחוטי תכלת שכוללין ל\"ב נ\"ח דתורה שכוללת רמ\"ח מ\"ע ושס\"ה ל\"ת והן י' הדברות ה\"ח בה' מ\"ע כו' ואנכי ולא יהיה כו' כוללם יחד ואח\"כ מתחלקי' בדרך פרט כמו ענין מקיף דיחידה שנבדל לגמרי ומקיף דחי' בא דרך פרט כנ\"ל כך ל\"ב נ\"ח בוקע ממקיף דמקיף שהוא הטלית בל\"ב חוטין דציצית ואח\"כ מתחל' במקי' דחי' בדרך פרט כפי' ציו' אדם בנר\"נ היינו רמ\"ח מ\"ע רמ\"ח אברין תפילין בראש וכה\"ג עד צדקה שהוא במעש' שנק' סוף והיינו כמו משל הנ\"ל ברצון ומחשבה שבאדם שבאה בהתלבשות בהעלם בדרך פרט בכל אבר כו' שזהו למעלה בחי' סובב דאת השמים כו' אני מלא וכתיב ואשים דברי בפיך לנטוע שמים שבודאי המקיף דתו\"מ בכל פרט ברמ\"ח מ\"ע כו' הוא מקיף למקיף דסובב כ\"ע הבא בהשתלשלו' כידוע אבל ל\"ב חוטין דטלית נמשכין ממקיף דמקיף דתו\"מ שבציור אדם וד\"ל ובכל זה יובן מה שמתעטפי' בטלית קודם התפלה וא\"א להקדים התפילין קודם הטלית לפי שהטלית והציצית הן היותר כללי שמשם מקור למקור לתו\"מ שבנר\"נ כו' דהקפת הטלית הוא פרישו דמ\"ש דלעילא שהוא בחי' התנשאות בעצמות כמ\"ש ה' מלך גיאות לבש וכענין המאמר הקדב\"ה מתעטף בטלית כו' שלמעלה מבחי' אדם בנר\"נ ומתחלק אח\"כ בפרטות בציור אדם בתו\"מ שנק' תורת האדם וכן בפרטים רבים בהלכות שבתשבע\"פ בבחי' ו\"ק דנוק' שהן שיתא סדרי משנה זרעים מועד כו' וכמ\"כ בסדורא דצלותא מב\"ש עד ש\"ע שזהו התחלקות סדר מדרגות מנמוך לגבוה כמו שידוע שהן ד' מדרגות דאבי\"ע הכל נכלל בהקפת הטלית שכוללם יחד ונמשך ע\"י ל\"ב חוטין שמאירים במל' דאצילות בבחי' מקיף בב' ציציות שלפניו מאיר בבחי' מקיף במוחי' דנוק' שיהי' כח ועוז ליחד יחוד דק\"ש ותפילין וכה\"ג בציצית שלאחריו וד\"ל:\n[כב] <b>והנה</b> מעתה יש להבין שרש ענין מחלוקת קרח על אהרן מה שייך לענין ציצית בטלית שכולה תכל' כנ\"ל דהנה כתיב וע\"י יתיב לבושי' כתלג חיור ושער רישיה כעמר נקא הרי מדמה בחי' שער רישי' דע\"י כעמר נקא והענין הא דכמו שבל\"ב חוטין דמקיף דטלית שהוא לבושי' כו' הוא בחי' המשכות של המקיף דמקיף כנ\"ל כך בחי' שער רישי' הוא בחי' בקיעת אור המקיף דגלגלתא [שלמעלה הרבה ממקיף דמוחי' דחב\"ד כו'] ולכך נק' ג\"כ בשם ציצית כמו ויקחני בציצית ראשו כו' והוא מ\"ש בכה\"ג כשמן הטוב על הראש יורד על הזקן כו' על הראש בבחי' מקיף דמקיף הנ\"ל בטלית רק שע\"י שמן הטוב שע\"ג הראש נמשך ובא להתחלקות פרטיות יותר והוא לבחי' דיקנא דכה\"ר כו' וזהו יורד עד הזקן זקן אהרן שיורד משם עוד עפ\"י מדותיו למטה מטה ביותר וענין שמן הטוב ידוע שהוא בחי' ח\"ס שבעצמות ממש שנמשך בהעלם ומקיף ע\"ג הראש בכללות כמו ענין ל\"ב נ\"ח דחוטין דטלית ומתחלק אח\"כ לפרטיות המשכות שהן י\"ג מדה\"ר שנמשך בדיקנא דכה\"ר כידוע וע\"ז נתקנא קרח ויש להבין תחלה שרש ענין ובחי' אהרן כה\"ר שנקרא שושבינא דמטרוניתא כידוע דהנה ידוע בשרש הכהנים שהן מבחינת קו הימין דחח\"נ כו' ושרש כה\"ג הוא בבחי' רב חסד העליון"],[1700400391,"שבפנימית ע\"י כו' שמשם שרש המשכת אור אה\"ר העליונה שבלי גבול כלל להיותה למעלה מן הטעם והשכל לגמרי כמו שאנו אומרים אהבה רבה אהבתנו וכתיב אהבת עולם אהבתיך כו' וא' בזוהר דאהבה זוטא דאה\"ע אתדחיי' מקמיה אה\"ר כו' וע\"כ יש ביכולת אה\"ר זו לעורר את האהבה בלב כנ\"י למטה אע\"פ שנסוג אחור לבבם כמו בהבלי טרדת הפרנסה וגם בהיותם בתוך טומאתם בעונותיהם יעוררם ברוח התעוררות תשובה פתאום בלתי הכנה כלל מקודם כידוע בענין ב\"ק שמכרזת כו' שובו בנים שובבים ועי\"ז מתעורר בכל א' וא' רוח התעוררות תשובה שלימה שיעזוב רשע דרכו ואיש און מחשבותיו בחרטה ועזיבה גמורה כו' כל זה הכח ועוז נמשך בנש\"י בגופים מבחי' כח גדול של אה\"ר דכה\"ר העליון שביכולתו לעורר את האהבה והתשובה מצד עוצם תוקפה כמו אה\"ר דאב לבנו יש בכח להמשיך לב בנו אליו וכח המושך הזה א\"א לבא מבחי' אה\"ע שנולד מן השכל רק מבחי' אה\"ר דוקא ע\"כ נק' אהרן כה\"ג שושבינא דמט' כידוע בענין בהעלותך את הנרות כו' וד\"ל וזהו שנאמר באהרן בשלום ובמישור הלך אתי ורבים השיב מעון פי' ורבים השיב מעון ע\"י המשכת אה\"ר הנ\"ל שעי\"ז דוקא נתעוררו רבים בתש\"ע ותש\"ת כנ\"ל בשלום ובמישור הוא בחי' קו האמצעי שעולה עד פנימית הכתר שז\"ש הלך אתי ממש כו' ואע\"פ ששרש אהרן מקו הימין א' בשלום ובמישור דקו האמצעי הלך אתי והענין הוא כי בחי' המשכת אה\"ר הנ\"ל סיבתה באה רק מצד הר\"ר לבלתי ידח ממנו נדח ומשם נמשך הב\"ק לעורר נשמות הנדחים ושובבים בדרך לבם לומר שובו בנים כו' ובחי' ר\"ר הוא בפנימית הכתר ששם גלוי עצמות אא\"ס וז\"ש הלך אתי ממש וכמ\"ש ואשא אתכם על כנפי נשרי' שהוא מדת הרחמים שנק' בריח התיכון דקו האמצעי שעולה להבריח לקצה העליון והיינו ואביא אתכם אלי ממש כידוע שז\"ש אל מול פני המנורה כו' ויעש כן אהרן בכל דור אל מול פני כו' העלה נש\"י כו' וכן התעוררות רחמים שבאדם על נשמתו באה מלמעלה ז\"ש בשלום ובמישור הלך להמשיך התעוררות תשובה ולהעלותם וזהו התכללות גבורות בחסדים לאכללא שמאלא בימינא שנק' שלום ומישור כמו מישרים אהבוך וכמ\"ש במ\"א שמדת הרחמים נק' נחלה בלי מצרים שמבריח מם הקצה העליון לקצה התחתון להאיר אור גם בחשך הגס ביותר כי נדחה מפני האור הגדול הזה שהוא מבחי' רב חסד העליון כל הקליפות וחיצונים וכמ\"ש ורבים השיב מעון כו' והיינו ענין נו\"ן פשוטה דאהרן שנמשך עד למט' מטה ביותר גם נשמו' שנפלו בשאול תחתית בטומאת העונות יעוררם לשוב ולעלות למעלה משום דמדת ר\"ר העליונים שבפנימית הכתר שנק' קצה העליון מבריח לקצה התחתון להאיר גם בחשך הגס ביותר דקמיה כחשיכה כאורה כו' וגם חשך כו' מצד תוקף אור המקיף דרב חסד כו' (ובזה יובן מאמר הזהר ע\"פ תמים תהיה ת\"ם י\"ם כו' דכתיב מעוז לתם דרך יהוה וכתיב הולך בתום ילך בטח כמ\"ש במ\"א שתום בחולם ע\"ג האות זהו בחי' פנימית הכתר והוא התמימות שברצון של מעלה מהתחלקות קוין עדיין כי בטעם לרצון (אפי' טעם כמוס שנק' ח\"ס) ודאי יש נטי' לרצון בדבר והיפוכו אבל התמימות הפשוטה שברצון הוא בחי' נקודת הרצון הפשוט כמו שהוא בפנימית ועצמות ממש שאין בו שינוי וחילוף לעולם וזהו למעלה הרבה גם מתמימות שבחו\"ב ומדות כידוע וד\"ל וזהו הולך בתום בחולם בנקודת רצון הפשוט ילך בטח ושאנן מקטרוגי החיצונים כי אין לחצוני' שרש יניקה שם להיותו למעלה מהתחלקו' קוין ימין ושמאל כו' כי למעלה היינו בחי' מקור המקיפים דבחי' רב חסד הנ\"ל שממנו בורחים החצונים כנ\"ל ע\"כ ילך בטח כו' וזהו מכף רגל עד ראש אין בו מתום הזה שאם היה בחי' תמימות הרצון בראש בתשוב' ע\"י המשכת ר\"ר עליו כנ\"ל שזהו ענין ורבים השיב מעון לפי שבשלום ומישור הלך אתי שהוא ג\"כ ענין התמימות שברצון"],[1700400392,"שנק' הוך בתום שזהו פנימי' הכתר וד\"ל וזהו מעוז לתם דרך יהוה לפי שתמימות שבמדות וחו\"ב נק' ח\"ס י\"ס דיס ומי הוא חו\"ב והן מקבלי' מתום שבפנימי' הכתר הנ\"ל והיינו מעוז לת\"ם י\"ס שנק' תמים הוא מבחי' מקיף דתום בחו\"ב הנ\"ל והוא בחי' דרך יהוה שנמשך בשמן הטוב ע\"ג הראש דכה\"ג בי\"ג מדה\"ר כנ\"ל היינו שמדרך יהוה זה נמשך מעוז גם לתמימות שבמדות וחו\"ב שימצא גם בהם שלימות התמימות שברצון הנק' תו\"ם וזה לא ימנע טוב להולכים בתמים דוקא וד\"ל ועוד יתפרש דרך ה' כפשוטו שהן דרך התו\"מ שהוא דוקא בקו האמצעי כידוע וע\"כ נק' מעוז לחם בבחי' תום דוקא וזהו ג\"כ הולך בתום כו' וד\"ל\nומעתה יובן שרש ענין מחלוקת קרח על אהרן כה\"ג להיות שמבואר למעלה בבחי' שער רישי' כו' שזהו כמו ל\"ב חוטין דמקיף למקיף דטלית ממש והוא שרש ומקור כל המשכת הקדושה עליונה והוא שנמשח כה\"ג בשמן משחת קדש על ראשו כמ\"ש כשמן הטוב על הראש כו' שהוא כללות מקור הקדושה שברמ\"ח שהן ה\"ח עליונים ששרשם מבחי' רב חסד דבחי' כה\"ג והיינו בחי' חוטי הלבן שבציצית דוקא ששרשם בשער רישיה כעמר נקא כו' ואור קדוש' זאת דבחי' החסדי' עליונים בכחמה לירד ולימשך מגבוה לנמוך עד למט' מטה להאיר גם החשך לאכללא שמאלא בימינא כנ\"ל בענין בשלום ובמישור הלך אתי ורבים השיב מעון ובזה נתקנא קרח ביותר מפני ששרש קרח הי' קו השמאל בחי' הגבורות ורצה שיהי' בחי' הגבורות נבדל ונפרד מן החסד ולא שיוכלל הגבורה בחסד ולכך נתקנא בזקן אהרן דוקא ששם נמשך מתוקף אור החסד כי רב הוא מאד וכמ\"ש יורד על הזקן כו' ששרשו משער ראשה כעמר נקא וע\"כ שאל ממשה טלית שכולה תכלת אם חייבת בציצית כי רצה שיהי' הכל מבחי' הגבורות דתכלת שנק' כורסייא דדינא שמזה יאיר אור תקיף ונורא מאד מבחי' היראה ופחד אלקות דעמ\"ש דתכלת אשא תכלא דאכיל ושצי כו' כנ\"ל שמפני עוצם היראה ופחד אלקים יברחו החצונים כמ\"ש כהמס דונג מפני אש כו' ולא יצטרכו לחוטי לבן בציצית להאיר את החשך אחר שהטלית כולה תכלת כו' וד\"ל ולהבין זה יש להקדים בתוס' ביאור בענין חוטי התכלת שבציצית שנק' כורסייא דדינא והוא שרש לשס\"ה ל\"ת לבער הרע בשרשו באשא תכלא כו' דהנה באמת הרי אמרו דאין רע יורד מלמעלה דהיינו למעלה מעה\"ד טו\"ר שהוא באצילות שאין שם אפי' שרש ומקור לרע כמ\"ש לא יגורך רע לא יגור במגורו כו' ואשא תכלא שהוא התכלת שהוא המל' שנק' כורסייא דדינא שם אד' לא שייך לומר דאכיל ושצי לרע ולמה צריכים לתכלת לבער הרע אך הנה יש להקדים תחלה דאת זלע\"ז עשה כו' כמו שבחי' שערות דקדושה שזהו בחי' דילוג אור השפע דקדושה האלקית ממקור הקדושה מאד הגבה למעלה שבוקע ויוצא לחוץ להאיר עד למטה מטה ביותר והוא הנק' עומק טוב שאין בערך המקבל לקבל בדרך השתלשלות דאו\"כ כנ\"ל בענין שער ראשה כו' והן חוטי לבן שבציצית שהן שרש הקדושה של רמ\"ח מ\"ע כו' כך את זה לעומת זה ממש יש בסט\"א עומק רע שהן באין ממקור ועומק הנעלם של כל רע הבא בגלוי או\"כ והוא בא ג\"כ שלא בדרך השתלשלות עו\"ע או\"כ כו' הנק' דילוג השפע משערי טומאה כתר דקליפה שהוא נמשך ג\"כ ע\"י בחי' שערות דוקא וכמו ועשו איש שעיר כו' ונק' שעירים כידוע וע\"כ אמר דשער באשה ערוה כו' היפך גמור משער דקדושה שהוא המשכת הקדושה בדרך דלוג גדול ובאת זלע\"ז השערות דילוג השפע מעומק רע (וכמ\"ש ידעת את העם כי ברע הוא) וכמ\"ש במ\"א בענין וגלחה את ראשה ועשתה את צפרניה כו' שזהו בחי' מותרי השפע הנמשך לחצונים מבחי' שערות דנוק' וצפרנים כמ\"ש בזהר בשערהא"],[1700400393,"אחידן כו' והיינו בחינת פסולת גבורות קשות דבוקעים ויוצאים מנקבי העור דרך גומות שבשערות שמשם יונקים החצונים בתוס' אור רב יותר משעור ומדה שלהם עפ\"י קו המדה כו' וע\"כ א' דשער באשה ערוה כו' באשה דוקא שמלאה גבורות ע\"כ משערהא אחידן כו' וזהו מאן דגליש למטרוני' כו' כידוע וזהו ג\"כ הטעם שהוזהרו הלוים שהן מקו השמאל להעביר תער על כל בשרם שלא ירבו יניקו' הדינין הקשים משער שלהם דוקא אבל הכהנים ששרשם מקו הימין דחסדים אדרבה ופאת זקנם לא יגלחו כו' כי בשערות שלהם כל קדושה וחסד נמשך ממקור החסד והקדושה כמ\"ש כשמן הטוב כו' וכנ\"ל שע\"ז נתקנא קרח ביותר כו' וד\"ל ונמצא מובן שמצד ששרש בחי' שערו' דקדושה נמשך ממקום הגבוה מאד נעלה שנק' עומק רום כו' כנ\"ל ע\"כ ממיל' מובן שבאופן ודרך כזה כאש' נמשך ביריד' האור והשפע לחצונים שנק' בחי' שערות ה\"ז ג\"כ בירידה עמוקה ביותר שנק' עומק תחת והוא הנק' בזהר עומקא דתהומא רבא ששם הוא בחי' מקור ועומק כל רע שנק' כתר דקליפ' המנגד לכתר דקדוש' בכלל והוא הנק' אפל כמ\"ש מדבר באפל יהלך אפל היפך אותיות פלא כו' והוא בחי' ההעלם דכו\"ח דקליפה והוא בחי' דכר והנוק' נק' אפילה כמ\"ש דרך רשעים כאפילה כו' מפני שהן מקבלים מעומק רע בחי' ההעלם של הרצון ותענוג שברע שלמעלה מן השכל וטעם שבלתי מורגש כלל עדיין ע\"כ א' לא ידוע במה יכשלו להיותו בבחי' ההעלם למעלה מגלוי שכל כו' (וכמ\"ש בד\"ח) (וכמא' זה עונות שאדם דש בעקביו בלתי מרגיש בעצמו לרע כלל וע\"ז א' עון עקבי יסובני להיותו בא מלמעלה מעומק רע שעליו בבחי' מקיף והוא מ\"ש למה אירא בימי רע שנק' ימי רע כו') ובחי' המשכות אלה שיורדים בירידה עמוקה כז' מעומק רע שהוא ע\"י בחי' שערות דקליפה נק' אורחות עקלקלות שהן לנגד אורחות הויה שבבחי' שערות דקדושה בי\"ג מדה\"ר שיורד משמן הטוב שעל הראש כו' (וכמ\"ש במ\"א ע\"פ ביו' ההוא יגלח אד' בתער השכיר' במלך אשור את הראש כו' וגם את הזקן תספה וארז\"ל אתא קב\"ה וגזיי' לרישי' ודיקני' כו' דכתר דקליפה כמו מלך אשור נק' מלך זקן וכסיל ובגזיזה דשערו' הזקן עד שרשן בשער ראשו ממיא הרי ניטל ממנו כל מקור שרשו בקדושה שבשערהא אחידין כו' דשערות דנוק' סומקי גו סומקי ע\"כ יש שרש לכתר דקליפה ממל' דקדושה דוקא והיינו למטה מקור חכמות חיצוניות שלנגד מקור חכמה דקדושה וכיוסף ומשה שהשפילו זקני וחרטומי פרעה כו' וד\"ל) וז\"ש דרכי שאול ביתה כו' וכן כל באיה לא ישובון שהן האפקורסין שיונקים שם במקור חכמה ובינה דקליפה כו' ושם יורדין הרשעי' להתברר ולהתלבן ולעלות משם כמ\"ש מוריד שאול ויעל שהן נש\"י שצריכין לבא שם מצד מעשיהם אשר לא טובים שדרך רשעים כאפילה ובחשך והוא השאול תחתית שאין באין לשם כ\"א הרשעים שהן עוברי רצונו ית' בשס\"ה ל\"ת רק שהן מצפצפין ועולין כמ\"ש ויעל אבל האפיקורסין אינן עולין משם לעולם וכן לעתיד נאמר ואלה לחרפות ולדראון עולם כו' וד\"ל והנה באמת הגם שהשאול ואבדון ובאר שחת וכה\"ג הן לענוש לרשעים לכלותם ולאבדם מ\"מ הרע של הרשעים קשה הרבה מן השאול עצמ וכי הגם שמה שעשו רע בפ\"מ באיזה ל\"ת הרי הוא מקור השפע לחצונים לא שממנו מקור התהוות מציאת השאול שהרי יש מציאת שפע אלקות גם בשאול מאחר דאת זלע\"ז עשה האלקים כו' רק שהוא שם בתכלית הצמצום וההסתר אבל אינו נפרד לגמרי מאלקות וראיה ממ\"ש יונה מבטן שאול שועתי כו' וכתיב אם אסק שמים שם אתה ואציעה שאול הנך שגם ששאול תכלית החשך לא יחשיך דקמיה כחשיכה כאורה כו' ע\"כ יונה ראה גלוי אור אלקי גם בהיותו בפתחי שאול בעומק תה\"ר כו' לא יש שם פרוד גמור מאלקות וכמ\"ש ומתחת לארץ ממש אין עוד כו' שהן ז' ארצות שמתחת לארץ גם שם אין עוד ממש כמו בשמים ממעל וז\"ש אסק שמים כו' ואציעה שאול הנך ממש דלגבי"],[1700400394,"בחי' סובב כ\"ע גם חשך כו' וכמ\"כ בבחי' ממל' כ\"ע זלע\"ז עש' האלקי' עכ\"פ אבל העובר עבירה מצד עצם העבירה קשה הרב' מהשאול עצמו שיאכלנו ויאבדנו כו' כי העבירה הוא רע גמור ששנאוי ותעוב לגמרי ונפרד בעצם מכל וכל מיחודו ית' ואעפ\"י שהשאול וגיהנם הוא לענוש על העביר' הרי עונש זה תיקונו ומאחר שהוא תיקונו ודאי שגופה של עבירה הרבה קשה ממנו (וראיה לזה ממ\"ש גיהנם כלה והן אינן כלין כו' וכה\"ג והן הרשעים שאין להם תקון גם בשאול וגיהנם כי הגיהנם כלה מצד שרשו בקו המד' שקץ שם לחשך בשרשו למעלה כו') ובזה נוכל להבין ענין יראת עונש שמשפילים מדרגתם בס' היראה ובאמת מדרגה גדולה היא כיראת הרוממות ממש מפני שאין הכונה ביראת עונש ע\"ד הפשוט שיראים מן העונש הגשמי שבשאול וגיהנם מצד עצמם אלא הכונה הוא שהאלקים הוא ירא ולא את העונש משום דעיקר הירא' בזה באה מצד האלקי' דוקא איך שהוא נורא מאד וכמו והאלקי' עשה שייראו מלפניו מעוצם גבורותיו ע\"כ תפול פחדו ואימתו ביותר כו' והענין הוא כי בזה שאנו רואים שמשליכים ומפילין לנשמה שנק' נפש החוטאת בחטא ועון בפ\"מ כ\"כ למטה מטה עד עומק תה\"ר כמ\"ש מוריד שאול בירידה כ\"כ לשאול תחתית כו' מזה אנו רואים גודל הפגם שעשה בעבירה זו ועוצם התעוב ושנאוי כ\"כ ואיך שהוא כ\"כ למנגד בתכלית לרצונו עד שיגדל כח הדין להשליכו למט' כ\"כ וכל שהיריד' יותר לעומק שאול מסתמ' פגם בדבר גדול ויקר ביותר הרי מזה ניכר עוצם גבורותיו דוקא ועד\"מ בן שעבר על רצון אביו באיזה דבר מה אם הדבר ההוא קטן בערך לא יכעוס האב כ\"כ במה שעבר רצונו ולא יענישנו בהכאת שבט כ\"א מעט אבל כשעשה הבן דבר שנגד רצון אביו בפנימיות נפשו כמו כאשר שבר אבן טוב או כלי יקר מאד מסגולת מלכים או טינפם ומיאסם וכה\"ג שאז יגדל כעס האב ביותר ויעלה חרון אפו בעוצם כח הדין להכות לבן ולייסרו ביותר או שיצוה לעבדיו להשליך לבן בבור עמוק וחשוך ולייסרו שם ביותר וכה\"ג וכל ערך הירידה וההכאה לפי ערך הפגם שעשה בפנימית נפש האב במה שהוא לו למנגד לרצונו ביותר כו' וד\"ל וכך יובן בשרש העונש הגדול לעוברי רצונו י\"ת בשס\"ה ל\"ת שכל שהפגם יותר בא כח הדין לענוש לנשמה להורידה בעומק שאול יותר שמסתמא פגם בדבר היקר ביותר כמו הפגם ביו\"ד דשם הויה ע\"י חילול שבת וע\"י בטול ת\"ת וכה\"ג בג\"ע וע\"ז וש\"ד יותר מתגבר כח הכעס להורידו בעומק תה\"ר ושאול יותר מאשר פגם בה\"א אחרונה במניעת צדקה שלא חמל על דל ואביון וכה\"ג בשס\"ה ל\"ת פגם דאוכל חלב ודם קשה יותר מלבישת דשעטנז שזה באו\"פ וזה באו\"מ כו' ושניהם אינו ק' כ\"כ כש\"ד ממש וג\"ע ממש וכמו ההפרש בין חייבי מיתות ב\"ד לחייבי כריתות וחייבי לאוין שכל שהעונש קשה יותר מסתמ' פגם בדבר הגבוה ועליון ביותר כמשל הנ\"ל וד\"ל:\n(כג) <b>ויובן</b> זה בתוס' ביאור עפ\"י מ\"ש במ\"א ע\"פ בארץ לא זרועה כו' ששרש הל\"ת גבוהים ממ\"ע מטעם הנ\"ל והוא מארז\"ל שמי עם י\"ה שס\"ה ל\"ת וזכרי עם ו\"ה רמ\"ח מ\"ע הרי שרש ל\"ת בי\"ה דשם הוי\"ה והטעם הוא כי מזה שאנו רואים בשס\"ה ל\"ת שמאד שנאוי ותעוב בעיני ה' עד שמענישין עליהן ביותר מזה הוראה שהן לתכלית המנגד יותר לפנימית ועצמות שלו ממש שה\"ז למעלה מן פנימי' רצונו ברמ\"ח מ\"ע רק שהוא בא בדרך שלילה והעלם כו' וכמשל שיותר יכירו במוה\"ע המלך במה ששונא בתכלית יותר ממה שיכירוהו בדברים שאוהב ביותר כו' וזהו שפגם הל\"ת יותר קשה לעונש מפגם המ\"ע כו' וד\"ל והנה כתיב מוריד שאול ויעל דמשמ' שירידה זו לצורך עלי' היא דהנה באמת הרי אין רע יורד מלמעלה כלל כנ\"ל והיינו העונש עצמו שהוא הרע כו' וכל עיקר משפט יריד' זו הוא רק חסד וטוב האמיתי דמשפט איהי רחמי כו' שהוא רק בשביל שיתברר ויתלבן ויתקן הפגם שפגם בחטאו ויצא נקי (כידוע שיש ב' מיני"],[1700400395,"גבורות א' גבורות קשות לשיצאה ולכלות לגמרי והוא כמו המות ורע דקליפה שנק' אבדון אבל גבורות ממותקות לתקן הרע הוא השאול וגיהנם כו') שכדאי שיקבל עונש גדול כזה בשאול כדי שתטהר הנפש החוטאת ותהי' כלי מוכן לקבל זיו השכינה בג\"ע מכל התו\"מ שעשה בחייו בעוה\"ז וכ\"ש וק\"ו שיהי' ראוי לקבלת שכר המצות בעוה\"ב שהוא בחי' העדן עלא' דעין לא ראתה כו' וכמו שאמר גבי אחר מוטב לדייני' וליתי לעלמא דאתי וע\"כ נק' חסד גדול ואמיתי כל עונש הקש' הזה וזהו מוריד שאול במשפט דאיהו רחמים וחסדים גדולים שירידה זו רק בשביל העלי' וזהו ויעל לעוה\"ב ובג\" שזהו עיקר המכוין בעונש זה ולא מצד הדין קשה הזה בעצם רק לאותן שיורדין ואינן כלל כו' וד\"ל אך הנה מזה שמורידין לשאול כדי להתקן אנו רואים גדול יקר מעלת העילוי של שכר מצות בג\"ע ועוה\"ב עד שכדאי כל ירידה עצומה וקשה כזו דלפום צערא אגרא כו' ומזה מובן גודל עוצם הפגם שפגם שזהו רק מצד ערך עוצם מעלת היוקר ורוב העילוי במה שפגם כנ\"ל במשל הבן שמאס אבן טוב וכלי יקר כו' או כמשל הנ\"ל בדבר שמאד לנגד פנימיותו כו' וא\"כ אנו רואים מן עונש הירידה הזאת עוצם יקר העילוי שאח\"ז עד שבשביל זה הורד בעונש קשה כזה ונק' חסד גדול ואמיתי מטע' זה כנ\"ל וזהו מוריד שאול בדין ומשפט שהוא באמת חסד אמיתית כדי שיעל לפ\"ע הירידה ממש שמזה שיצוה להורידו בעמקי שאול יותר ניכר מזה גודל עוצם הפגם בדבר היקר ביותר שלזה הורד כ\"כ וא\"כ עלייתו יותר נעלה כל שירידתו יותר למטה וזהו עיקר ענין יראת עונש שהיא יראת הרוממות ממש שהרי עונש זה שמוריד שאול הוא בא מחמת משפט המלך לפי ערך פגם כבוד יקר מעלתו המרומם לעוברי רצונו עד שחסד יקרא כי אין מספיק העונש לפ\"ע הפגם שפגם בעוצם היוקר ורום המעלה כו' א\"כ זהו יראת הרוממות ממש ולא היראה מן העונש עצמו דכלא חשיב לגבי יראה זו במה שפגם ביקר כבודו המרומם שמחמת זה יצוה להורידו בשאול נמצא יראת אלקים מצד רוממות העצמות הוא דוקא ולא יראת עונש מצד עצם העונש כלל וד\"ל. וזהו ענין התכלת שנקרא אשא תכלא שהוא עונש הבא מכח הדין וגבורה עליונה שבמלכות דאצילות במה שיצוה להוריד לנשמה בשאול תחתית כנ\"ל שאין זה בא רק מעוצם יקר רוממות גדולת המלך שפגם ביקרו העליון ביותר וע\"כ מדת הדין שלפי ערך רוממותו נק' אשא תכלא דאכיל כו' כמו מלך מרומם ביותר שכח הדין שלו הנמשך נורא מאד כאש אוכלת כו' לפ\"ע תוקף רוממות גדולתו כו' וכך למעלה כתיב הן שמים לא זכו בעיניו כו' משום שלפי ערך הרוממות לא יצדק לפניו כדבעי וכו' כידוע ואעפ\"י שזה שרש ומקור לכחות הדין שלמטה אבל הוא בא רק מעוצם הרוממות דוקא וזהו הנק' כורסייא דדינא כמו המלך ברוממותו כשיושב על כסאו לשפוט שהוא נורא מאד מאד מטעם הנ\"ל וד\"ל ובזה יתורץ דגם שאין רע יורד כלל מלמעלה מ\"מ נק' אשא תכלא דאכיל כו' להיות שמצד הרוממות וההתנשאות ביותר יומשך כח הדין על המנגד לו ביותר עד שגם וסביביו נשערה כו' כנ\"ל (וז\"ש כי ה' אלקיך אש אוכלה הוא והוא התכלת) רק מ\"מ חסד גדול הוא במה שיצוה לענוש כדי שיתוקן כנ\"ל ע\"כ נק' גבור' שבחסד שמז' ניכר עוצ' היוקר והמעל' ביותר כנ\"ל והיינו ענין חוטי תכל' שבציצי' שעל חוטי לבן שבתחל' נותן חוטי לבן כמ\"ש ועשו לה' ציצי' על כנפי כו' ואח\"כ נותן התכלת כמ\"ש ונתנו על כו' פתיל תכלת והיה לכם לציצית ששניהם מצוה אחת והענין הוא שחוטי לבן הוא בחי' המשכות הקדושה כמו מבחי' שערות דעמר נקא כו' להאיר את החשך ודינין קשין ולהמתיקן והוא להיותה בחי' אורחות הוי' די\"ג ת\"ד שהן מנגדים לאורחות עקלקלות דשערות דקליפה כנ\"ל וכמ\"כ ממש חוטי תכלת הן מנגדים בתכלית לאורחות עקלקלות הנ\"ל רק שהן באים בבחי' הגבורות והוא כח הדין הגדול ונורא הנמשך על המנגד הפוגם ביקר רוממותו שנק' אשא תכלא ונק' כורסייא דדינא כנ\"ל וכידוע שזהו עיקר בחי' הגבורות שלא לסבול"],[1700400396,"ההיפוך המנגד כלל (וע\"ד המבואר במ\"א בענין שמן המור שנק' גבורות דאבא דהיינו מה שיש בכח החכמה להשיג האמת של ההשכלה נק' חסד שבחכמה ומה שיש בכח החכמה שלא יסבול הטעו' ושקר המנגדו נק' גבורות דאבא והכל א' וד\"ל) וזהו וראיתם אותו כו' ולא תתורו כו' ע\"י ראיה דתכלת דוקא שהוא אימת עמ\"ש שלימה לסור עיניו מכל רע מצד עוצם הפחד אלקים וזהו מתוך שמכירים ומבינים מן העונש הגדול שנמשך מכורסייא דדינא והוא אשא תכלא דתכלת גודל עוצם יקר תפארת מלכות כנ\"ל וזהו שע\"י וראיתם אותו דתכלת ממילא ולא תתורו אחרי לבבכם כו' וד\"ל ואחר כל הנ\"ל יובן יותר ענין מחלוקת קרח ועדתו על אהרן דוקא כנ\"ל כי הנה מבואר למעלה בענין חוטי לבן שבציצית שהוא מקור הממשיך מאור החסדים המקיפים העליונים וכך היא ענין המשכות חסדים ר\"ר העליונים שנמשך ע\"י שערות דדיקנא דאהרן כה\"ר שביכולתו לירד ולהאיר עד למטה מטה גם בחשך דקליפה ולכך הוזהרו הכהנים שלא יגלחו פאת זקנם כנ\"ל וע\"ז נתקנא קרח ביותר ורצה לשמש בכה\"ג באופן אחר דהיינו שלפי מדרגתו בשרשו בקו השמאל יהי' יתרון מעלת הגבורות על החסדים דאו\"י להיות מאיר מבחי' מקיפים דאו\"ח דבחי' הגבורות דוקא שזהו שרש הלוים ויהיו הלוים כהנים והוא מפני שטענת קרח הי' על עיקר ענין כה\"ג שהוא תוקף האור החסד שנמשך ומתפשט למטה ומפני תוקף האור החסד שנמשך ומתפשט למטה ומפני תוקף האור כי רב הוא מאד יאיר גם במחשכים להשיב רבים מעון כנ\"ל ולהמתיק כל דין וקטרוג הקשה לטוב וחסד כו' כנ\"ל ולזאת יש ביכולת כח הגבורה ביתר שאת באופן אחר והוא כשיאיר אור כח הדין הנורא ביותר מבחי' מקיפים דקו השמאל שהוא בחי' התכלת שנק' כורסייא דדינא כנ\"ל שמפני עוצם היראה ופחד אלקים כי נורא הוא מאד יברחו החצונים והמס ימסו כדונג כו' וכמו לע\"ל דכתיב ובאו במערו' צורי' כו' מפני פחד ה' ומהדר גאונו כו' וכה\"ג אנו אומרי' ובכן תן פחדך כו' ואימתך כו' ויראוך כו' (והוא יותר עליון מקו הימין שימין העליון תרעץ אויב כו' כמו בהמתקת הדינין בחסדים כי זהו מתוק הדין בשרשו וכנ\"ל בענין הקטורת) ולזה שאל ממשה טלית שכולה תכלת אם חייבת בציצית שלדעתו במקיפים דתכלת א\"צ לחוטי לבן כלל להאיר את החושך כי ידחו ממילא ולילה כיום יאיר מטע' זה וד\"ל (ודן ק\"ו אם בטלי' שאר מיני' וגם בלבד חוט א' תכל' פוטרו כי העיקר הוא מ\"ש ונתנו על ציצית כו' פתיל תכלת וראיתם אותו דוקא כ\"ש טלית שכולה תכלת דא\"צ אפי' לחוטי תכלת כי א\"צ להמשכת חוט כלל מפני שתפטור א\"ע כי היראה ופחד מרחוק דוקא ולא מקרוב כו' וד\"ל) אך קרח שגה ברואה כי גם שבדרך זה הי' יכול להיות כה\"ג כאהרן בשרשו בקו הימין אמנם לא יהיה דבר זה כ\"א לע\"ל דוקא שיבורר עה\"ד טו\"ר לגמרי ולא יהי' שום צד אחיזה לחצונים מקו השמאל כלל וכמ\"ש ואת רוח כו' ובלע המות כו' אז יהיו הלוים כהנים שיהי' יתרון מעלה לבחי' הגבורות על החסדים כמעלת הזהב על הכסף כו' ואמנם עתה נהפוך הוא שהלוים יהיו טפלים לכהנים ונכללים הגבורות בחסדים שזהו לאכללא שמאלא בימינא דוקא שזהו יסוד כל התו\"מ וכמ\"ש בזהר דקרח רצה להחליף תקינא דלעילא כו' וכמ\"ש וילוו עליך וישרתוך והוזהרו הלוין לגלח בתער על כל כו' שלא יקבלו מהם החיצונים כנ\"ל ולזה ירד קרח ועדתו בחיים שאולה לפי שהשאול יש לו אחיזה בהם בחייהם שלא כדרך במות הטבעי כו' (וזהו שאמרו מחלוקת לש\"ש מחלוקת הלל ושמאי שאלו ואלו דא\"ח להיותם כלולים הגבורות בחסדים בקו האמצעי עד ששניהם דא\"ח ממש אעפ\"י שהן ב' הפכים חו\"ג כו' ע\"כ סופה להתקיים כו' אבל מחלוקת קרח ועדתו שלא לש\"ש כו' מפני שנפרד קרח במחלוקתו מן החסדים דימין ולא נכללו בקו האמצעי שזהו הנק' לש\"ש ע\"כ אין סופה להתקיים כי ירדו שאולה כו') והיינו מ\"ש באהרן בשלום ובמישור כו' כנ\"ל וד\"ל:"],[1700400397,"<h2>שער התפילין </h2>\n(כד) <b>והנה</b> אחר שנתבאר בענין הטלית וחוטי הציצית בתכלת ולבן כו' יש להבין שרש ענין התפילין בכלל והן תש\"ר ותש\"י כמה שכתב וקשרתם לאות על ידך כו' והנה מבואר במ\"א ע\"פ שימני כחותם על לבך כחותם על זרועך דכנ\"י אומרת להקב\"ה בבקשתה שימני כחותם על לבך שזהו ענין תש\"ר שלמעלה שהקב\"ה מניח תפילין כידוע ותפילין דמארי עלמא מאי כתיב בהו מי כעמך ישראל גוי אחד כו' והרצועות דתש\"ר של מעלה תלויין ונמשכין על לבו כמ\"ש בזהר דרצועות ש\"ר צריכין להימשך ולהיות תלויין על לבא ולזה א' שימני כחותם על לבך (וכמשי\"ת דכנ\"י הוא בחי' המל' שעומדת בחזה דז\"א ולכך תש\"י כחותם על זרועך שהקשירה כנגד הלב וכידוע ולזאת א\"א שתבקש' להיות עולה בבחי' תש\"ר עצמו רק ברצועות דתליין על לבא דז\"א כו') וכחותם על זרועך בבחי' תש\"י של מעלה שהוא מניח בזרועו השמאלי כמ\"ש וקשרתם לאות כו' וכל זה בקשת כנ\"י להיות חקוקה כחותם על לבו של הקדב\"ה ברצועות דתליין על לבו וכחותם על זרועו שהוא תש\"י שבזרועו כו' (וכללות בחי' החקיקה מבואר במ\"א שהן רושם אות בעצם ולא כאותיות הכתב והיינו כאותיות החותם שהאותיות חקוקים בעצם אם דרך בליטה שנק' אותיות זכרים אם דרך שקיעה שנק' אותיות נקבות שזהו ב' מיני חותמות שיח' חותם בולט וחותם שוקע) (וכמ\"ש במ\"א ע\"פ לסוסתי סוסוון נוקבן כו' וכמו החקיק' בלבו של אדם דבר הנחמד ואהוב לו ביותר שנחקק בבחי' עצמיות שלא ישכח ויעקר לעולם מלבו וכמאמר אע\"ג דאזיל הכא כו' דיוקני אשתאר בך שז\"ש שימני כחותם על לבך כמ\"ש בזוהר וד\"ל) והנה ידוע שיש ב' מיני חותמות א' חותם בולט שהאותיות שבו בולטין וכאשר חותמין בו בשעוה נעשין אותיות הללו משוקעי' והב' חותם שוקע שאותיות שבו משוקעים וכשחותמין בו נעשין אותיות הללו בולטין כידוע הרי בחותם הבולט מבליט' נעשה שקיעה ובחותם שוקע משקיעה נעשה בליטה (ושניהם ענין א' שהוא פעולת החות' לחקוק אותיות שבו בדבר שנבדל הימנו רק זה חותם וחוקק דרך שקיעה שבו וזה חוקק וחותם באותיות בולטין שבו ובעל החותם כשרוצה שיחקקו אותיות שמו בבליטה יחתום בחותם שוקע וכשחפץ באותיות שקועים חותם בחותם בולט וכך גם כאן כשאמר שימני כחותם בב' מיני חותמות הללו אם כמו בחותם שוקע שהאותיות שלו נעשים בולטים או כחותם בולט כו') והנמשל מזה יובן למעלה שזהו ב' מני חותמות שהזכיר כאן שימני כחות' על לבך ברצועו' תש\"ר שעל לבו כנ\"ל זהו בחי' חותם הבולט שהאותיות שלו עושין אותיות שקועים למטה (אך פי' שימני כחותם היינו שנעשה חותם בולט למעלה ואין בליטה זו נעשה למעלה על לבו רק מבחי' שקיעה דלמטה כמשי\"ת וא\"כ חותם שוקע הוא שעושה אותיות בולטים למעלה ושניהם אמת כמשי\"ת) וכחותם על זרועך שהיא ש\"י כנ\"ל הוא בבחי' חותם השוקע למעלה על זרועך נעשה מבליטה דלמטה [וחותם שוקע זה שנעשה מבליטה שלמטה עושה אותיות בולטי' למטה ושניהם אמת כנ\"ל בחותם הבולט ונמצא דב' חותמות הללו ישנם בכל א' בין בחותם הבולט בין בחותם השוקע מאחר שהחותם הבולט למעלה נעשה משקיעה דלמטה וחותם השוקע למעלה נעשה מבליטה דלמטה הרי חותם הבולט למעלה הי' עצמו הי' חותם שוקע למטה ובחותם שוקע למעלה להיפך שהיה הוא עצמו הי' חותם בולט למטה ושניה' יתפרשו בפי' שימני כחותם בולט על לבך משקיע' דלמטה וכחותם שוקע על זרועך מבליטה דלמטה] והנה להבין ביאור כל זה הנה תחלה יש להבין מהו כחותם על זרועך שהוא חותם שוקע שנעשה מבליטה דלמטה והוא בבחי' תש\"י כנ\"ל ויובן זה למעלה מעבודה שבלב בתפלה דהנה להבין ענין הבליטה שלמטה שמזה נעשה חותם שוקע למעל'"],[1700400398,"הוא כמו שמצינו ענין התפעלות אהבה האלקית בתפלה שהיתה בהסתר לבוש שק דנפש הבהמית ויוצאת לידי גלוי מן ההעלם ויציאה זאת הוא בבחי' בליטה כו' דהנה ידוע דנה\"ב שרשה מנגה דעשי' והוא אביו ואמו שממשיכים נפש טבעיות ברצון ושכל ומדות טבעיים המסתירים על אור אלקי שבנפש האלקית וכשמתפעל באהבה האלקית הרי יוצאת מהעלמה ולכך נק' אהבה המוסתרת שהיתה מוסתרת בטבע נה\"ב ועלתה משם בגלוי והוא בבחי' העלאה דוקא ברשפי אש שלהבת יה כמו צמא לך נפשי כו' בארץ ציה דוקא וה\"ז עולה בבחי' בליטה כאותיות החותם הבולטים ועד\"מ הר שעולה בגובה בשטח הארץ וכמ\"ש במ\"א בענין לא כאברהם שקראו הר כו' דאהבה דאברהם הי' עולה בבחי' העלאה מלמטה למעלה כמו נצוץ הנמשך מלמטה למעלה ולכך נמשל להר שהוא צומח ועולה בגובה ובולט ונראה למעלה ע\"פ שטח כל הארץ המישור להיותו בחי' צומח שבדומם כידוע וכך בחי' התפעלות הלב הוא בחי' צומח שהוא רוח הבל הלב שעולה משטח דומם לצאת ולידבק למעלה כמ\"ש כי רוח האדם העול' למעלה כו' וזהו לא כאברהם שקראו הר לפי שמדתו הי' בבחי' אהבה ונק' אברהם אוהבי ומזה הטעם האבו' שהן המרכבה נק' הרי' כמו שמעו הרי' כו' וד\"ל. [ושרש הדברי' בענין סיבת הבליט' מבוא' במ\"א ע\"פ כמראה הקשת כו' כן מראה הנגה כו' דלשון נגה אור הוא בליטת האור כמו שידוע בלה\"ק דבחי' בליטה לחוץ הניכר יותר מתוך היפכו נק' הגיון כהגיון המחשבה שאור השכל נעשה בולט יותר ונראה בהשגה בבחי' בליטה יותר דוקא דרך האותיו' דמחשבה נק' הגיון אור השכל שבמחשב' וכמו והגית בו כו' ובתורתו יהג' כו' וכידוע שזהו הגיון אותיות המחשבה כאשר מקושר השכל ביותר במחשבה ועיון עמוק הרי הוגה ובולט אור השכל כמו כאשר הוגה מן המסלה וכן יגיה חשכי [וכך ל' הגה\"ה על הספר להוציא לאור יותר בולט מה שנעלם לכאורה שאין הגה\"ה השגה לסתו' אלא אדרב' להביאו לאור השכל מוגה ובולט כו'] וכן הגיון הלב כמו יהגה לבי וכן והגיון לבי כו' שהוא מה שיוצא בולט מן הלב כו' ושרש הכל הוא כמו ההוגה את השם כו' וכמ\"ש במ\"א בענין כאשר יאמר הגי כו' והמשל לכל הענין הזה הוא כמראה הקשת ביום כו' שהקשת גוונין שבו אינם עצמיי' כלל רק גווני השמש דוקא שמאירי' לנגד הענן ובלעדי השמש אין גוון כלל בענן והענן אם הוא עב ועכור לא יתראה בו גוון השמש כלל ולהיפך במים צלולי' הגוון נראה כמו שהוא אך בענן צלול יוכר הגוון בגוון בולט יות' מכמו שהוא בשמש עצמו וכמו השכל במשל יוכר ויובן השכל בבליטה יותר מכמו שהוא בעצם לפי שהמשל דבר זר ע\"כ מתוכו יובן יותר בולט כו' וכך יגיה חשכי שהאור מתוך החושך יוכר ויהי' בולט יותר וכך כל הגיון כהגיון השכל בבליט' במחשבה כנ\"ל וכמ\"כ ענין עליי' הנשמה האלקי' מתוך הגשמית הנה\"ב שאם החומר עב הרי יסתיר אורה לגמרי אבל אם בחומר של נה\"ב בשכל ומדו' כו' מזוכך קצת יהי' מזה דוקא בחי' אור הנשמה בבחי' בליטת אור וזהו כמרא' הקש' כו' כן מראה הנגה כו' שנגה אור בולט והו' מראה דמות כו' שלמעלה בא אור זה ג\"כ בבחי' דמות אותיות בולטי' כו' והיינו ג\"כ בחי' צומח דהר שהו' צומח שבדומם באותיות המחשבה שהן דומם ובהגיון אור השכל בהם נק' צומח שבדומם שבולט אור השכל ביותר וכן בהגיון הלב שהוא התפעלות הלב שיצא בולט מבחי' דומם שבו כו' וזהו כחותם הבולט שאותיות שלו בולטים ונכרים יוצאים נבדלים משאר שטח דומם המתכת דחותם וז\"ש בזוהר ע\"פ שימני כחותם אע\"ג דאזיל הכא והכא שהן ת\"ס דנה\"א שמלובש' בנה\"ב כל היום מ\"מ דיוקני בחי' כתר וצלם כו' אשתאר בך להיות שהן בולטי' ויוצאים מבחי' נוגה כידוע בענין בחי' התקשרות עצמיות שדבוק תמיד למעלה וד\"ל):"],[1700400399,"(כה) <b>והנה</b> כמו שבאבות הן המרכבה בבחי' העלאה מלמטה למעלה בגלוי אור בליטה באהבה ותשוקה כמשל ההר וכמו חותם הבולט כנ\"ל כך בכל א' מישראל מה יפה ירושתינו בכא\"וא יש אהבה המסותרת ומושרשת בנפשו כמו טבעיו' ממש רק שצריך להוציא' מן ההעלם דנה\"ב כו' וזהו בק\"ש באמרו שמע ישראל ואהבת כו' דהנה ישראל זה הוא בחי' נצוץ האלקי שירד למטה בחומר גופני מאד ושרש ישראל זה עלה במחשבה למעלה מעלה כידוע וכשא' שמע ישראל פי' שמע ל' אסיפה וקיבוץ כמו וישמע שאול כידוע והוא ענין קיבוץ ואסיפה דנצוצי אור הקדוש' שבנשמה האלקי' שנתקשרה בלבוש שק דחומר הגופני בכמה מיני רצונות זרות במדות רעו' ותאות חומריי' שמגעלי' ומטמאים אור קדושת הנ\"הא ויציא' זו הוא נק 'אסיפה וכמו ויאסף כו' שיגבר רצון האלקי דנשמה לקבץ כל מה שנתפזר ממנה לעלות למעלה בשרשו שעלה במח' וזהו ואהבת דקאי הכל לישראל זה שאהבתו לה' יהי' בכל לבבך בשני יצריך שזהו קיבוץ כל הרצונות שכבר נתפזרו למטה כענין לב אחד לאביו שבשמי' וכמ\"ש מי לי בשמי' כו' כלה שארי כו' (וע\"ז שייך ציווי ואהבת על עליית הרצון שנפל בקליפה דנגה אבל על עצם נקודת הרצון ואהבה שיש בקבע בנה\"א א\"צ שום ציווי ואהבת זה ממיל' וגם ציווי וכמ\"ש במ\"א שזהו גי' דואהבת בפ' אור א\"י וא\"ח) והנ' כל ענין פסד\"ז ושתי' לפני ק\"ש וק\"ש עד אני ה' אלקיכם דסוף ק\"ש הכל הוא בבחי' העלא' מלמטה למעל' בבחי' אותיו' הבולטי' ואח\"כ בש\"ע נעשה בחי' אותיו' שקועים כנ\"ל דמבליטה דלמטה נעשה שקיעה למעלה ותחלה יש להבין בענין ק\"ש באמרו שמע ישראל שהוא בחי' העלא' כנ\"ל אך מ\"ש ה' אלקינו מה שייך ענין העלאה בזה והענין הוא דהעלא' שבב' תיבו' הללו עולה על הכל והוא ענין ישראל עלה במחשבה באמרו הוי' אלקינו דוקא וביאור זה הנה יש להקדים תחלה ענין המבואר במ\"א בפי' ה' אלקינו שהוא יחוד או\"א חו\"ב תרין ריעין שהוא יחוד תדירי דלא מתפרשין לעלמין כו' והענין הוא שזהו בחי' ההשפע' מאין ליש (מאין דחכמ' ליש דבינ') שזהו יחוד תמידי בהכרח לצורך העולמו' כמ\"ש בע\"ח וזהו ענין מחדש בטובו בכל יום תמיד מע\"ב שבכל יום מחדש יחו' דאו\"ב מאין ליש שנק' מע\"ב בכלל כידוע וביאור הדברי' הנה תחל' יש להבין ענין מאין ליש למטה מאצי' לבריא' ומזה יובן למעלה בחו\"ב דאצי' כנ\"ל דהנה ידוע בהשתלשלות הכללי' שא\"א שיתהווה בע\"ג מבלתי בע\"ג שאין ערוך בניהן כלל כ\"א בדרך התהוות יש מאין ולא בדרך התהוות יש מיש נק' עו\"ע כו' וביאור זה ידוע שבחי' יש מיש זהו כמו כח הפועל בנפעל שהפעולה ידמה לפועל בהכרח בכמה דברים א' במה שיתפעל מפעולתו בין קודם שפעל לאח\"כ א\"כ בהכרח שיש ממהות הפועל בנפעל והב' מצערו ויגונו באבדון הפעולה מפני שנמשך ממהותו וגם בפעולות הרוחניו' כפעולת והתפשטו' שכל מכח השכל שידמה לעצם כח השכל כזיו השמש וכך תנועה שביד וכמ\"ש במ\"א באריכו' וכל זה הוא הנק' יש מיש כידוע ואופן זה א\"א לומר בהשתלשלו' בע\"ג מבלתי בע\"ג שהוא כח האלקי שאם הי' נמשך ממהות כח האלקי' בנברא בע\"ג הרי יש לו ערך ושייכו' עמו ויש בזה ודאי שנוי והתפעלו' בכח הפועל האלקי בין קודם שפעל לאח\"כ וכתיב אני ה' לא שניתי וכמ\"ש אתה הוא כו' באין שנוי כלל בין קודם שברא כו' כידוע (ועוד דהיא גופא קשיא דאם הנפעל ידמה לפועל הרי צריך להיו' הנברא בלתי בע\"ג כמו כח הפועל האלקי' ואנו רואי' שהנברא בע\"ג ותכלית) אלא מוכרח לומר שאין זה בא ממהות למהות מיש ליש דרך עו\"ע כשאר ההשתלשלו' אלא בבחי' התהוות יש מאין וביאור יש מאין ידוע שהוא ההיפך מבחי' שפע והמשכ' שמהות המשפיע נשפע אלא שאין כאן ממהות המשפיע כלל רק בחי' זיוו ואורו לבד שנק' אותיות וכה\"ג וביאור הדבר הזה ידוע שזהו כמו אור חיות הנפש שנק' זיו ואור ולא כמו כח הפועל כו' ובזה אין שנוי והתפעלו'"],[1700400400,"כלל כנראה בחיות הנפש בגפה שמה שמתפעל הנפש מפעולות חיות אברי הגוף אין זה נוגע לעצמותה כלל רק גרעון אור או תוס' אור בכלי הגוף לבד [וכמ\"ש במ\"א באריכות בכמה מופתים לזה מכח המוליד כו' ומענין הגלגולי' וכו' וד\"ל] והנמשל מזה יובן למעלה ג\"כ בבחי' מל' דאצי' שמחי' מאין ליש ג' עולמות בי\"ע כידוע שאין זה כדמיון שכל האנושי כמו שידמה האדם בנפשו כח הפועל בנפעל שנק' שפע והמשכה ממהו' למהות כנ\"ל שהרי אין ערוך לנברא עם הבורא כלל כנ\"ל אלא מ\"ש ואתה מחי' כו' בחי' אור וחיות זה הוא בא בבחי' התפשטות אור וזיו שאינו ממהותו כלל כמו בחי' אותיות שהן נבדלין מן העצם וזהו ואתה שאינו ממהותו כלל כמו בחי' אותיות שהן נבדלין מן העצם וזהו ואתה א' ת' כ\"ב אותיות וזהו מלכותך מלכות כל עולמים וידוע שהמל' הוא בחי' אותיות הדבור העליון שבדבר ה' כו' והן י' מאמרות בכלל כמו יהי אור שמא' זה מהווה אור מאין ליש תמיד וכידוע וזהו פי' מאין ליש מאין ומ\"ה שלא מעצם ומהות המשפיע וכמ\"ש במ\"א באריכות ביאור הבדל כללי שבין אור ושפע וד\"ל והנה ידוע דהאותיות הוא בבחי' המל' ולכך גם ג\"ע התחתון והעליון נתהוו רק מבחי' אותיות רק שג\"ע התחתון ממלא דיצי' וג\"ע העליון ממלא דבריאה וכמ\"ש מלכותך מלכות כ\"ע ועד\"ז יובן גם למעלה מעלה באצי' עצמו בבחי' אותיות המחשבה דבינה דאצי' שמקבל מאור חכמה דאצי' שזהו ג\"כ מאין ליש הרי אין זה ממהות אור החכמה רק בחי' הארה וזיו מן העצמות כמו ענין מאין ליש באותיות דמל' דאצי' לבי\"ע והענין הוא דיש בחכמה ב' מדרגות א' מהות החכמה עצמה והב' בחי' גילוי אורה לבד הנק' אין כמו עד\"מ גלוי התחכמות שכל שאין זה רק התפשטות אור מעצם כח השכל וראיה ממה דלא קאים אדעתיה דרבי' כו' וזהו מאין ליש דחו\"ב דאצי' שבהכרח יחודם תמידי לצורך העולמות דהיינו שכדי שיומשך בבחי' אותיות הדבור לעולמות בי\"ע בהכרח שתחלה יהיה מקום לזה בשכל ומחשבה שהן חו\"ב עד\"מ דבור האדם שמקבל מן המחשבה שחושב באותיות והאתיות דמחשבה הוא לפי אופן ההשגה דבינה דוקא כידוע והשג' זו נק' יש לגבי בחי' אין דחכמה שהוא נקודת אור השכל שנמשך לבא בהשגה אבל צריך להיות תמידי כדי שיומשך בדבור והנמשל מזה יובן למעלה בענין חידוש מע\"ב בכל יום דידוע פי' מעשה בראשית שהוא יחוד או\"ב דבראשית הוא בחי' חכמה ואבא אמר לאימא שנק' עשיה כמ\"ש בחכמה עשית בבינה שזהו גלוי השגת השכל כנ\"ל וזהו פי' מעשה בראשית דזוגייהו תדיר ונק' תרין ריעין כו' מאין ליש בלי הפסק לצורך העולמות כנ\"ל וד\"ל אך מ\"ש ישראל עלה במחשבה הנה שרש הנשמות ממו אבא כמ\"ש כי אתה אבינו כטפה במוח האב שזהו בבחי' פנימית ועצמות דמהות כח החכמה דאצי' שממנו מקןר מוצא גלוי התפשטות אור דיחוד חו\"ב מאין ליש בכל יום כנ\"ל וזהו שאומר שמע ישראל דוקא לפי שישראל עלה במחשבה בבחי' יחוד פנימי דאו\"א לצורך תולדות הנשמות וזהו יהוה אלקינו דוקא כמו כי אתה אבינו כו' וזהו תכלית עליות הנשמות לשרשם העצמי שמזה יוכל לבא יחוד חו\"ג בחצוניות לחדש מע\"ב מאין ליש באצי' וכן מאצי' לבי\"ע ע\"י בחי' המל' שהוא בחי' דבור העליון ולכך שמע ישראל דוקא וכשמוסר נפשו באחד בשרשו עי\"ז נעשה יח\"ע דאו\"א תרין יח\"ת דזו\"נ שהוא ה' אחד כידוע וד\"ל ונמצא שבין בישראל דלתתא שבגוף הוא עולה בהעלא' כנ\"ל ובין בישראל דלעילא שעלה במחשבה כו' ועל שניהם אומר ואהבת את ה' כו' דקאי על ישראל שעלה במחשבה שא' שמע ישראל הזכיר ג' מדרגות בכל לבבך בשני יצריך שזהו ישראל שבגוף ובכל נפשך קאי על שרש ישראל שנפשו הוא בבחי' מהו' ועצמות דאור אבא דאצי' כנ\"ל והג' בכל מאדך בלי גבול זהו מס\"נ באח\"פ בעצמו' אא\"ס ממש שלמעלה גם מבחי' מהו' ועצמו' אור אבא כו' ששם לא שייך לומר בחי' מקור לנשמו' ע\"י בחי' יחוד כו' וזהו מאודך לדבק' בעצמו' אא\"ס חיי החיי'"],[1700400401,"של עצמות כמו כי עמך מקור חיי' שלמעלה מבחי' מקור חיים של הנאצלים כו' וכמ\"כ למעלה ממקור חיי הנשמות כו' וע\"כ אהבה זו בלתי מוגבל בכלי כי אין שם כלי להגביל דלית שום מחשבה תפיס' בי' כו' וישראל אין שרשן רק ממחשבה (אך מ\"מ יש לישראל שרש בעצמות ממש אחר שיש להם מס\"נ זה בכח לדבקה שם דהיינו בכל מאדך וזה ידוע דכל דבר הנמשך מצד העצם נמשך לשרשו שמשם נחצב כניצוץ לשלהבת וכה\"ג דרוח אייתי רוח כו' והיינו שיש לכאו\"א גם לקל כו' למס\"נ בפ\"מ וא\"א לומר שאין זה רק מצד שרשם במחשב' שהיא בפנימי' חכמ' שהרי המס\"נ הוא דוקא לעצמו' ממש כמו אליך ה' נפשי כו' וראי' ממה שמצינו גם מלמעל' למטה כן לשכל עצמו' אלקו' נמשך לבא בגלוי בנש\"י להשיבם בתשוב' שלימה כמו משכני אחריך נרוצה כו' וכן השיבנו כו' שזהו כמו כח המושך כו' ואין זה רק מצד שרשם בעצמות ממש כי חלק ה' ממש עמו כמ\"ש במ\"א) ונמצא ב' מדרגות יש כאן בנשמו' א' נשמו' שבגוף וב' נשמ' בשרשה במוח אבא כנ\"ל וכל א' כלול מג' מדרגות נר\"נ שהוא ג' מדרגו' בהתפעלו' הנשמות בבחי' הבטול בג' מדרגות נר\"נ שהוא ג' מדרגו' בהתפעלות הנשמות בבחי' הבטול בג' מדרגות דחב\"ד חג\"ת נה\"י כידוע בחי' נפש הוא הבטול בבחי' המעשה בלבד להיו' סו\"מ וע\"ט בפ\"מ כידוע והוא בחי' נה\"י כו' עקביי' והב' בטול שבמדות אוי\"ר בחי' רוח האדם העולה כו' וג' בטול היש לאין ממש בהתפעלו' המוחים בהשגה והוא בחי' נשמה כמו נשמת שדי תבינם והוא בחי' בינה לבא כו' שהלב מבין ומשיג כו' וזהו בנשמה שבגוף שעל זה א' בכל לבבך כנ\"ל הכל לצאת מנרתק חומר הגופני בג' מדרגות הללו דנפש רוח נשמה שנקרא בי\"ע והוא חב\"ד חג\"ת נה\"י וכמ\"כ בנשמה האלקי' בשרשה באצי' בלתי גוף יש בה ג' מדרגו' דנר\"נ הנ\"ל והכל בבחי' אלקו' והוא בבחי' נר\"נ דאצי' שע\"ז א' בכל נפשך א' התפעלו' בטול היש מהכלי לבד שבנפש דאצי' והב' התפעלות המדו' שנק' רוח בבחי' האצי' והג' בחי' בטול היש שבהשגה דבינה בחי' אין דאצי' להיות בחי' אין ששרשו בחו\"ב דאצי' והוא כמו בינה לבא למטה וכמ\"כ ג' מדרגות הללו בג\"ע עליון ותחתון בנשמו' שנהנין מזיו כו' ויש עוד מדרגה ד' העולה על כולנה והוא למעלה מבחי' בטול עצמי דנשמ' בשרשה בחו\"ב כו' והוא מס\"נ בעצמות ממש כנ\"ל שזהו בכל מאדך וע\"ד כל זה יש במלאכי' בחיצוניות העולמו' וזהו ענין פסד\"ז ושתים לפני ק\"ש שהוא הכנה לק\"ש בפסוק ואהבת בכל לבבך דקאי בנשמות והוא כמ\"ש ואחרי הרוח רעש ואחר הרעש אש והכל לא ברוח ה' ולא ברעש ה' ולא באש ה' עד קול דממה דקה תמן קאתי מלכא ממש וזהו נא' גבי אליהו שהוא בחי' שם ב\"ן וכה\"ג ממש הי' במשה שם מ\"ה כידוע וזהו מ\"ש לא ברוח הוי' כו' קאי על ג' מדרגות הנ\"ל בעשי' ויצי' ובריא' שהן נה\"י וחג\"ת כו' ונר\"נ בנשמו' דרוח הוי' ורעש הוי' ואש הוי' בכל בנשמות ששרשם בנר\"נ דאצי' ולמטה כדוגמתו ממש הוא במלאכי' שנחלקים לג' מדרגות מלאכי' דעשי' ודיצי' ודבריא' בכלל ודרך פרט בכל עולם כלול מג' והן רוח ורעש ואש שהוא אופני' וחיו' הקדש ושרפי' שרפי' בבריאה וחיות ביצי' ואופני' בעשי' כמ\"ש כי רוח החי' באופני' כו' וע\"ד הנ\"ל בחי' בטול במעש' חיצוניו' השתחווא' הוא באופני' וגלגלי' כמו וצבא השמים לך משתחווים וחיות הקודש ביצי' בחי' התפעלות אוי\"ר כו' ושרפים או' קדוש הוא כמו בחי' התפעלו' בינה לבא הנ\"ל והכל לא ברוח ה' כו' עד ולא באש הוי' שהן השרפים כו' אבל הנשמות ג' מדרגות הללו עצמן הכל בשם הוי' דאצי' כו' וקול דממה דקה כו' הוא כמו בחי' מס\"נ דמאדך הנ\"ל שעולה על הכל כנ\"ל וד\"ל:\n(ךו) <b>והנה</b> כל זה הוא רק בחי' בטול היש מלמטה למעלה שההתפעלו' הוא בבחי' בליטה כלפי מעלה בין במלאכים בין בנשמות עד סוף ק\"ש הנה זהו החותם שבבחי' אותיות בולטי' ואתד\"לת זאת עושה אתד\"לע מלמעלה למטה בבחי' אותיות שוקעים והיינו בש\"ע שנק' צלותא בלחש דוקא דהנה עד ש\"ע"],[1700400402,"כל בחי' התפעלו' בנשמות ומלאכים הכל הוא ברעש בחי' בליטה ביותר עד בש\"ע שהוא בלחש והיינו קול דממה דקה דתמן קאתי כו' וביאור הדברים ידוע שבחי' ג' מדרגות הנ\"ל במלאכים ונשמות הכל הוא בבחי' בטול היש לאין ולא בחי' האין בעצם כמו שהוא (וזהו כמשל גווני השמש הנראים בענן שהאור נעשה שם בולט יותר כנ\"ל באריכו' משא\"כ בהיותו זה הגוון עצמי בעצם אור השמש אינו ניכר כלל וכלל כו') שהרי גם הבטול שבא מצד ההשגה שנק' בחי' נשמ' והוא בחי' חב\"ד כמו בחי' בינה לבא הנ\"ל שעליון מכלם ה\"ז ג\"כ בחי' בטול היש דהשגה עכ\"פ ואינו נק' בטול בעצם דהיינו דעצם בחי' האין דפנימי' החכמ' שזהו כתר שבחכמ' כמ\"ש במ\"א בהפרש גדול שבזה כמו היש ה' בקרבנו אם אין בעצם כו' וזהו שאומרי' בשתים לפניה הכל בבטול היש דמלאכי' שאו' קדוש והיינו ברעש גדול וידוע דכל רעש הוא בא מצד הריחוק יותר יתפעל במורגש יותר וזהו הרעש כמו והאופני' ברעש גדול כו' דהשרפי' או' קדוש לא ברעש כ\"כ לפי שהמה קרובי' יותר שהן בבחי' בריא' בחי' חב\"ד דאימ' מקננ' בכורסיי' כו' ונק' שרפי' מצד רשפי אש דבינ' לבא והוא בטול פנימ' דבחי' ההשגה הנ\"ל ע\"כ או' קדוש וי\"ו דקדש דאין דחכמ' מובדל מהשגת' וזהו בחי' בטול ההשגה שלהם ולכך אינו ברעש אבל חיות הקדש ואופני הקדש שמקבלי' רק מבחי' מדות אוי\"ר שנולדים מצמצום השכל וההשגה ולא מן עצם ההשגה התפעלות' בריחוק יותר לכך בולט ויורגש ברעש יותר עד הגלגלים דמשתחווי' ברעש גדול יותר מכולן לפי שרחוקי' יותר מהכל להיותם רק מבחי' נה\"י דעשי' שנק' נה\"י דנה\"י שזהו רק בחי' הודא' חיצוניות כמ\"ש במ\"א וזהו כל ענין סדר שתים לפניה ביוצר אור מדבר בג' מדרגות בטול היש הנ\"ל במלאכי' וחיות ושרפים ובברכה שניה אה\"ע כו' מדבר בנשמות אה\"ע כמו אהבה טבעי' מקטנות המוחי' שנוגע למעשה להיות סור מרע כו' וזהו ודבר לבנו במצותיך לבלתי נטות ימין ושמאל במעשה עכ\"פ ואח\"כ ויחד לבבינו לאוי\"ר בטול השני במדות שמצד ההשגה כו' בחי' יצי' ובחי' רוח כו' ואח\"כ וקרבתנו כו' וליחדך באהבה בבחי' מוחי' דגדלות בשמע ישראל ליחדך בבחי' בינה לבא באמרו שמע ישראל ואהבת כו' ובברכה זו השני' הוא מדבר בבחי' ההמשכה מלמעלה למטה ליתן כח ועוז לנשמה האלקי' כמו אה\"ע אהבתנו כמו משכני כו' אה\"ע אהבתיך ע\"כ משכתיך כו' וכן וייחד לבבינו וקרבתנו כו' שכל זה אינו אלא בנשמות מצד שרשם באלקים חיים שישראל עלה במחשבה באצי' בג' מדרגות דנר\"נ כנ\"ל עד פנימית אבא כנ\"ל משא\"כ המלאכי' שנבראו מן הדבור דמל' בחיצוניות חכמה הרי בחינת בטולם מן עולם הנפרד בא מצד עצמם שמשבחים ומפארי' תמיד ע\"י שם ומל' כי כך אופן בחינ' התהוותם מאלקי' שחוזרי' ונכללים באור האלקי רק בהגלו' נגלות אור האלקי עליהם כפי מדתם לבד שביתר מכפי המדה מתבטלים לגמרי כמו הושיט אצבעו קטנה יתר מכפי מדתם שמקבלי' בשרש התהוותם ושרפן כו' וד\"ל ונמצא עכ\"פ שהכנה זו דשתי' לפני' בנשמו' ומלאכי' רק בשביל ק\"ש שיעלו למעלה דוקא נשמו' במס\"נ באחד ואהבת כו' בכח ובפ\"מ בנשמ' שבגוף ובמלאכי' במ\"ש ונתתי עשב כו' וענין פסד\"ז שלפני שתי' לפניה הוא ג\"כ בשביל נשמו' ומלאכי' כידוע דעיקר ענין פסד\"ז לזמר עריצי' להכרית יניקו' החיצוני' כמו רוממו' אל כו' וחרב פיפיו' כו' והוא ע\"י בהלו נרו עלי ראשי שיאיר אור בתוס' בשם הוי' שבנשמ' בשבחו של מקום וממילא גם במלאכי' שאינם בשם הוי' רק בשם אלקי' נמשך הארת אור בתוס' זה והכל רק לדחות החושך דקליפות שנק' עריצים כו' ולכך נזכר בכל הללויה ענין בטול כל הברואי' וכל המלאכי' אך תחלה מדבר בנשמו' כמו הללי נפשי כו' כי טוב זמרה ואח\"כ הציווי על המלאכי' הללוהו כל מלאכיו ולשמים וארץ שיעלו הכל עד כל הנשמ' תהלל יה שכולל כולם וד\"ל אך הנה בחי' השקיע' שנעשה מלמעלה למטה ע\"י בחי' הבליטה שמלמטה למעלה הוא"],[1700400403,"ענין ש\"ע שנק' צלותא בלחש והוא בחי' בטול פנימי דעצם אין דחכמה שנק' בטול במציאו' כמו השתחווא' דר\"ע כו' וכידוע דבש\"ע הוא השתחווא' שבאצי' (ולמעלה גם כן בבחינות אדם דאצי' כורע בברוך בחי' השתחוות זו היא בחי' השפעה והמשכה למטה והיינו בחי' ח\"י חוליו' דז\"א שהן ח\"י המשכו' במל' שזהו עיקר ח\"י ברכות דש\"ע) ובחי' בטול זה הוא כמו השקיעה שבחותם שהאותיו' שקועי' וכמו חלל בית קיבול להכיל אור השפע וכמו ולבי חלל בקרבי שהלב חלול ושקוע הרבה מצד עוצם הבטול בעצם אין ומ\"ה הפנימי שבלב ומוח ולא שנעשה אין ומ\"ה אלא כמו ונחנו מ\"ה בעצם ובחי' חכמ' תתא' בטול היש דהשגה בינה לבא הנ\"ל אינו אלא בחי' הכנה וכלי לבא לבחי' אין ובטול עצמי הנק' השתחווא' פנימי' דוקא ככריעות והשתחווא' דר\"ע שזהו היפך השתחווא' דמלאכי' וצבא השמים שבולט ביותר משום דכל שהוא רחוק יותר ומורגש בבחי' יש יותר ניכר התפעלות הרעש בהשתחווא' שלו כנ\"ל ולהיפך כל הקרב יותר לא ניכר כלל בטולו וזהו השתחוואה בפנימי' ובזה הוא עיקר ההפרש בין בטול היש שמחמת ההשגה כמו ואהבת דק\"ש עד אני ה' כו' ובין בטול עצמי דש\"ע שזהו מצד עצם אור הנשמו' כמו שהן למעלה בחי' בית קיבול בשקיעה עצמית להכיל אור האלקי תמיד כנשמת משה שהי' בחי' ו\"ה בעצם בתמידו' בהיותו בחי' כלי בית קיבול להכיל תמיד גלוי אא\"ס בנפשו ע\"כ הי' כבד פה וכב' לשון מפני שהדבו' הוא בחי' התפשטו' יש במהו' בפ\"ע כידוע ולעוצם תכלית אמיתי' בטולו העצמי כנ\"ל לא הי' יכול להיות במהו' דבר מה בדבור ולשון וכמו אין מלה בלשוני כו' כמשל העומד לפני המלך בקירוב עצום שמתבטל בעצם לגמרי מכל וכל ולא יוכל להיות בבחי' התפשטות דבר לדבר דבר וחצי דבר גם אם ישאלנו המלך דבר ידום כאבן מגודל בטול המציאו' ואין מלה בלשונו כלל רק ידבר בלחישו וגם זה אינו יודע מה שמדבר בהיותו בלתי רשות שכלו ורצונו כלל איך לדבר רק ע\"פ כח ועוז של המלך שמחזקו לדבר וזהו ענין ש\"ע אד' שפתי תפתח שאת' תפתח שפתי לדבר כי אין מלה בלשוני מצד איזה כונה מעצמו מעוצם הבטול שאין לו כלום מצד עצמו כי אינו רק בית קיבול להכיל מה שישים ה' בפיו אותו ידבר וזהו ופי יגיד ממילא ולא ע\"י הכנת עצמו באיז' כונ' והתפעלו' מעצמו כלל וכלל וכל זה הוא רק מצד בחי' בטול העצמי הנ\"ל שנמצ' רק כמו בית קיבול שקוע כענין ולבי חלל כו' כנ\"ל וגם שקיע' זאת לא נעש' מצד עצמו בבחי' בטול היש אלא כמו שחוקק אדם בשעוה בחותם בולט שנעשה שקיעה ממילא כו' כך ע\"י בחי' הבליטה שמלמטה הוא שנעשה כנ\"י חותם שוקע למעלה וזה ענין כחותם על זרועיך שנעשו כנ\"י בחי' חותם שוקע על זרועך למעלה והוא ענין בטול עצמי ופנימי הנ\"ל שבש\"ע וכן בכל ענין פרטי מעשה המצות דכנ\"י שהן רק לעשות בחי' כלי בית קיבול להכיל האור אלקי דאצי' כמו רמ\"ח מ\"ע שהן רמ\"ח אברי' כו' כידוע שזהו התלבשו' אורו' בכלים ואמנם בחי' הכלים הללו למעלה הרי הן נעשין מם גופם של מעשה המצות שהאדם עושה למטה שנעשה מזה ממש למעלה בחי' כלי להכיל אור האלקי שבאצי' וה\"ז כאותיות שקועי' וחלולין לקבל בתוכן דבר מה ולכך נק' בנ\"י חותם שוקע על זרועך למעלה ושקיעה זאת בכנ\"י נעשה ע\"י בחי' חותם הבולט שהי' תחלה עד סוף ק\"ש באויר בולטים מלמטה למעלה כנ\"ל וד\"ל וביאור פרטי הדברים הנה בח\"י ברכאן דצלותא שבלחש דוקא כמו וקולה לא ישמע מצד בטול העצמי כנ\"י זהו כענין קול דממ' דק' דתמן קאתי מלכא כנ\"ל דהיינו ששם דוקא קאתי ונמשך ח\"י ברכות והמשכות עליונות דז\"א דאצי' בכל שם משמות הויה שבכל ברכה וברכה כידוע דשם ומל' שבכל ברכות דש\"ע הוא שם מיוחד כמו שם הויה בנקוד צירי בהשיבנו ושם הויה בנקוד סגול ברפאינו וכמ\"ש במ\"א על ענין כשכורעין כורעין בשם כו' וכשכורע בברוך וזוקף בשם הוא אשר נעשה בחי' כלי להכיל ולקבל בנשמתו שם הוי\"ה דז\"א כו' כנ\"ל והיינו בחי' חותם שוקע למעלה (שמזה יהיה"],[1700400404,"חותם בולט אח\"כ כמשית') וכך הוא בענין מצות ת\"ת באמרו ואהבת ודברת בם כו' דכמו שח\"י ברכות דש\"ע הן בחי' ח\"י המשכו' אורות בכלים שקועים בבטול עצמי הנ\"ל כך הוא ענין שרש התורה והמצות שנז' בפ' שמע כמו ודברת בם מצות ת\"ת הרי ע\"י בליטת אור האהבה הזאת דבכל נפשך כו' נעשה לאדבקא רוחא ברוחא מחשבה במחשבה ודבור בדבור בדבר ה' זו הלכה שנעשה רק בחי' כלי לקבל גלוי אור המשכת אא\"ס שבדבר ה' זו הלכה שמדבר בפיו וה\"ז כאותיות שקועים שמקבלים בתוכן דבר מה כך אותיות דבר ה' כשתורת ה' בפיו עולין למעלה ונמשך בהן גלוי אור א\"ס שבח\"ע שבתורה ש\"מ שהרי הקדב\"ה יושב ושונה כנגדו כו' וכמ\"ש ודברי אשר שמתי בפיך הרי דבר ה' נמשך ומלובש בדבור האדם כשמדבר דבר ההלכה וכמא' ג' קשרין ישראל מתקשראן באוריי' ואוריי' בקודב\"ה כו' וה\"ז ג\"כ בחי' חותם שוקע הנ\"ל שהאור מלובש בכלי חלל בית קיבול כו' וכך הוא כל המצות מעשיות שנק' רמ\"ח אברין דמלכא כנ\"ל שהוא התלבשו' אורות בכלים ובחי' כלים שלה' היינו דוקא מה שישראל עושין מצות למטה כמארז\"ל ועשיתם אותם אתם כאילו עשאוני ברמ\"ח כו' וביאור הדבר ידוע שישראל הן העושין המצות עליונו' למעלה וכענין לעשות ולקיים את כל דברי התורה כו' שהן מקימין ועושין שרש התו\"מ למעלה ע\"י מעש' המצות בגשמיות שעושין למטה דוקא והענין הוא כידוע דאא\"ס מצד עצמו ממש לאו מכל אינון מדות כלל שאינו בא בגדר ותואר מתוארי האדם גם להיות בבחי' מקור למקור לאדם דאצי' וכמא' אנת הוא חד ולא בחושבן פי' ולא בחושבן י\"ס כלל דלפני אחד מה אתה סופר וכמ\"ש במ\"א וגם מבחי' הרצון הוא מושלל וכמו שאומרים יהי רצון מלפניך כו' וכידוע ולהיות מה שנתצמצם בצמצום הראשון הנק' מק\"פ להיות המשכת הקו וחוט זהו מצד שנתאו' להיות לו בחי' דירה בתחתוני' בתו\"מ שישראל עושין למטה בפ\"מ דוקא וכמ\"ש סוף דבר כו' כי זה כל האדם דלעילא עד ראשית הקו כנ\"ל דסוף מעשה דוק' עלה גם לפני תחלת המח' דמל' דא\"ס כו' וכמא' במי נמלך נשמתן ש\"צ שבגופי' שמקיימי' תו\"מ בפ\"מ דוקא הרי מזה נעשה לעצמות אא\"ס תחלת המחשבה להקרות בשם חכים ומבין בבחי' אצי' שזהו מה שעלה ברצונו להאציל ע\"ס דאצי' להקרות חכים ומבין כו' שנמצא מובן מזה דמה שנאצלו ע\"ס באו\"כ כמו חכמה מוחא חסד דרועא כו' הכל מפני העלא' דנשמות ישראל שנתאו' להיות כו' א\"כ הרי ודאי במעשיהם בפ\"מ בקיום התו\"מ למטה מעוררים תמיד אור חדש בהתעוררות חדשה מעצמות המאציל להאציל ע\"ס בתוס' אורות בכלים מכלים שונים באבי\"ע וזהו שארז\"ל כאילו עשאוני משום שמצד עצמותו לאו מכל אינון מדות כלל רק ע\"י ישראל שעושים בתו\"מ למטה נמשך ונתצמצם להיות מקור למקור לע\"ס דאצי' באו\"כ כמו ע\"י עסק ת\"ת למטה כמו ודברת בם הרי עי\"ז נמשך אא\"ס בחכמה דאצי' בתו\"מ אור בכלי החכמה דאצי' לפי שבאתדל\"ת יעורר אתל\"ע כי רוח אייתי רוח כו' והוא מה שהקדב\"ה יושב ושונה כנגדו כמ\"ש את ה' האמרת כו' שעי\"ז נמשך התלבשות אא\"ס בחכמה שבתורה ועי\"ז נק' חכים בתוס' אור באצי' ועד\"ז כל המצות שנק' רמ\"ח אברין כנ\"ל היינו ע\"י מעשה המצוה בפו\"מ למטה נעשה למעלה בחי' אתדל\"ע בעצמות ממש להמשיך תוס' אורות בכלי למעלה באצי' שנק' אברי' דמלכא והיינו כאילו עשאוני ברמ\"ח כו' והיינו שישראל עושין המצות עליונות למעלה להיות כלי מוכן לבחי' עצמות אור המאציל אך איך ביכולת מעשה גשמית בפ\"מ שישראל עושין למטה לגרום אתדל\"ע שבעצמו' המאציל בהתעוררות חדשה להאיר בתוס' אור באצי' אין זה רק מטעם שישראל עלה במח' והוא בחי' סוף מעשה שעלה במ\"ת ע\"כ יש יכולת וכח למעשה בפ\"מ שלמטה לעורר אור עצמו' המאציל בנאצלי' וזהו מ\"ש לעשות כו' וכן למען להקים את דברי התורה שישראל עושין מחדש לשרש הת\"מ שלמעלה באצי' מטעם שלזה כו' עיקר הרצון בתחלה כנ\"ל וד\"ל וזהו ענין חותם שוקע שכנ\"י נעשה למעלה ע\"י מעשה התו\"מ דוקא בהיות שהן עושין במעשה התו\"מ"],[1700400405,"בחי' כלים מכלים שונים בבחי' שקיעה וחלל בית קיבול לקבל בתוך מעשיהם בחי' המשכת והתלבשות אא\"ס שהוא מתקבל ומתלבש שם בהעלם (ולע\"ל יתגלה מן ההעלם כמו ולא יכנף עוד כו' כידוע) וה\"ז עד\"מ חותם שוקע שאותיות שלו שקועין וחלולי' לקבל בתוכן דבר שהן אורות עצמות המאציל כנ\"ל וחותם הזה השוקע נעשה רק מבחי' חותם הבולט שנעשה בכנ\"י מחמת אוי\"ר בהתפעלות מורגש ובולט בחי' בטול היש מלמטה למעל' עד סוף ק\"ש כענין הנ\"ל במא' לא כאברה' שקראו הר כו' (וכענין וירש ה' על הר סיני שהר סיני עשן כו' בהעלאה למעל' ועי\"ז ירד ה' עליו מלמעל' למטה כו' שמבחי' בליטה דעל כל דבור פרחה כו' נעשה חותם שקוע שזכו לקבל י' הדברו' וכך מכתב אלקי חרות על הלוחות באותיות שקועים כו'):\n(ךז) <b>וזהו</b> כחותם על זרועך שהוא תש\"י ונק' תפלה מיושב שהוא מברכת יוצר עד סוף ק\"ש כידוע והענין הוא להיות שכל עיקר פסד\"ז וברכת יוצר עד סוף ק\"ש הוא רק בחי' העלא' מלמטה למעל' בבחי' חותם בולט כנ\"ל ומזה נעשה חותם שוקע שהו' ענין תפלה של יד שע\"כ א' ע\"ז כחותם על זרועך דוקא כנ\"ל דהנה ד' פרשיות שבתש\"י הכל הוא בבחי' בטול ושקיעה מלמטה למעלה דוקא וכנגד זה נמשך מלמעלה למט' כמו דרוח אייתי רוח כו' וכמו פ' ראשונה קדש לי כל בכור בחי' חכמה כידוע בני בכורי ישראל וכמו הבכור שנק' ראשית אונו כו' כך החכמ' נק' ראשית והן ישראל שנקראו ראשית תבואתו לפי שנקרא בכורי כו' וזה שכתוב קדש לי כל בכור שהחכמה נקרא קדש מלה בגרמיה וכמו שכתוב קדש ישראל לה' כו' והוא גם בכאו\"א מישראל בבחי' כח מ\"ה שבנפשו האלקי' כידוע ופי' קדש לי היינו שיהיה מקודש לה' מלמטה למעל' כענין תרומת כל הקדשי' כמו העשירי יהי' קדש כו' וכמ\"כ קדש ישראל לה' [כמו נוד' לאלקינו שכל ל' מור' העלאה כלפי מעלה כו'] וזהו ע\"י מצות ת\"ת דחכמה דכנ\"י נתעלה לקשר מחשבה כו' ועי\"ז נמשך מלמעלה למטה בחי' גלוי אא\"ס שבח\"ע דאוריי' מח\"ע נפק' כמארז\"ל שהקב\"ה יושב ושונה כנגדו כנ\"ל וזהו שנז' בפ' קדש למען תהי' תורת ה' בפיך ופי' בפיך מפני שהוא בחי' כלי לדבר ה' בהיותו בבחי' בטול פנימי ועצמי הנ\"ל בחי' שקיעה וע\"ז אמר למען תהי' המשכת אור א\"ס בח\"ע בפיך שיהיה דבר ה' ממש נמשך בפי הקורא ושונה והוא להיותו בחי' כלי חלל שקוע לקבל כו' וכנ\"ל דזהו בחי' גלוי והתלבשות האור דחכמ' בכלי החכמ' שהוא בבחי' שקיעה ונמצא דפ' קדש הוא בבחי' בטול והעלאה כחותם שקוע לקבל תורת ה' ח\"ע ושקיעה זו נעשה ע\"י בחי' בליטה דברכו' ק\"ש כנ\"ל וד\"ל והנה ידוע דקדש והיה כי יביאך הן בחי' חו\"ב וע\"ד הנ\"ל בפ' קדש שנמשך אור התורה מלמעלה למטה כמ\"ש למען תהיה כו' כך בפ' והיה הוא בבחי' מוח הבינה דהנה בפ' והי' כ\"י נז' יציאת מצרים ופי' מצרים ידוע שהוא מיצר ים שהוא בחי' המיצר והצמצום שמתצמצם התפעלו' האהבה בשכל והתבוננות שנק' אם הבנים וכמ\"ש במ\"א בענין בצאת ישראל ממצרים שזה בחי' לידה שהמדות יוצאים ונולדים מן השכל משא\"כ כשהן בעיבור בשכל והשגה עדיין כעובר במעי אמו נק' מיצר ים כו' והעיקר הוא על בחי' האהבה שנק' ב\"ן ולכך נק' בינה בן י\"ה שי\"ה חו\"ב המה המולידי' לבן שהוא האהב' וזהו הנק' אהבה המסותרת פי' מסותרת בעיבור בשכל והתבוננות ולא יצא לגלוי מהו' בפ\"ע בלב עדיין רק נכלל ובטל בהתפעלות שבמוח ההשגה כו' וכמו שאנו רואים בחוש במי שטרוד בשכלו באיזה עסק מו\"מ וכה\"ג שהתפעלות אהבה שבזה נכלל ובטל בהתפעלות המוח כו' (שהן מדו' שבשכל כו') והנה ידוע דחו\"ב הן פ' קדש והי' כ\"י וחו\"ג הן פ' שמע והי' א\"ש וכמו שהאוי\"ר נולדי' מן השכל וההתבוננו' בגלוי מן ההעלם בבחי' לידה כנ\"ל כך ענין ב' פרשיו' דשמע והי' א\"ששנז' בהן ב' דברים דאוי\"ר האהבה בפ' שמע ואהבת"],[1700400406,"כו' והיראה בפ' והי' א\"ש במ\"ש שם לאהבה ולעבדו בירא' וכן השמרו לכם כו' וגם לפי מאמר ריב\"ק דקדמ' פ' שמע לוהי' לפי שבוהי' מקבל עליו עול מצות ושרשם בירא' דוקא כו' ושתיהן נולדו ממוח הבינה שזהו בפ' והי' כ\"י דוקא שנז' בה יצ\"מ שזהו בחי' לידה דמדו' אוי\"ר מן השכל כנ\"ל ונמצא דב' פרשיו' קדש והיה כ\"י הן בחי' או\"א וכו' ושמע והיה א\"ש הן בחי' חו\"ג הנולדים מחו\"ב והעיקר מפ' והי' שהוא בבחי' בינה שנק' אם הבנים להיות שנז' בה יצ\"מ שהוא בחי' התולדה של המדות מן המיצר דבינה כנ\"ל וד\"ל והנה כתיב אם הבנים שמחה דמשמע שאין השמחה רק בתולדה כשהבנים כבר נולדו מבטן אמם שאז תשמח אם הבנים ולכאורה אין זה מובן דהלא כתיב אם לבינה תקרא הרי הבינה נק' אם הבנים שמחה למה אנו רואי' להיפך שעיקר השמחה הוא בהשגה והתבוננו' מצד עצם המושג דוקא גם בטרם תוליד או\"יר כלל ובקיצור המושג כשיולד בלב אין שם התפעלות שמחה מן השכל כלל וכמו שאנו רואים במי שמשיג שכל וסבר' שכל מה שישיגנ' בכי טוב טעם יותר יותר ישמח בה וכשלא ישיג היטב לא ישמח כ\"כ א\"כ השמח' בשכל עצמו הוא ואיך תלה העיקר בטפל שאם הבנים שמח' מצד הבנים שהן המדו' שבלב שנולדים רק מצמצום אור השכל וההשגה שבמוח הבינ' כידוע אך הענין הוא דיש ב' מדרגות בבינ' א' פנימי' בינה הוא עצם עומק המושג ושם דוקא בא גלוי אור העונג שבחכמה במורגש ביותר כידוע הוא גלוי התענוג והשמחה בכל הבנת השכל מצד עצמו לפי שבהבנה והשגה גמורה בפנים מסבירות בטוב טעם יותר שם יבא גלוי הענג ושמחה מורגשת ביותר משא\"כ כשאינו מבינה היטב שנשאר הענג ושמחה בהעל' כו' כמ\"ש במ\"א והב' חיצוניות בינה שהיא מקור לתולדות המדות שהן ז\"ת דבינה כשכל מטה כלפי חסד או דין שמזה יולדו המדות חו\"ג שבלב כידוע אין שם שמחה וענג רק כשהוציא השכל לאור הפסק דין לחו\"ג בלב דוקא אזי תשמח אם הבנים כו' וכמו שאנו רואים שיש שמחה גדולה בהתפעלות שמחה מורגשת בתוך האהבה שבלב שנולדה מן השכל ולכאורה מאין תמצא באהבה מאחר שלא היה בשכל המולידה כו' אך בהכרח שהשמחה הזאת באה מן ההשגה שבמוח בינה לגלוי באהבה שבלב שז\"ש פשט הענין דאם הבנים שמחה כשתוליד דוקא שתשמח האם על הבנים וזאת השמחה אע\"פ שהיא למטה מן השכל כי אינה רק שמחה שבלב מ\"מ שרשה יותר עליון משמחה שבבינה מצד עצמה עד\"מ דאם הבנים תשמח מבניה יותר משמחה שתשמח בבעל' כענין שמח תשמח רעים האהובים שזהו חו\"ב שנק' תרין רעין שמח בחכמה תשמח בבינה כענין אשה בעלה משמחה כו' אבל שוש תשיש כו' בקיבוץ בניה לתוכה יותר כו' משו' דתולדת הבנים שרשן בפנימית ועצמות דחו\"ב יותר מיחודם לצורך עצמ' כו' [וכמ\"ש במ\"א בענין אל עליון גומל כו' דבתולדה דנה\"י יש מעלה יתירה מגוף המוחי' דחו\"ב כו' וזהו לב\"ב כו') ובכל זה יובן בבנים דאם שהן בב' פרשיות דשמע והי' א\"ש שהן אוי\"ר בן ובת שנולדים מבינה שזהו בפ' והי' כ\"י כנ\"ל ששם דוקא ענין השמחה בלב שהרי בפ' שמע מאחרי שא' ואהבת הרי באהבה זאת ודאי יש שמחה בלב כידוע בכל אהבה שאינ' בלא שמחה בהתפעלות כאהבת איש לאשתו ולרעהו כנפשו שיגיל וישמח בלבו בראותו כמו וראך ושמח בלבו כו' ובפ' והיה א\"ש השמחה בעבודה שהיא היראה כמ\"ש ולעבדו וכתי' תחת אשר לא עבדת בשמחה וטוב לב הרי העבודה שביראה צריך להיות בשמחה ואע\"פ שהיראה והשמחה ב' הפכי' לכאורה אבל הרי אמרו במקום גילה שם תהא רעדה א\"כ בגילה ושמחה באהבה יש רעדה וכן להיפך ברעדה יש שמחה וגילה והענין הוא דשמחה זו שבפ' והי' א\"ש היינו בשמחה של מצוה דוקא שהמצות בעול ירא' ואימת מלך עכ\"ז ישמח במעשה במצוה שעשה נח\"ר לאדונו כו' ועל שתי השמחות דבן ובת אוי\"ר שבפ' שמע והיה א\"ש א' אם הבנים שמחה שכוללת"],[1700400407,"ב' שמחות הללו לפי שממנה מקור מוצאם ואע\"פ שאם הבנים שמחה מצד הבנים מ\"מ שמחת האם היא (והוא בא מבחי' פנימית ועצמות דבינה יותר כנ\"ל) וזהו כחותם על זרועך תש\"י דהיינו ד' פרשיות דקדש והיה כ\"י בחי' חו\"ב שמולידי' אוי\"ר שבב' פ' דשמע והי' והכל בבחי' בטול מלמטה למעלה כדי שיהי' נמשך מלמעלה למטה שהן כללות ענין ד' פרשיות דתש\"י שבזרוע השמאלי של הקב\"ה שהוא בבחי' חותם שוקע ע\"ד הנ\"ל בפ' קדש כך בפ' והיה כ\"י שמוליד המדות אוי\"ר הכל בבחי' בטול מלמטה למעלה כדי שיהיה נמשך גלוי אא\"ס בבינה ומדות מלמעלה למטה כנ\"ל וד\"ל והנה ידוע דתפילין של יד שמניח בזרוע השמאלי כמ\"ש וקשרתם לאות על ידך כו' הוא בחי' המל' למעלה שהוא ה\"א אחרונה דשם הוי' וכידוע בענין ד' אותיות דהוי' יו\"ד בחכמה ה\"א בינה וי\"ו ז\"א ה\"א בחי' מל' והן ד' פרשיות דתפלה של יד עצמה קדש בחי' יו\"ד דחכמה והיה נ\"י ה\"א בינה שמע וי\"ו בחי' ז\"א והיה א\"ש בחי' מלכות ה\"א תתאה והוא בחי' היראה תתא' עול מצות המלך כמ\"ש ולעבדו כו' (והוא מ\"ש ונתתי עשב שי\"ן ע\"ב דמל') וכתי' הן יראת ה' היא חכמה דנעוץ תחלתן בסופן בחי' ירא' תתא' עול מצות שבפ' והי' א\"ש נעוץ בתחלתן בבחי' חכמה שבתורה שבפ' והי' א\"ש נעוץ בתחלתן בבחי' חכמה שבתורה שב\"פ קדש כמ\"ש למעלה בענין ולמען תהיה תורת ה' בפיך שהוא המשכת ח\"ע דתורה שנק' ראשית כמ\"ש ראשית חכמה כך ע\"י פ' והיה א\"ש נמשך היראה בעול מצות המלך שהוא בחי' ומדרגה האחרונה ונעוץ סופן בתחלתן כו' דבחי' בטול בטול חיצוני מגיע בביטול הפנימי ועצמי דבחי' אין דמ\"ה דח\"ע דאור תורה כו' (ומ\"ש וקשרתם לאות על ידך תחלה ואח\"כ והיה לטוטפת כו' כמ\"ש שמאלו תחת כו' ית' בסמוך) והנה ידוע דהמל' נק' ג\"כ בשם צדקה צדק ה\"א כו' דפי' צדקה הוא התגלות השפע למקבל דלית לי מגרמי' כלום כמו להחיות רוח שפלי' כאשר מתקבל במקבלים נק' צדקה צדק ה\"א בחי' נוק' משא\"כ בעודנו אצל המשפיע ולא נמשך למקבלי' נק' צדיק שעושה צדקות ועדיין לא בא בגלוי כו' וכך יובן בענין מעשה המצות שהעוש' ומקיי' כל המצו' נק' צדיק כידוע בענין ועמך כולם צדיקים כו' אך גופה של מעשה המצוה נק' וכמו צדקה תהי' לנו כו' שמזה מובן דכללו' כל מעשה המצו' נק' בשם צדקה שהצדקה נק' מעשה וכמו הי' מעשה הצדקה והמצות בכלל העיקר הוא רק בחי' המעש' כמובן בכמה כתובי' אך לכאור' אין דמיון כלל למעשה זאת של הצדק' להחיו' רוח שפלי' עם מעשה המצות והענין הוא כידוע בענין המצו' דכתי' אשר יעש' אות' האד' וחי בהם הרי ע\"י המצו' נמשך חיים העליוני' להחיו' רוח שפלי' דלית לי' חיים כו' וכמו בצדקה דכתי' כן צדקה לחיים פי' כן בסיס שהצדק' נק' בסיס וכן לחיים העליוני' שעל ידה יומשך כל חיים עליוני' שבעצמו' המאציל לאבי\"ע לפי שהצדק' נמשך מצד הרחמי' שמשפיל א\"ע להרגיש בהתפעלו' רוח הנמוך שאין ערוך לו כמו העני ונבזה כו' להחיותו כו' ובאתדל\"ת עושה אתדל\"ע שיצמצם עצמות המאציל ויבא בהתלבשו' לצורך שפע העולמו' מצד הרחמנות כו' הגם שבלתי ערוך לו כלל אדרבה מזה עצמו יבא סיבת הרחמי' וכל שיותר רחוק בערך יותר יומשך ר\"ר כמו שיש בטבע הרחמים שכל שהדבר נמוך ביותר יותר ירחם כמו לרוח שפלי' ונדכאי' ביותר כו' וכך יובן במצות שיעש' אותם האדם היינו שממשיך אורו' בכלים מכלים שונים ולכך א' וחי בהם משום שזהו כמו להחיו' רוח שפלי' ממש מאחר שמצד עצמו' המאציל לאו מכל אינון מדות כלל אלא שמתלבש בע\"ס או\"כ מצד בחי' צדקה לבד והוא ע\"י המצו' שנק' מעשה שגורמי' למעלה בחי' עשי' זאת שישפיל א\"ע בכלים שונים ולכך המצו' נק' צדקה כמ\"ש וצדק' תהי' לנו ונק' מעשה כנ\"ל וכל זה אינו אלא בקבלת עול מצות בפ' והי' א\"ש דנעוץ סופן בתחלתן כנ\"ל (ולא עוד אלא שסוף מעשה דמצות עלה תחלה במחשבה ורצון שלמעלה גם מבחי' ראשית דיו\"ד דחכמ' וראי' ממ\"ש שמאלו תחת כו' כמשי\"ת ואח\"כ וימינו כו') ובכל זה יובן מ\"ש שמאלו תחת לראשי כו' פי' שמאלו של הקדב\"ה שהוא בחי' ז\"אדאצי' שע\"ז א' כחותם ועל זרועך זרועו השמאלי כמ\"ש וקשרתם לאות על ידך והקדב\"ה"],[1700400408,"כשמניח תפילין מניח תפלה של יד תחלה בזרוע השמאלי שלו כמ\"ש וקשרתם תחלה ואח\"כ והי' לטוטפת כו' תש\"ר כאדם למט' כו' וזהו שא' שמאלו ששם כנ\"י נחתם בבחי' חותם שוקע כמ\"ש כחותם על זרועך הוא תחת לראשי פי' בחי' הגבהת והעלא' המוחי' דכנ\"י שזהו ראשי דכנ\"י מגביה הקדב\"ה בזרועו השמאלי דוקא וכפשט הכתוב שמאלו מניח תחת לראשי ומגביהו כו' והיינו ע\"י בחי' חותם שוקע בבחי' בטול פנימי ועצמי שבתש\"י בד' פרשיו' שנק' חותם על זרועך עי\"ז דוק' מעלה אותן כו' וזהו לראשי אותיות ישראל כו' וזה בא הכל ע\"י בחי' בליט' החותם שבברכות ק\"ש שמן הבליטה דוקא נעשה שקיעה כנ\"ל ואחר שנעשה כחותם שוקע על זרועו ע\"ז א' שמאלו תחת כו' (וכמו הקשירה דתש\"י כנגד הלב כמו לבבתני אחותי כלה כו' וד\"ל):\n(ךח) <b>ומעתה</b> הנה יש להבין ענין החותם השני הנק' חותם הבולט כנ\"ל והוא במ\"ש שמני כחותם על לבך שהן רצועות דתש\"ר דתליין על לבא כנ\"ל דהנה מבואר למעל' בהפרש שבין ב' חותמו' דבחותם השוקע כשחותמין בו בשעוה נעשה שם אותיות בולטים ובחותם הבולט להיפך והנה מאחר שמבואר על חותם השוקע שהוא נעשה למעלה בש\"ע מבליטה דלמטה על ידי קריאת שמע וברכותי' א\"כ ודאי חותם שוקע זה שבא מלמטה למעלה בש\"ע גם הוא נעשה בחי' בולט והוא בתש\"ר (ומה שהקדים לומר כחותם על לבך בחי' בולט לפני כחותם על זרועך שוקע שלפ\"ז ראוי להקדים כחותם על זרועך שהוא השקיעה דש\"ע כו' ית' בסוף הענין) בהיות מבואר למעלה בבחי' בטול דשקיעה בש\"ע שזהו ענין ובחי' בטול הרצון בעצם מכל וכל ולא שעושה א\"ע בטל בטול היש כו' והוא ענין הכריעות והשתחוואות דש\"ע כו' שנק' בטול עצמי כו' אך לכאור' יש להבין דאם כל עיקר ענין הש\"ע אינו רק עצם הבטול פנימי שאינו בולט כלל בחיצוניות א\"כ למה צריך להראות בטול חצוני דוקא בהכרנת ראשו וגופו בכריעה והשתחוואה חיצונית דוקא כידוע אך הנה יש להקדים לזה ענין המבואר במ\"א בענין מ\"ע ול\"ת דשרש ל\"ת בי\"ה גבוה ממ\"ע בו\"ה כו' לפי שכל ענין הל\"ת אינו רק בחי' העדר לבד שזהו שב ואל תעשה דבר שנגד הרצון כמו לא תלבש שעטנז לא תאכל חלב ודם וכה\"ג והוא ענין הלאו שקודם להן דמ\"ע כו' וביאור הדבר ידוע דבמ\"ע לכאורה ההתקשרות בדבר מה שהוא בא בבחי' המשכות גלוי אור אלקי ממש כמו תפילין וציצית ושבת וכו' שקדשנו במצותיו שנמשך גלוי אא\"ס ברצונו הפנימי העצמי שבכל מצות כו' וזהו העוה\"ב להנחיל אוהבי יש ממש כו' ולמה יש יתרון מעלה למל\"ת שאינו אלא בהעדר שב ואל תעשה כו' אך הענין הוא דבהשג' קירוב אלקות יש ב' מדרגות הא' ההשגה ותפיסה במה שנמשך מהותו אחריו והוא במה שנמשך אחר רצונו הפנימי כמו מ\"ע וכן יוכל אדם להשיג אלקו' ע\"י הדביקו' בהתבוננו' ותשוק' הרצון בהתפעלו' רב כו' אך אין כ\"ז נק' השג' ותפיס' בעצם מהותו דלית מחשב' תפיס' כלל בעצמו וגם בבחי' רצונותיו הפנימי' במ\"ע אין זה מהותו העצמי עדיין וכמו עד\"מ במלך ב\"ו שיראו מה שנמשך אח\"ז ברצון פנימי עדיין אין יודעין מזה עצם מהותו ממש כו' אך במה ששנאוי בעיניו ולא יחפוץ בו ויקוץ בו ביותר מזה ידעו יותר מהותו העצמי ולא שידעו מהותו העצמי ממש רק שידעו ממנו ממה שרואין שזהו היפוכו ונק' זה ידיעה דרך שלילה מצד היפוכו לבד כמו שיכולי' להשיג במהות הרוחני כשיודעין היטב על כל היפוכו בתוארי הגשם איך שהגשם היפוך הרוחני כו' ובזה יובן ענין הלאו שקודם להן דהיינו שבלאו שהוא היפוכו כמו ל\"ת בזה יוכר יותר פנימי' עצמותו הרבה יותר מבהן דמ\"ע שנמשך רצונו שם כו' וד\"ל ויובן זה דרך קצרה שבחי' הקירוב באה\"ר וכליון הנפש ממש עדיין לא ישיג במהות ועצם אלקי' אלא רק בבחי' בטול עצמו כשנעשה כאבן דומם בלתי התפעלו' כלל בחי' בטול המציאו' שנק' קול דממה דקה כדומם ממש בלא רצון ושכל לגמרי תמן קאתי מלכא שבזה הוא נעש' כלי לגלוי עצמו' אלקי' ממש כי מצד"],[1700400409,"הרוממו' ערך אלקו' על הנברא בע\"ג א\"א שישיגנו בעצם מהותו בבחי' איזה יש ודבר מה גם ע\"י אה\"ר או מ\"ע וכה\"ג רק ע\"י בטול הרצון בבחי' שקיעה כמו העדר דל\"ת שב וא\"ת כו' בזה דוקא יכולי' להשיג בעצמו כו' וד\"ל ומענין לאו דקוד' להן בל\"ת ומ\"ע יובן ג\"כ בענין כריעו' והשתחוואו' דש\"ע דודאי לעולם גילוי אלקו' בעצמו א\"א שיהיה הקירוב אליו בש\"ע באיזה יש ודבר מה גם לא בהתפעלות רצון באה\"ר כו' או בדביקות גדולה בהשגה עמוקה כו' רק בבחי' הבטול במציאות לבד כנ\"ל ולפ\"ז יובן דבהכרח צריך להיות הבטול הזה בש\"ע שיתראה בחיצוניות דוקא כמו בגילוי תנועת כפיפת ראשו וגופו הגשמי דוקא שזהו בטול גשמי שמראה היותו כאבן דומם בלי התפשטות כלל וכלל שזה דוקא יותר מעלה מבטול הפנימי שבמוחו ולבו כמו שבטול הרצון והלב בתשוקה ואה\"ר לא ישיגו כנ\"ל כך גם בבטול המציאות אם הוא בפנימית המוח ולב גם זה לא ישיגנו כו' אלא דוקא כריעה בחיצוניות כמו לפני מלך ב\"ו שכריעה על אפים ארץ יותר ירצה בעיני המלך מבטולו הפנימי שבלבו ומוחו דכלא חשיב בעצם כו' וכמו יען כי נכנע אחאב כו' ובזה יובן עיקר ענין השקיעה שבש\"ע שהוא בחצוניות כאותיות חותם שקוע שקיעה גשמית שזהו בגופו ולבו הגשמי חלול ושקוע כמו בכריעה בברוך בראשו הגשמי דוקא וד\"ל וזהו ההפרש בין תש\"י לתש\"ר דתש\"י הוא בחי' שוקע כנ\"ל ומבחי' שקיעה דתש\"י נעשה בליטה דתש\"ר שהן בולטים על הראש כו' הנקרא חותם הבולט כנ\"ל ולהבין ביאור ענין הבליטה דתש\"ר יש להקדים תחלה ענין א' והוא המבואר במ\"א בענין אותותינו לא ראינו כו' שזהו בזמן הגלות דוקא אבל בזמן בהמ\"ק אותו' ומופתי' העליוני' היו באין בגלוי למטה וראינו בעינינו וזה פלא גדול לכאורה דהנה ודאי אנו מוצאי' שהיו ניסים ונפלאות הרבה גם בזמן הגלות כמו בזמן בהמ\"ק ונס דאסתר ומרדכי יוכיח שהי' בזמן הגלות וכה\"ג ולמה יאמר אותותינו לא ראינו בזמן הגלות דודאי ראינו בגלות כמו בזמן בהמ\"ק ראשון ושני וגם בכל דור ודור נעשו נסים ונפלאו' ה' לרבים מישראל וליחידי' כידוע ומפורסם ואם נאמר דהכונ' כך הוא דאותן נסים ונפלאות ממש שיהי' בימי' הקדמוני' ראו הכל שלא עפ\"י התלבשות בדרך הטבע כלל ונגלה לעין כל כח אלקי ממש שלמעלה מן הטבע לגמרי כקריעת י\"ס וכה\"ג משא\"כ בזמן הגלות דאותותינו שהן כמו אותן נסים ונפלאות שבימי קדם לא ראינו כמו שהן בלתי העלמה אלא הן מתעלמין ומתלבשי' בדרך הטבע כמו נס דמרדכי ואסתר שהי' מלובש בדרכי הטבע באהבת אסתר וכה\"ג וכן נס דחנוכה במלחמת בני חשמונאי אמנם גם זה לא יתישב כלל דהרי א' אבותינו ספרו לנו פועל פעלת בימי קדם וכמו שמספר אדם לבנו יצ\"מ כו' דמשמע שנסי' כאלה לא ראינו כלל רק אבותינו ספרו לנו שהי' בימי קדם וזה פלאי דודאי גם אם ההתלבשות הוא בדרך הטבע מ\"מ הרי הוא אותו הנס שהיה בימי קדם ממש וראיה לדבר ממה שחייב אדם לבר' על הנס שנעש' לו לבדו במקו' שניצול כו' גם אם הי' הנס מלוב' בטב' אבל בחי' השגחה אלקי' הי' כו' אך הענין הוא כידוע בענין עלמא דאתכסיא ועלמא דאתגליא כו' דאלקי' גי' הטבע היינו מה שהנס נעשה בהתלבשות דרך הטבע ממש שהטבע מסתיר עליו לגמרי כאילו יוכל לומר טבעיות הוא לגמרי ואמנם כאשר כח האלקי הוא המושל על כחות הטבע לשנותם מהיפוך להיפוך כמו מי שא' לשמן וידליק יאמר לחומץ כו' זהו בחי' ההארה וההמשכה מעלמא דאתכסיא שמאיר בעלמא דאתגליא והוא הנק' נס נפלא ומחודש להיות שבחי' אין עצמו שלמעלה לגמרי מן הטבע נראה בעולם הטבעי בבחי' אור חדש ונפלא ע\"כ הכל תמהין עליו ומתפעלי' ביותר אבל כמו שהאור הזה עצמו במקומו אינו נפלא ומחודש כלל וכלל כמו החידוש דמקום ארון אינו מן המדה שבשטח מקום לא יתפס הארון מקום הגם שהארון עצמו נתפס בגדר ושטח כו' וכה\"ג בכל הנסים ונמצא הרי מלובש אור האלקי"],[1700400410,"שלמעלה מן הטבע בחי' אין עצמו בלבוש זה שהוא דבר שנעשה בו הנס שהוא מעולם הטבע אע\"פ שאינו מסתיר אלא אדרבה נגלה בו רק שאין זה גלוי עצם האור כמו שהוא למעלה במקומו רק אור המתנוצץ דרך נקבי המסך שהאור הבוקע הזה מחודש לעין הרואה לבד וכמ\"ש במ\"א שזהו ענין נצוצי אורות החסדים דשם הוי' שבוקעי' בשם אלקי' כמו כ\"ו כל\"ח כידוע וזהו ההפרש בין זמן הגלות לימי קדם שבימי קדם היה בא גלוי אור העליון למטה כמו שהוא בלי העלם ולבוש שיתראה בו ועל ידו כמו מנוח שראה מלאך ה' במהותו כמו שהוא במקומו וכן הנביאי' במראות אלקים כו' וכך היו כל הנסי' שפעל בימי קדם אשר אבותינו ספרו לנו שראו האור דעצמות כמו שהוא משא\"כ עכשיו אותותינו אלה ממש מלובשים במראה ודמות שבזה העולם שבו נעשה הנס אע\"פ שיוצא מגדרי הטבע ונק' נפלא מ\"מ אינו נראה בעינינו כמו שהוא בעצם ממש כו' ובזה מתורץ הקושיא הנ\"ל וד\"ל והנה עפ\"י אופן זה יובן ג\"כ בענין השקיעה והבליטה דתש\"י ותש\"ר הנ\"ל דהנה ע\"ד הנ\"ל בנסים ואותות יש הפרש כללי כזה בין גלוי אלקות למטה עכשיו בין גלוי אלקות למטה לע\"ל דעכשיו ג\"כ יש גלוי הוי' סובב כ\"ע באלקים ממלא כ\"ע כמ\"ש כי ה' הוא האלקים אך זהו בא דרך הארה והתלבשות בשם אלקי' כנ\"ל אבל לע\"ל כתיב ונגלה כבוד הוי' שיתגלה למטה כמו שהוא למעלה ממש בלי שינוי המהות ובלא התלבשות ע\"י שם אלקים כלל וכמארז\"ל שיוציא חמה מנרתקה שזהו כמו שמש ומגן ה' אלקי' דאלקי' נרתק לשם הוי' כו' וכן נא' לע\"ל ולא יכנף עוד מוריך והיו עיניך רואות כו' בחי' ראי' זו שלא ע\"י לבוש אמצעי כלל וכלל וד\"ל וע\"ד כל זה יובן בהפרש שבין שקיעה לבליטה הנ\"ל דתש\"ר הוא כמו חותם הבולט דהיינו שהוא בולט בגלוי כמו שהוא בעצם בלי לבוש וכלי שעל ידו יאיר כו' (וכמ\"ש וראו כל ע\"ה כי שם הוי' נק' עליך דוקא בבחי' בליטה ע\"ג הראש דבמוחי' שבראש יש או\"כ חלל המוחים וגופי המוחי' שהן כלים לאורות כמ\"ש בזהר פ' ואתחנן באריכות וע\"פ שד' בתים דתפילין ג\"כ הן כדוגמתן בחלל ובית קיבול לפרשיות והפרשיות עמן כלים מכלים שונים לאורו' דאו\"א וזו\"נ כנ\"ל בתש\"י היינו דוקא בתש\"י שבזרוע השמאלי שצריך להיות בהצנע בלתי מגולה כמ\"ש לך לאות ולא לאחרים לאות כו' אבל תש\"ר נהפוך הוא שצריך שיהיו מגולי' לכל עין רואה שהרי הוא בבחי' בליטה ע\"ג המוחי' כו') וביאור זה הדבר הנה יובן ממה שמבואר למעלה בענין חותם שוקע למעלה שזהו בתו\"מ שבאין האורות בבחי' התלבשות בכלים מכלים שונים כנ\"ל בד' פרשיות דת\"שי דפ' קדש הוא להמשיך בחי' גלוי אא\"ס בח\"ע כמ\"ש למען תהיה תורת ה' בפיך כו' וכחותם שוקע לקבל כך בחי' דבר ה' שמדבר הוא אותיות שקועין בחי' חלל בית קיבול לקבל גלוי אא\"ס שבחכמה כשהקדב\"ה יושב ושונה כנגדו כו' הרי עכ\"פ יש בחי' לבוש אמצעי להלביש ולהכיל לגלוי אא\"ס שבו והוא בחי' החכמה שבדבר ה' זו הלכה כו' מאחר שהדמיון הוא כמו אותיות שקועים שמוסתר בהן האור כו' וכידוע דגם כללות בחי' חכמה עילאה דאור תורה בחי' לבוש הוא שמתלבש בה עצמות אא\"ס ב\"ה וכמ\"ש עוטה אור כשלמה (שאע\"פ שהשלמה ולבוש זה הרי אינו בחי' מסתיר כלל כנ\"ל בענין לבושיה כתלג כו' בפ' ציצי' מ\"מ בחי' כלי ואמצעי הוא שעל ידו יאיר עצם אורו כו') וכך הוא ג\"כ בכל המצות מעשיות שנק' רמ\"ח אברי' שזהו כמשל אברי האד' שהאו' וחיו' נמשך ומתקבל בכלי האבר הרי מוסתר ונעלם בכלי כו' וכמו מצות ציצית שבחוטין וטלית הן בחי' כלי ולבוש שעל ידן יאיר אור ל\"ב נ\"ח וכן מצות סוכה בחי' מקיפי' עליוני' דאימא שמתלבשי' ומאירי' בסכך כו' וכך כל המצות (כי מצוה בחילוף א\"ת ב\"ש שם הוי' מ\"צ הוא י\"ת שנעלם בלבוש מ\"צ ולע\"ל יתגלה כמ\"ש במ\"א( אך הנה לע\"ל נא' ולא יכנף עוד כו' כנ\"ל שלא יבא עוד בלבושי' דמצות מעשיות אלא עיניך רואות כו' פי' בחי'"],[1700400411,"עצמות אור האלקי כמו שהוא במצות בחי' רצונו הפנימי והעצמי שבהן יהיו עיניך רואות בלי לבוש אמצעי שעל ידו יאיר שהוא גופה של מעשה המצוה וכמ\"ש דוד בפקודיך כו' ואביטה אורחותיך ארחין דגלגלתא דא\"א כו' שהן פנימי' רצונו שבמצות כמו שהן למעלה [אך הנה אמרו שכר מצוה מצוה עצמה פי' שכר מצוה הוא הנהנה מזיו ואור העליון הפנימי שגנוז במעשה זאת דמצוה כנ\"ל ומעשה המצוה עצמה שהוא לבוש מכסה יותר גדול מן השכר עד שגזר אומר דשכר מצוה הוא המצוה עצמה שבפ\"מ כמו עכשיו דשכר מצוה בהאי עלמא ליכא גופה של מצוה בפ\"מ זהו שכרה כו' וזה פלא לכאורה אך האמת הוא שזהו ההפרש בין ימות המשיח לעוה\"ב דבימה\"ש יתגלו טעמי מצות הנגלות לנו ע\"י משה כנ\"ל בענין יבא טוב כו' שזהו כמו בחי' אותיות חותם בולט דתש\"ר כנ\"ל אבל עוה\"ב דעצמות אא\"ס שלמעלה מרצונותיו הפנימיי' יתגלה אין לו כלי רק דוקא גופה של מעשה המצוה שלמטה בפ\"מ משום דסוף מעשה דוקא עלה לפני תחלת הרצון כו' ולכך גזרו אומר דכ\"י יש להם חלק לעוה\"ב מצד גופי המצות בפ\"מ גם בלי כונה כלל] וזהו ענין תש\"ר שהוא כמו חותם הבולט דהיינו בחי' גילוי עצמות האור האלקי שבא בבחי' בליטה כמו שהוא בעצם ולא כמו שהשקיעה היא בחי' כלי וחלל לקבל ולהעלים כו' כי זהו כמ\"ש לע\"ל ולא יכנף עוד כו' ואע\"פ שבודאי העוסק בתורה ממשיך אא\"ס בחכמ' אבל היא בחי' כלי ולבוש כנ\"ל ולע\"ל יהיה גלוי זה עצמו בלי כלי ולבוש כו' וכך הוא ענין דתש\"ר שהן בבחי' בולט בלי כלי מקבל כו' (שהוא בחי' דכר האור עצמי בלא כלי קיבול כו') וזהו ענין בליטת חותם דתש\"ר שבא אחר בחי' השקיעה דש\"ע הנ\"ל וכמ\"ש למעלה שמבחי' שקיעה דלמטה נעשה בחי' חותם בולט למעלה שזהו תש\"ר כנ\"ל וד\"ל:\n(ךט) <b>וזהו</b> שימני כחותם על לבך וארז\"ל מנין שהקב\"ה מניח תפילין כו' ותפילין דמארי עלמר מה כתיב בהו ומי כעמך ישראל כו' ויש להבין לכאורה דמה ענין ישראל בתש\"ר שהקב\"ה מניח כו' ולפי הנ\"ל דכחותם על לבך היינו תש\"ר שלו זהו שנז' שם ישראל והיינו מצד בחי' הבטול רצון ושכל כו' בבחי' שקיעה דלמטה שמזה נעשה בחי' בליט' דתש\"ר למעלה לכך בתפילין דמארי עלמא נאמר מי כעמך ישראל דוקא וזהו מטעם שישראל עלה במחשבה בחי' מקיף בתש\"ר כו' שלכך נק' גוי אחד בארץ כמו שהוא יחיד ואח\"פ למעל' כו' וד\"ל אך הנה עיקר ענין מה שאמ' שהקב\"ה מניח כו' זהו בחי' סובב כ\"ע בכלל ע\"ד הנ\"ל בענין שמתעטף בציצית כמ\"ש לבושי' כתלג כו' כך הוא מניח תפילין והיינו בחי' המשכת אורות מקיפי' מעצמות אא\"ס בתש\"ר שלו שמניח שהוא בא בבחי' בליטה וגלוי אור העצם כמו שהוא בלי התלבשו' בכלי ולבוש המעלים כאורו' פנימי בכלים כשאר מצות אלא כמו לע\"ל דכתיב ולא יכנף עוד כו' כנ\"ל באריכות והיינו כמו תש\"ר למטה שע\"ז נאמר כי שם הוי' נק' עליך דוקא כמו שהוא למעלה כו' ולכך נק' התפילין פאר כידוע וד\"ל והנה מעתה יש להבין ענין רצועות דתליין על לבא כנ\"ל שע\"ז א' כחותם על לבך דוקא ולא א' כחותם על ראשך שהן תש\"ר עצמו הבולט ע\"ג הראש דהנה עיקר ענין החותם הרי הוא בא בבחי' אותיות בין שהוא חותם שוקע או בולט העיקר הוא אותיות החותם ויש להבין תחלה שרש האותיות כו' והוא בבחי' האותיות שנכתבים ע\"ג הקלף בד' פרשיות דתפילין שידוע דכל אות ואות הוא בחי' המשכה מיוחדת באופן מיוחד בפ\"ע כל א' נבדל מזולתו רק שנצטרפו בצרוף תיבה א' ולכך אסור להיות דבק ונגיעה אות באות שהנגיעה והדבק מבלבל המשכת כל אות כמו שהוא ולא עוד אלא שצריך להיו' ריוח פנוי מכל צדדי האות מכל רוחותיה וכמ\"ש ז\"ל דכל אות שאין גויל מקיף לה מד' רוחותיה פסולה והענין הוא דהאות עצמו הוא בא בבחי' המשכת אור פנימי באופן מוגבל בשחור ולבן שבתוכו"],[1700400412,"כמ\"ש במ\"א והגויל המקיפו מכל צדדיו הוא בחי' המקיף שלו שמקיף לאותה ההמשכה שבו כו' כי הנה הגויל שהוא עור הקלף לבן פשוט וחלק בלי אותיות כי הוא עצמי ואותיות הדבוקים עליו הוא מדבר נבדל כדיו שנכתב על הקלף הפשוט (ולא כאותיות החקוקים בחותם שהן עצמיים כו') ומוחק וכותב וחוזר ומוחק כו' וכל זה אין שנוי בגופו של קלף שלמעלה מתואר האותיות הכתובים אמנם הרי הקלף הוא סובל ונושא עליו כל תוארי האותיות הנכתבים עליו כולם יחד בשוה כו' וע\"כ נק' הקלף מקיף היולי שמקיף לכל האותיות בכללה וגם ממילא מם הקלף נעשה בחי' מקיף בפרט לכל אות ואות כי האותיו' מפורדי' מטעם שכל א' מור' על המשכ' בפ\"ע והגויל המקיף לה הוא בחי' המקיף של זה האות מכל ד' רוחותיה כי הגויל מקיף בכלל להיותו העצם הפשוט הסובל עליו הכל ולכך כל אות שאין גויל מקיף לה מד' רוחו' פסולה לפי שבמקום הנגיעה והדבק באות הסמוכה אין שם הקפת הגויל שהוא המקיף בפרט לאות זה ואין לאות זה על מה לסמוך בעצ' מקור מקום מעמדו ומחצבו כו' וד\"ל וכך יובן למעלה בבחי' אותיו' שבפרשיו' דתפילין למעלה שהגויל הוא הקלף שלהן הוא בחי' מקיף העליון הפשוט בתכלית וסובל כולם וכל אות יש לו מקיף בפרט מכל ד' רחותיו שהוא מקור מעמד זה האות ולכך כל שאין גויל מקיף לו מד' רוחותיו פסול כנ\"ל וד\"ל ומעתה יש להבין בענין הרצועות דהנה הרצועות אע\"פ שהן נמשכין למטה על לבא ואינן אלא כטפילין לגבי תש\"ר עצמו ללבוש על ידן התש\"ר להדקן בראש ונק' תשמישי קדושה כו' מ\"מ הרי הן נעשו' מעור בהמ' כמו הקלף הנק' גויל שבהן האותיו' דפרשיות נכתבי' רק שקלף דפרשיות מעובד ולבן ורצועו' שחורו' הל\"מ כו') דהיינו בבחי' מקיף ג\"כ וזהו שהרצועות תליין על לבא בבחי' מקיף על הלב דוקא והענין הוא בהיות שבתש\"ר עצמו הרי הגויל הוא בחי' מקיף שלמעלה מבחי' האותיות דפרשיות כנ\"ל דהנה האותיות דד' פרשיות דתש\"ר הוא ענין בחי' חותם הבולט הנ\"ל שזהו בחי' בליטה דתש\"ר שבו גלוי עצמות אא\"ס בא למעלה מבחי' התלבשו' אורות בכלים אלא גלוי האור כמו שהוא בעצם בלי כלי מקבל כנ\"ל וזהו עיקר ענין ד' פרשיות דתש\"ר שמניח הקב\"ה בראשו כו' כנ\"ל אך החי' המקיף של הד' פרשיות שבאין בבחי' אותיות הוא הגויל והקלף מטעם הנ\"ל וממדרגה זאת נמשך גם ברצועות דתש\"ר שהן מעור בהמה ג\"כ שהקלף דפרשיות נעשי' ממנה כנ\"ל ולהיות כי הרצועות ג\"כ מהמקיף דקלף הפרשיות ע\"כ תליין על לבא בבחי' מקיף שלמעלה מבחי' אותיות דחותם (כי הלב הוא מקבל מן המוח כידוע הטעם שנק' לב לפי שמקבל מל\"ב חדרים שבמוח שהן ל\"ב נ\"ח כו' שנחלקים ע\"י הדעת כמ\"ש ובדעת חדרים ימלאון כו' וזהו בבחי' או\"פ שבמוחים דחו\"ב כו' הוא שמתיישב בכלי הלב בהתפעלות לפי הכלי כמו שאנו רואים בהתפעלות הלב שנולד מהתפעלות השכל שבמוח ממש אם לאהבה או לירא' ופחד כו' אבל בחי' מקיפים דמוחים דחו\"ב לא יתיישב בכלי הלב בהתפעלות מורגשת אלא בבחי' מקיף על הלב מלמעלה וענין מקיף המדות ידוע כמו אה\"ר שבין איש לרעהו אע\"פ שכבר נשכח מאתו מרוב הזמן עדיין נשאר בחי' המקיף של אהבה שנק' אה\"ר בהעלם למעלה מגלוי שלה באו\"פ בכלי הלב וזהו הנמשך ממקיפי' דחו\"ב המולידי' המדות כו' וגם כאן ברצועות דתליין על לבא בבחי' מקיף על הלב היינו להיותם נמשכי' ממקיפי' דד' פרשיות דתש\"ר כנ\"ל וד\"ל) וביאור הדבר הנה ידוע דשרש האותיות הוא בבחי' בינה שנק' פתוחי חותם כו' שכל השגה במורגש יעשה אותיות במחשבה בהכרח וגם בפנימית ההשגה דבינה שמקבלת מחכמ' שנק' מאין ליש כידוע עכ\"פ יש ודאי מקור לאותיות דבינה אבל בבחי' הרצון שלמעלה מן השכל לגמרי אין שם גם מקור לאותיו' והוא כמו אה\"ר שברצון בעצם שאינו מוגבל כלל בבחי' אותיו' השגה כלל רק אור פשוט ועצמי"],[1700400413,"והוא הנק' מקיף דחו\"ב וכמ\"ש כצנה רצון תעטרנו כידוע והוא ענין הקלף והגויל דפרשיות כנ\"ל ומשם נמשך בחי' רצון במדות ג\"כ בבחי' מקיף על המדו' שבלב הנק' רעותא דלבא שלמעלה מבחי' אותיות ההשגה והטעם שבמדות שמקבלי' מהמוח כו' והוא הנק' מקיף על הלב וכנרא' בחוש שהרצון שבלב למעל' מהתפעלו' או\"יר שבלב שנולדי' מן השכל כי או\"יר שנולדי' מן השכל יש להו הפסק וביטול כשיבוטל הטעם ורצון הלב אין לו ביטול להיותו מהרצון שלמעלה מן הטעם לגמרי כו' וד\"ל ולהיות כן א\"א שיבא בחי' מקיף דרצון הלב בבחי' אותיו' עדיין ולכך אה\"ר זו שברצון הלב הוא שורה על הלב בבחי' מקיף כי או\"יר שבלב שנולדו מהשכל לא יכילו כלל לאור אה\"ר זאת שברצון הלב וז\"ש וימינו תחבקיני פי' עד\"מ מחיבוק שמחבק אדם לחבירו מבחוץ שלא נכנס הארת אור אה\"ר זו שבחיבוק בתוך לבבו רק מקיפו מבחוץ ותועלתו הוא שע\"י חיבוק הזה שורה עליו אה\"ר בבחי' מקיף על לבו לבלתי יוכל להפריד בלבו דגם שלבו ירצה לפרד לא יניחנו המקיף דחיבוק הזה לעולם והיינו ענין רצועות דתליין על לבא בבחי' מקיף על הלב כימינו תחבקני כו' שלא יבא הלב לידי פירוד כו' וזהו כחותם על לבך בבחי' מקיף כמשל החיבוק כנ\"ל ושמאלו תחת לראשי הוא מ\"ש כחותם על זרועך כנ\"ל וד\"ל אך הנה באמת כל זה סותר לפשט הכתוב דמ\"ש שימני כחותם על לבך כחותם ממש קאמר שבא באותיות דוקא והוא באותיות בולטין כחותם הבולט עכ\"פ ואיך נאמר שזהו בחי' מקיף על הלב ברצועות דתליין על לבא כנ\"ל שהוא דוקא למעלה מבחי' אותיות דא\"כ מה זה שאמר כחותם על לבך אין זה כחותם רק בחי' מקיף לבד כענין וימינו תחבקני כנ\"ל:\n(ל) <b>אך</b> הנה בזהר א' ע\"פ שמיני כחותם על לבך כהאי חותמא כו' משום דאע\"ג דאזיל הכא והכא דיוקני אשתאר בך ופי' אזיל הכא והכא מבוא' במ\"א בענין אך בצלם יתהלך איש דצולמא דב\"נ קאים עליה תדיר כו' והוא בחי' מזלי' חזי דהיינו שרש נשמתו למעלה והוא שנק' דיוקנא שנשאר דבוק תמיד למעלה ואע\"ג דט\"ס דנפש האלקי' מחכמ' ולמטה אזיל הכא והכא בהתלבשות ברהיטי מוחי' כו' בנה\"ב בכל צרכי גופו ועסקיו כל היום מ\"מ בחי' כתר שבה דבוק למעלה וזהו דיוקני אשתאר בך ממש (וכך יובן בכללו' נ\"י שהוא בחי' מל' למעל' דכתר מל' דבוק תמיד למעלה) וז\"ש שימני כחותם על לבך שחקוק דיוקני ואשתאר בך לעול' כמו עד\"מ ב' או\"נ בנפשם שדיוקן וצלם דנפש איש חקוק בלוח לבו של חבירו כך לשמות ישראל חקוקות תמיד בלוח לבו של הקדב\"ה שהוא בחינת ז\"א כו' אע\"ג דאזיל הכא והכא בגלותא בשיעבוד פרנסה מ\"מ שרש עצם רצונם חקוק ודבוק בלבו למעל' כו' ולפ\"ז בחי' חותם זה שעל לבך דדיוקנא אשתאר שם היינו בבחי' חקיקה באותיות שקועי' דוקא כמו שאדם חוקק בלבו אהבת רעהו כנפשו ולמעלה מבואר שז\"ש כחותם על לבך חותם הבולט הוא אלא צריך לומר דבחי' בטול הרצון בעצם בכנ\"י הנק' שקיעה כנ\"ל הוא העושה בחי' בליטה בחי' חותם בולט בלבו וזהו מ\"ש דיוקני אשתאר בך לא בבחי' חקיקה אלא ששקיעה דלמטה עושה בחי' אותיו' בולטו' (כאותיו' שמות השבטי' על חשן המשפט על לבו של כה\"ג) וזהו שימני כחותם שיהי' בולט ולא כחותם בולט שנעשה ממנו שוקע (והפשוט מורה כך שיהי' בליט' אור הנשמה חקוקה למעלה) ובזה יתורץ ענין הנ\"ל דברצועות דתליין על לבא אין הכונה רק ששם עולות כללות הנשמו' כמ\"ש דיוקני אשתאר בך וא\"א שיבאו שם בבחי' או\"פ כי עליות שלהן בבחי' בטול הרצון שהוא מקיף דא\"ח כו' אלא הן שם בבחי' מקיף ולא מקיף ממש שלמעלה מאותיות אלא שאותיות זה החותם הבולט נמשך ממקיף זה וזהו על לבך ומ\"מ כחותם באותיות והוא אותיות בולטים מן המקיף דהיינו מן הרצועות דתליין על לבא נעשה כחותם בולט על לבו של הקב\"ה משום דדיוקנא דכנ\"י אשתאר שם בהעלם ומקיף וכדוגמא זאת יהיה לע\"ל דכתיב ולא יכנף עוד כו' ואמר ביום ההוא הנה אלקינו זה כל א' מרא' באצבע כו' אע\"פ"],[1700400414,"שזהו בחי' אור מקיף שבא לגלוי לכל ולכל א' כפי מדרגתו לפי שבא בבחי' אותיות כו' והוא ענין וימינו תחבקני על כל אחד ואחד לפי מדרגתו שזהו ענין הרשימו בהעל' שנשאר אחר התפלה הגם שכבר חלפה ועברה התפעלות אהבה כו' לבלתי יוכל להפרד כנ\"ל מצד דיוקן החותם של נשמתו למעלה על לבך דאשתאר בך וכמ\"ש כי עזה כמות אהבה וד\"ל ובכל זה מובן המשך הפסוק הזה דשימני כחותם על לבך כחותם על זרועך דבקשת כנ\"י שתהי' כחותם על לבו של הקדב\"ה בתש\"ר וברצועות דתניין על לבא כנ\"ל וכמ\"ש וימינו תחבקיני וכחותם על זרועך שהוא בחי' תש\"י שמניח בזרועו השמאלי שע\"ז א' שמאלו תחת לראשי כנ\"ל ע\"י ק\"ש וברכותי' שמבחי' בליטה בהתפעלות ברעש באוי\"ר כו' נעשה בחי' שקיעה למעלה בש\"ע ומשקיעה נעשה בליט' בחותם על לבך כו' כנ\"ל (וש\"ע הוא הממוצע בין בליטה דלמטה לבליטה דלמעלה דבק\"ש באוי\"ר בחי' בליטה דלמטה כנ\"ל ובש\"ע הוא השקיעה ומזה נעשה החותם בולט למעלה ולפ\"ז לא יתיישב במה שא' שימני כחותם על לבך ברצועו' כו' כשקורא ק\"ש קודם ש\"ע דלפ\"ז בליטה דלמעלה קודם לשקיעה דלמטה אך באמת בש\"ע נעשה שקיעה למעלה כנ\"ל) אך עדיין אינו מובן סדר הפסוק הזה מה שהקדים המאוחר ואיחר את המוקדם דלפי כל הנ\"ל הל\"ל תחלה כחותם על זרועך שהן תש\"י ואח\"כ כחותם על לבך שהן תפילין של ראש מאחר שמבליטה דלמטה בק\"ש וברכותי' נשעה כחותם על זרועך תחלה שנק' תפלה מיושב כנ\"ל ואח\"כ נעשה כחותם על לבך ברצועו' דתליין על לבא כנ\"ל ואיך הקדים המאוחר שהוא כחותם על לבך כו' ועוד דאין זה כסדר המניח תפילין שמניח תש\"י תחלה וכמ\"ש וקשרתם לאות על ידך והדר לטוטפת כו' כידוע ולפי סדר הפסוק הזה דכחותם על לבך תחלה מניח תש\"ר תחלה כו' וכן לפי סדר הפסוק דשמאלו תחת לראשי תחלה שהוא תש\"י שמניח הקדב\"ה בזרועו השמאלי כנ\"ל ואח\"כ וימינו תחבקיני בחי' תש\"ר היפך סדר של הפסוק דכחותם על לבך כו' אמנם הנה באמת זה הפסוק דכחותם על לבך שמדבר בהנחת תפילין שהקב\"ה מניח שנק' תפילין דמארי עלמא כנ\"ל הוא היפך הנחת תפילין דלמטה שהאדם מניח דכתיב וקשרתם לאות כו' תש\"י תחלה ואח\"כ תש\"ר משום דמלמטה למעל' מכנ\"י שהן בחי' מקבל מאור האלקי בד' פרשיות דתפילין וכמ\"ש כי שם הוי' נק' עליך צריך להיות הסדר כך דוקא בתש\"י תחלה כנ\"ל אבל מלמעלה למטה שזהו ענין הנחת תפילין למעלה שהקב\"ה מניח התפילין הסדר בהיפוך שמניח תש\"ר תחלה ואח\"כ תש\"י שהרי לא א' רק לכנ\"י דוקא וקשרתם לאות תחלה כו' אבל כשהוא בעצמו מקיים מצות תפילין מניח תש\"ר תחלה ואין זה פלא כלל שהרי גם גופו של תפילין אין תפילין שלו בד' פרשיו' דקדש כו' כתפילין שלנו אלא תפילין דמארי עלמא מה כתיב בהו בהו ומי כעמך ישראל כו' מפני שישראל עלה במחשבה שבראש בתש\"ר תחלה כו' וביאור הדברים יובן מענין ההפרש הידוע בין עכשיו לע\"ל דעכשיו מאתדל\"ת אתדל\"ע דכל מה שנתעור' ונמשך אור ושפע מעצמות המאציל באבי\"ע הכל תלוי במעשה התחתוני' באתעדל\"ת מלמטה למעל' לפי אופן העלא' מ\"ן כו' אבל לע\"ל יהי' גלוי אלקות למטה כמו למעלה בשוה ולא מצד אתדל\"ת כלל אלא מצד עצמו בלבד כמו שהי' בתחלת ההשתלשלו' שהי' חפץ חסד מצד עצמו שלא מצד אתדל\"ת כלל וכלל וכמ\"כ יובן בענין ההפרש בין תפילין דכנ\"י שזהו באתדל\"ת מלמטה למעלה דכתיב שמאלו תחת כו' תש\"י תחלה להעלות את כנ\"י וכן וקשרתם לאות כו' תחלה כדי שיהי' אח\"כ בחי' ההמשכה מלמעלה למט' בתש\"ר דהיינו וימינו תחבקני כו' ע\"י רצועות כו' וכל זה כנשמו' שבגופי' הוא שמצות הנחת תפילין שלהם ב\"ד מוחי' קדש והי' כ\"י שיומשך עליהם מלמעלה ע\"י אתדל\"ת תחלה בתש\"י בד' פרשיו' דקדש בבחי' שקיעה בחותם שעל זרועיו שמאלי תחלה כו' אבל מצות תפילין שהקב\"ה מניח הוא כמו לע\"ל אתדל\"ע מצד עצמו כי חפץ"],[1700400415,"חסד הוא שא\"צ העלא' בתחלה כלל כו' אדרבה התעוררות מעצמו דוקא וזהו שמניח תש\"ר תחלה ומה כתיב בהו ומי כעמך ישראל כו' דהיינו מה נמלך בנשמתן ש\"צ דמזה היה לו חפץ חסד מעצמו וכמ\"ש חפצי בה כי תהיו אתם ארץ חפץ היינו חפץ ורצון עצמי פשוט שמחמת זה עלה ברצונו מצד עצמו להאציל ואין זה נק' העלא' מלמטה מאחר שלא היו נשמות למטה עדיין בבחי' בריאה מאין ליש כלל רק עצמיות התקשרות בשרש דישראל שעלה במחשבה כו' זהו לא נק' העלאה כו' וז\"ש ומי כעמך כו' גוי אחד בארץ למטה למהוי אחד באח\"פ כו' ולכך מניח תש\"ר תחלה ומתש\"ר ברצועות דתליין על לבא נמשך לתש\"י שבזרועו השמאלי מלמעלה למטה לכנ\"י שהן מקבלים משמאלו כמ\"ש שמאלו כו' והוא כשקושר תש\"י כנגד לבו ולכך הקדים כחותם על לבך תש\"ר תחלה ואח\"כ כחותם על זרועך כמו לע\"ל וד\"ל (אך כנ\"י מבקשת שימני בגלותא דוקא דדיוקני אשתאר בך אע\"ג דאזיל הכא והכא כו' הענין הוא כידוע בענין חותם המתהפך מימין לשמאל ומשמאל לימין בסדר האותיות כו' כך כנ\"י שעולה דיוקן שלה כחותם מלמטה למעלה ואשתאר למעל' הרי נהפך למעלה מן המוקדם נעשה מאוחר והמאוחר נעשה מוקדם ולכך החותם שנעשה למעלה תש\"ר קודם לתש\"י וזה נעשה מהעלאת מ\"ן דכנ\"י בגלותא בהיפך תש\"י קודם כו' והיינו הענין הנ\"ל בהפרש דעכשיו בגלו' לע\"ל אבל הא בהא תליא והיינו אך ממש וד\"ל):\n(לא) <b>ולהבין</b> בתוס' ביאור ענין ב' חותמות הנ\"ל הנה באמת אין הענין כנ\"ל דמבליטה דלמטה נעשה שקיע' למעלה כמו שחותמין בחום בולט שנעשה שוקע (וכן להיפוך כו') דאם הי' פי' כחותם על לבך כפשוטו כמו שנחתם בחותם ממש על לוח כו' ודאי הי' הענין כך דמאותיות בולטים נעשה שוקעים כנ\"ל אבל ענין שימני כחותם כו' הוא בדרך העלאה והמשכה קאמר משום דרוח אייתי רוח ואמשיך רוח רוח כמוהו ממש וכמו אם ישים אליו לבו כו' [והיינו כאשר דיוקני אשתאר בך שאז ממילא נזכר גם הוא ונמשך רוח לבבו כרוח העולה ממש כמים הפנים כו' וה\"ז כמו ב' או\"נ בנפשם שמפני שרוח לב זה קשור ברוח לב זולתו אייתי ואמשיך רוח חבירו אליו תמיד משא\"כ בלתי או\"נ בנפשם דדוקא בבחי' אתדבקות רוחא ברוחא מעורר זה לזה וכמ\"ש במ\"א בענין השיבנו ה' כו' אם תעירו ואם תעוררו כו' וכמ\"כ עד יערה עלינו רוח ממרום] ויובן דבר זה בהקדים הידוע בענין ב' מדרגות בעבודה בחי' רצוא ושוב כמו והחיות רו\"ש כו' ובחי' רצוא זהו ענין כחותם על זרועך שנעשה בבחי' שקיעה מבליטה דלמטה כנ\"ל אבל לא כפי המבואר למעלה דנתהפך להיות שוקע אלא אדרבה כמו רוח העולה מלמטה בבחי' רצוא שהוא בולט כהר כו' כנ\"ל בהתפעלות ברעש יש מי שאוהב ברשפי אש מורגש רוח העולה כאש שזהו בחי' חותם בולט דוקא כנ\"ל הנה רוח הזה התחתון עולה למעלה ואייתי ואמשיך רוח מלמעלה ממש כמו רוח זה התחתון העולה ג\"כ בבחי' בולט מלמעלה ממש כמו רוח זה התחתון העולה ג\"כ בבחי' בולט מלמעלה רק ע\"י התעוררות רוח התחתון דהיינו כמו שמהתעוררות אהבה שנק' הר מלמטה למעלה אייתי ואמשיך רוח אהבה אהבה עליונה מאצי' לבריא' והרי לפי אופן רוח העולה שמעורר כך יתעורר רוח הנמשך מלמעלה כמוהו ממש כמו יהי חסדך ה' כאשר יחלנו לך מלמט' לא יוסיף ולא יגרע כו' (כמו השאלה שמשיבין לפי אופן השאלה לבד כמ\"ש במ\"א בענין תלמוד המחכים את רבו) ולפ\"ז רוח העליון שנמשך כמים הפא\"פ כן לב האדם כו' בא למטה בבחי' בליטה כמו רוח התחתון שנתעורר מחמתו א\"כ למה נק' כחותם על זרועך שהוא תש\"י בחי' חותם שקוע כנ\"ל הענין הוא דאין פי' כחותם על זרועך שלמעלה הוא זה החותם השוקע אלא שכנ\"י תהי' כחותם שקוע לקבל אור האהבה העליונ' שנמשך מלמעלה בבליטה כדוגמת רוח התחתון שמחמתו בא כנ\"ל והיינו ענין התלבשות האורות בכלים שהכלים מגבילים"]]});
